INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C1','math',3,2,'u2',2,'곱셈구구로 몫 구하기와 (몇십) ÷ (몇) 내림 없음 — 나누는 수의 단에서 몫을 찾고, 몇십은 10 카드 몇 장으로 보아 (몇) ÷ (몇)의 몫을 10배 하기',ARRAY['4수01-06']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C2','math',3,2,'u2',3,'(몇십) ÷ (몇) 내림 있음 — 십의 자리를 나누고 남은 10 카드를 1 카드 10장으로 바꾸어(아래로 내려) 다시 나누기',ARRAY['4수01-06']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C3','math',3,2,'u2',4,'(몇십몇) ÷ (몇) 내림 없음 — 십의 자리와 일의 자리를 차례로 나누어 몫을 그 자리 위에 쓰기',ARRAY['4수01-06']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C4','math',3,2,'u2',4,'나눗셈 어림하기 — 나누어지는 수를 나누기 쉬운 몇십·몇백으로 보아 몫이 얼마쯤일지, 몫이 어느 두 수 사이에 있을지 가늠하고 계산한 몫과 견주기',ARRAY['4수01-08']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C5','math',3,2,'u2',5,'(몇십몇) ÷ (몇) 내림 있음 — 십의 자리를 나누고 남은 수를 일의 자리 위로 내려 함께 다시 나누기',ARRAY['4수01-06']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C6','math',3,2,'u2',6,'나머지와 나누어떨어짐 — 똑같이 나누고 남는 수가 나머지이고, 나머지가 0이면 나누어떨어진다고 하며, 나머지는 언제나 나누는 수보다 작음을 알기',ARRAY['4수01-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C7','math',3,2,'u2',7,'나머지가 있는 (몇십몇) ÷ (몇)과 계산 확인 — 몫이 두 자리인 나눗셈의 몫과 나머지를 구하고, 나누는 수 × 몫 + 나머지 = 나누어지는 수로 확인하기',ARRAY['4수01-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C8','math',3,2,'u2',8,'(세 자리 수) ÷ (한 자리 수) 내림이 없는 경우 — 몇백은 (몇) ÷ (몇)의 몫을 100배로 보고, 백의 자리부터 차례로 나누어 그 자리 위에 몫을 쓰며 나눌 수 없는 자리의 몫에 0을 쓰기, 나누는 수 × 몫 + 나머지로 확인하기',ARRAY['4수01-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C9','math',3,2,'u2',9,'(세 자리 수) ÷ (한 자리 수) 내림이 있는 경우 — 윗자리에서 남은 수를 아래 자리 수와 더해 다시 나누고, 백의 자리가 나누는 수보다 작으면 십의 자리까지 함께 보아 나누며, 몫을 어림해 계산한 몫과 견주기',ARRAY['4수01-06']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-2-u2-C10','math',3,2,'u2',10,'나눗셈으로 문제 해결하기 — 상황을 나눗셈식으로 세우고, 몫(한 묶음·한 사람 몫)과 나머지(남는 것)가 각각 무엇을 뜻하는지 읽어 알맞게 답하기',ARRAY['4수01-05']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X01','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C8']::text[],'몇십·몇백을 나눌 때 몫의 0을 빠뜨린다(60 ÷ 3 = 2, 800 ÷ 4 = 2)','몇십이면 몫도 몇십') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X02','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C8']::text[],'몫에 0을 더 붙인다(60 ÷ 3 = 200, 30 ÷ 2 = 150)','자리에 맞추어 몫 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X03','math',3,'u2',ARRAY['M3-2-u2-C2','M3-2-u2-C5','M3-2-u2-C7','M3-2-u2-C9']::text[],'윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다(30 ÷ 2 = 10, 45 ÷ 3 = 11)','남은 수는 아래로 내리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X04','math',3,'u2',ARRAY['M3-2-u2-C3','M3-2-u2-C5']::text[],'몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다(93 ÷ 3 = 13)','높은 자리부터 그 자리 위에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X05','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C9']::text[],'나머지를 나누는 수보다 크거나 같게 남긴다(257 ÷ 4 = 63 … 5)','나머지 < 나누는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X06','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7']::text[],'몫과 나머지를 바꾸어 쓴다(25 ÷ 4 = 1 … 6)','묶음 수가 몫, 남은 것이 나머지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X07','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C10']::text[],'나머지를 빠뜨리고 몫만 쓰거나, 남는 것이 있는데 나누어떨어진다고 한다','남은 것까지 쓰기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X08','math',3,'u2',ARRAY['M3-2-u2-C7']::text[],'확인할 때 나누는 수 대신 나머지를 몫에 곱한다(99 ÷ 8 = 12 … 3 → 3 × 12 + 8)','나누는 수 × 몫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X09','math',3,'u2',ARRAY['M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9']::text[],'확인할 때 나머지를 더하지 않는다(나누는 수 × 몫만 견준다)','+ 나머지까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X10','math',3,'u2',ARRAY['M3-2-u2-C8','M3-2-u2-C9']::text[],'나눌 수 없는 가운데 자리의 몫 0을 빠뜨린다(307 ÷ 3 = 12 … 1)','나눌 수 없으면 몫에 0') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X11','math',3,'u2',ARRAY['M3-2-u2-C8']::text[],'몫의 0을 끝에 붙여 자리가 어긋난다(615 ÷ 6 = 120 … 15)','0은 그 자리에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X12','math',3,'u2',ARRAY['M3-2-u2-C9']::text[],'백의 자리가 나누는 수보다 작은데 몫을 세 자리로 쓴다(258 ÷ 4 = 640 …)','백의 자리 < 나누는 수면 몫은 두 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X13','math',3,'u2',ARRAY['M3-2-u2-C10','M3-2-u2-C6','M3-2-u2-C7']::text[],'문제에서 몫을 묻는지 나머지를 묻는지 바꾸어 답하거나, 남는 것을 위해 하나 더 필요한 경우를 놓친다','묻는 것에 밑줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X14','math',3,'u2',ARRAY['M3-2-u2-C10','M3-2-u2-C1','M3-2-u2-C3']::text[],'똑같이 나누는 상황에 나눗셈 대신 곱셈·뺄셈 식을 세운다(96개를 3모둠에 → 96 × 3, 96 − 3)','똑같이 나누면 ÷') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X15','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C3','M3-2-u2-C5','M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9','M3-2-u2-C10','M3-2-u2-C6']::text[],'곱셈구구나 빼기에서 실수해 몫이 1 크거나 작다','나누는 수 × 몫으로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X16','math',3,'u2',ARRAY['M3-2-u2-C4','M3-2-u2-C9']::text[],'어림할 때 나누기 쉬운 수로 바꾸지 않거나 몫의 자리 수를 잘못 가늠한다','나누기 쉬운 몇십·몇백으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X17','math',3,'u2',ARRAY['M3-2-u2-C1','M3-2-u2-C2','M3-2-u2-C3','M3-2-u2-C4','M3-2-u2-C5','M3-2-u2-C6','M3-2-u2-C7','M3-2-u2-C8','M3-2-u2-C9','M3-2-u2-C10']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는, 큰↔작은, 몫↔나머지','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X18','math',3,'u2',ARRAY['M3-2-u2-C6','M3-2-u2-C10']::text[],'나누어떨어진다는 뜻을 헷갈린다(나머지가 0일 때가 아니라 몫이 0일 때라고 생각한다)','나머지 0 = 나누어떨어짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X19','math',3,'u2',ARRAY['M3-2-u2-C3','M3-2-u2-C8','M3-2-u2-C9']::text[],'자리 숫자가 나누는 수보다 작으면 나누는 수를 그 숫자로 거꾸로 나눈다 — 418 ÷ 4에서 십의 자리 1을 보고 「4 ÷ 1 = 4」라 하여 142로 쓴다','나누어지는 수의 자리 숫자를 나누는 수로 나누기 — 나눌 수 없으면 몫에 0을 쓰고 아래 자리와 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-2-u2-X20','math',3,'u2',ARRAY['M3-2-u2-C10','M3-2-u2-C1','M3-2-u2-C6']::text[],'문장에 나온 차례대로 식을 세우거나 엉뚱한 수로 나눈다 — 「8명이 공책 240권」을 8 ÷ 240으로 쓰거나, 열쇠고리 4개를 만드는데 고른 색깔 수 3으로 나눈다','무엇을(나누어지는 수) 몇으로(나누는 수) 똑같이 나누는지 먼저 찾아 밑줄 긋기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#1','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'mc','auto','나눗셈식 18 ÷ 6 = 3을 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X14']::text[],true,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"mc","stem":"나눗셈식 18 ÷ 6 = 3을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"18 나누기 6은 3과 같습니다","correct":true},{"t":"6 나누기 18은 3과 같습니다","mis":"M3-2-u2-X20"},{"t":"18 곱하기 6은 3과 같습니다","mis":"M3-2-u2-X14"}],"explanation":["나눗셈식은 왼쪽부터 「나누어지는 수 나누기 나누는 수」로 읽어요.","18은 나누어지는 수, 6은 나누는 수, 3은 18을 6으로 나눈 몫이에요.","그래서 「18 나누기 6은 3과 같습니다.」라고 읽어요."],"variant_rule":{"alt":[{"stem":"나눗셈식 56 ÷ 8 = 7을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"56 나누기 8은 7과 같습니다","correct":true},{"t":"8 나누기 56은 7과 같습니다","mis":"M3-2-u2-X20"},{"t":"56 곱하기 8은 7과 같습니다","mis":"M3-2-u2-X14"}],"explanation":["나눗셈식은 왼쪽부터 「나누어지는 수 나누기 나누는 수」로 읽어요.","56은 나누어지는 수, 8은 나누는 수, 7은 56을 8로 나눈 몫이에요.","그래서 「56 나누기 8은 7과 같습니다.」라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#2','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'sa','auto','28 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"28 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["나누는 수 4의 단에서 28을 찾아요.","4 × 7 = 28 — 그래서 28 ÷ 4 = 7이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."],"variant_rule":{"alt":[{"stem":"42 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 7의 단에서 42를 찾아요.","7 × 6 = 42 — 그래서 42 ÷ 7 = 6이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."]},{"stem":"72 ÷ 9는 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["나누는 수 9의 단에서 72를 찾아요.","9 × 8 = 72 — 그래서 72 ÷ 9 = 8이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."]},{"stem":"12 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 2의 단에서 12를 찾아요.","2 × 6 = 12 — 그래서 12 ÷ 2 = 6이에요.","나누는 수 × 몫 = 나누어지는 수가 되는지 곱셈으로 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#3','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'mc','auto','곱셈식 8 × 7 = 56을 나눗셈식 두 개로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X14','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C1","difficulty":1,"kind":"mc","stem":"곱셈식 8 × 7 = 56을 나눗셈식 두 개로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"56 ÷ 8 = 7, 56 ÷ 7 = 8","correct":true},{"t":"8 ÷ 56 = 7, 7 ÷ 56 = 8","mis":"M3-2-u2-X20"},{"t":"56 × 8 = 7, 56 × 7 = 8","mis":"M3-2-u2-X14"},{"t":"56 ÷ 8 = 8, 56 ÷ 7 = 7","mis":"M3-2-u2-X15"}],"explanation":["곱해서 나온 56이 나누어지는 수예요.","56을 8로 나누면 7, 7로 나누면 8 — 56 ÷ 8 = 7, 56 ÷ 7 = 8.","곱셈식 하나를 나눗셈식 두 개로 바꾸어 나타낼 수 있어요."],"variant_rule":{"alt":[{"stem":"야구공이 한 묶음에 3개씩 3묶음 있어요. 곱셈식 3 × 3 = 9를 나눗셈식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"9 ÷ 3 = 3","correct":true},{"t":"3 ÷ 9 = 3","mis":"M3-2-u2-X20"},{"t":"9 × 3 = 3","mis":"M3-2-u2-X14"},{"t":"9 ÷ 3 = 6","mis":"M3-2-u2-X15"}],"explanation":["곱해서 나온 9가 나누어지는 수예요.","9를 3으로 나누면 3 — 9 ÷ 3 = 3.","곱셈과 나눗셈은 서로 바꾸어 나타낼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#4','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',1,'sa','auto','6 ÷ 3 = 2예요. 그러면 60 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"6 ÷ 3 = 2예요. 그러면 60 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["60은 6의 10배예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","2의 10배 — 60 ÷ 3 = 20이에요."],"variant_rule":{"alt":[{"stem":"8 ÷ 2 = 4예요. 그러면 80 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["80은 8의 10배예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","4의 10배 — 80 ÷ 2 = 40이에요."]},{"stem":"9 ÷ 3 = 3이에요. 그러면 90 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["90은 9의 10배예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","3의 10배 — 90 ÷ 3 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#5','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'mc','auto','봉사 동아리 학생 60명이 버스 3대에 똑같이 나누어 타려고 해요. 버스 한 대에 타야 하는 학생 수를 구하는 식은 어느 것인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X20']::text[],true,'{"seq":5,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"봉사 동아리 학생 60명이 버스 3대에 똑같이 나누어 타려고 해요. 버스 한 대에 타야 하는 학생 수를 구하는 식은 어느 것인가요?","options":[{"t":"60 ÷ 3","correct":true},{"t":"60 − 3","mis":"M3-2-u2-X14"},{"t":"60 × 3","mis":"M3-2-u2-X14"},{"t":"3 ÷ 60","mis":"M3-2-u2-X20"}],"explanation":["전체 학생 60명을 버스 3대에 똑같이 나누어요.","전체 학생 수 ÷ 버스 수 — 식은 60 ÷ 3.","60 ÷ 3 = 20 — 버스 한 대에 20명씩 타요."],"variant_rule":{"alt":[{"stem":"봉사 활동을 가기 위해 학생 40명이 버스 2대에 똑같이 나누어 타려고 해요. 버스 한 대에 타야 하는 학생 수를 구하는 식은 어느 것인가요?","options":[{"t":"40 ÷ 2","correct":true},{"t":"40 − 2","mis":"M3-2-u2-X14"},{"t":"40 × 2","mis":"M3-2-u2-X14"},{"t":"2 ÷ 40","mis":"M3-2-u2-X20"}],"explanation":["전체 학생 40명을 버스 2대에 똑같이 나누어요.","전체 학생 수 ÷ 버스 수 — 식은 40 ÷ 2.","40 ÷ 2 = 20 — 버스 한 대에 20명씩 타요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#6','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'mc','auto','밤 20개를 한 명에게 4개씩 나누어 주려고 해요. 몇 명에게 줄 수 있나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X15']::text[],true,'{"seq":6,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"밤 20개를 한 명에게 4개씩 나누어 주려고 해요. 몇 명에게 줄 수 있나요?","options":[{"t":"5명","correct":true},{"t":"16명","mis":"M3-2-u2-X14"},{"t":"80명","mis":"M3-2-u2-X14"},{"t":"6명","mis":"M3-2-u2-X15"}],"explanation":["전체 밤 수를 한 명에게 주는 밤 수로 나누어요 — 식은 20 ÷ 4.","4 × 5 = 20 — 그래서 20 ÷ 4 = 5예요.","20 ÷ 4 = 5 — 몫 5는 밤을 받는 사람 수예요."],"variant_rule":{"alt":[{"stem":"딱지 35장을 한 명에게 7장씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","options":[{"t":"5명","correct":true},{"t":"28명","mis":"M3-2-u2-X14"},{"t":"245명","mis":"M3-2-u2-X14"},{"t":"6명","mis":"M3-2-u2-X15"}],"explanation":["전체 딱지 수를 한 명에게 주는 딱지 수로 나누어요 — 식은 35 ÷ 7.","7 × 5 = 35 — 그래서 35 ÷ 7 = 5예요.","35 ÷ 7 = 5 — 몫 5는 딱지를 받는 사람 수예요."]},{"stem":"감자 12개를 접시 2개에 똑같이 나누어 담으려고 해요. 접시 한 개에 몇 개씩 담아야 하나요?","options":[{"t":"6개","correct":true},{"t":"10개","mis":"M3-2-u2-X14"},{"t":"24개","mis":"M3-2-u2-X14"},{"t":"7개","mis":"M3-2-u2-X15"}],"explanation":["전체 감자 수를 접시 수로 나누어요 — 식은 12 ÷ 2.","2 × 6 = 12 — 그래서 12 ÷ 2 = 6이에요.","12 ÷ 2 = 6 — 몫 6은 접시 한 개에 담는 감자 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#7','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'sa','auto','60은 10 카드 6장이에요. 10 카드를 3곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C1","difficulty":2,"kind":"sa","stem":"60은 10 카드 6장이에요. 10 카드를 3곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.","answer":["2"],"explanation":["10 카드 6장을 3곳에 한 장씩 차례로 놓아요.","6 ÷ 3 = 2예요 — 한 곳에 2장씩.","10 카드 2장이 나타내는 수는 20 — 60 ÷ 3 = 20이에요."],"variant_rule":{"alt":[{"stem":"80은 10 카드 8장이에요. 10 카드를 4곳에 똑같이 나누어 놓으면 한 곳에 10 카드가 몇 장씩 놓이나요? 숫자로 쓰세요.","answer":["2"],"explanation":["10 카드 8장을 4곳에 한 장씩 차례로 놓아요.","8 ÷ 4 = 2예요 — 한 곳에 2장씩.","10 카드 2장이 나타내는 수는 20 — 80 ÷ 4 = 20이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#8','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'match','auto','나눗셈식 60 ÷ 3 = 20을 세로로 썼어요. 세로셈의 수와 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C1","difficulty":2,"kind":"match","stem":"나눗셈식 60 ÷ 3 = 20을 세로로 썼어요. 세로셈의 수와 그 뜻을 알맞게 이으세요.","pairs":[{"l":"60 — 나누어지는 수","r":"전체 학생 수"},{"l":"3 — 나누는 수","r":"모둠 수"},{"l":"20 — 몫","r":"한 모둠의 학생 수"}],"mis":"M3-2-u2-X20","explanation":["세로셈에서 나누는 수 3은 왼쪽, 나누어지는 수 60은 안쪽, 몫 20은 위에 써요.","60은 전체 학생 수, 3은 모둠 수를 나타내요.","몫 20은 한 모둠의 학생 수예요 — 몫은 자리를 맞추어 위에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#9','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',2,'sa','auto','80 ÷ 4의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C1","difficulty":2,"kind":"sa","stem":"80 ÷ 4의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 0 → 몫 0.","80 ÷ 4 = 20 — 몫의 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":80,"b":4,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"90 ÷ 3의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 0 → 몫 0.","90 ÷ 3 = 30 — 몫의 십의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":90,"b":3,"hide":[["q",0]]}},{"stem":"60 ÷ 3의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 0 → 몫 0.","60 ÷ 3 = 20 — 몫의 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":60,"b":3,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_basic#10','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_basic','lesson_basic','M3-2-u2-C1',3,'error','auto','탁구공 40개를 상자 2개에 똑같이 나누어 담으려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X01','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C1","difficulty":3,"kind":"error","stem":"탁구공 40개를 상자 2개에 똑같이 나누어 담으려고 해요. 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「4 ÷ 2 = 2이니까 상자 한 개에 2개씩 담아요」","correct":true,"mis_target":"M3-2-u2-X01"},{"t":"서윤 — 「40 ÷ 2 = 20이니까 20개씩 담아요」","mis":"M3-2-u2-X17"},{"t":"민준 — 「확인하면 2 × 20 = 40이야」","mis":"M3-2-u2-X17"}],"explanation":["40은 10 카드 4장 — 2곳에 2장씩 놓으면 10 카드 2장, 20이에요.","40 ÷ 2 = 20 — 상자 한 개에 20개씩 담아요.","채원이는 몫의 0을 빠뜨렸어요 — 몇십을 나누면 몫도 몇십이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#1','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',2,'mc','auto','공원에서 친구가 「배지 96개를 똑같이 3묶음으로 나누려고 해. 배지는 한 묶음에 몇 개씩인지 어떻게 구할까?」라고 했어요. 알맞은 식은 어느 것인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X20']::text[],false,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"공원에서 친구가 「배지 96개를 똑같이 3묶음으로 나누려고 해. 배지는 한 묶음에 몇 개씩인지 어떻게 구할까?」라고 했어요. 알맞은 식은 어느 것인가요?","options":[{"t":"96 ÷ 3","correct":true},{"t":"96 − 3","mis":"M3-2-u2-X14"},{"t":"96 × 3","mis":"M3-2-u2-X14"},{"t":"3 ÷ 96","mis":"M3-2-u2-X20"}],"explanation":["배지 96개를 3묶음으로 똑같이 나누어요.","전체 배지 수 ÷ 묶음 수 — 식은 96 ÷ 3.","나누어지는 수가 커져도 똑같이 나누는 상황이면 나눗셈식을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#2','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',2,'mc','auto','연필 90자루를 한 명에게 9자루씩 나누어 주려고 해요. 연필을 몇 명에게 나누어 줄 수 있나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X01']::text[],true,'{"seq":2,"concept":"M3-2-u2-C1","difficulty":2,"kind":"mc","stem":"연필 90자루를 한 명에게 9자루씩 나누어 주려고 해요. 연필을 몇 명에게 나누어 줄 수 있나요?","options":[{"t":"10명","correct":true},{"t":"81명","mis":"M3-2-u2-X14"},{"t":"810명","mis":"M3-2-u2-X14"},{"t":"1명","mis":"M3-2-u2-X01"}],"explanation":["전체 연필 수를 한 명에게 주는 연필 수로 나누어요 — 식은 90 ÷ 9.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","90 ÷ 9 = 10 — 몫 10은 연필을 받는 사람 수예요."],"variant_rule":{"alt":[{"stem":"학생 80명을 4모둠으로 똑같이 나누려고 해요. 한 모둠에 몇 명의 학생이 있나요?","options":[{"t":"20명","correct":true},{"t":"76명","mis":"M3-2-u2-X14"},{"t":"320명","mis":"M3-2-u2-X14"},{"t":"2명","mis":"M3-2-u2-X01"}],"explanation":["전체 학생 수를 모둠 수로 나누어요 — 식은 80 ÷ 4.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","80 ÷ 4 = 20 — 몫 20은 한 모둠의 학생 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#3','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 40 ÷ 4 ○ 80 ÷ 8',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":3,"concept":"M3-2-u2-C1","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 40 ÷ 4 ○ 80 ÷ 8","options":[{"t":"=","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"<","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["40 ÷ 4의 몫은 10이에요.","80 ÷ 8의 몫은 10이에요.","10 = 10 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 40 ÷ 2 ○ 70 ÷ 7","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["40 ÷ 2의 몫은 20이에요.","70 ÷ 7의 몫은 10이에요.","20 > 10 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#4','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'blank','auto','수 카드 3, 4, 5, 9 가운데 2장을 골라 한 번씩만 사용하여 □0 ÷ □ = 30을 완성하려고 해요. 알맞은 나눗셈식은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X15']::text[],false,'{"seq":4,"concept":"M3-2-u2-C1","difficulty":3,"kind":"blank","stem":"수 카드 3, 4, 5, 9 가운데 2장을 골라 한 번씩만 사용하여 □0 ÷ □ = 30을 완성하려고 해요. 알맞은 나눗셈식은 어느 것인가요?","options":[{"t":"90 ÷ 3 = 30","correct":true},{"t":"30 ÷ 9 = 30","mis":"M3-2-u2-X20"},{"t":"90 ÷ 9 = 30","mis":"M3-2-u2-X15"},{"t":"40 ÷ 5 = 30","mis":"M3-2-u2-X15"}],"explanation":["몫이 30이 되려면 앞의 수를 뒤의 수로 나눈 몫이 3이어야 해요.","9 ÷ 3 = 3 — 그래서 90 ÷ 3 = 30이에요.","나누어지는 수가 10배 커지면 몫도 10배 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#5','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'sa','auto','서윤이 60 ÷ 2를 계산하고 몫을 3이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C1","difficulty":3,"kind":"sa","stem":"서윤이 60 ÷ 2를 계산하고 몫을 3이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["서윤 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","바른 몫은 30 — 확인: 2 × 30 = 60이에요."],"variant_rule":{"alt":[{"stem":"민준이 50 ÷ 5를 계산하고 몫을 1이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["민준 — 몇십·몇백을 나눌 때 몫의 0을 빠뜨린다.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","바른 몫은 10 — 확인: 5 × 10 = 50이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#6','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'ox','auto','80 ÷ 4 = 2예요.',ARRAY['M3-2-u2-X01']::text[],true,'{"seq":6,"concept":"M3-2-u2-C1","difficulty":3,"kind":"ox","stem":"80 ÷ 4 = 2예요.","answer":"X","reason_options":[{"t":"80은 8의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"mis":"M3-2-u2-X01","explanation":["8 ÷ 4 = 2예요.","80은 8의 10배 — 몫도 10배인 20이에요.","2는 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":80,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"90 ÷ 3 = 3이에요.","answer":"X","reason_options":[{"t":"90은 9의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"explanation":["9 ÷ 3 = 3이에요.","90은 9의 10배 — 몫도 10배인 30이에요.","3은 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":90,"b":3,"upto":0}},{"stem":"70 ÷ 7 = 1이에요.","answer":"X","reason_options":[{"t":"70은 7의 10배라 몫도 10배여야 해서","correct":true},{"t":"0은 나누어도 0이라 안 써도 되어서","mis":"M3-2-u2-X01"}],"explanation":["7 ÷ 7 = 1이에요.","70은 7의 10배 — 몫도 10배인 10이에요.","1은 몫의 0을 빠뜨린 답이에요."],"asset":{"type":"ldiv","a":70,"b":7,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#7','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',3,'sa','auto','60 ÷ 3을 세로셈으로 계산할 때 몫 20을 쓰고, 그 아래에 나누는 수와 몫의 곱 3 × 20을 써요. 3 × 20은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C1","difficulty":3,"kind":"sa","stem":"60 ÷ 3을 세로셈으로 계산할 때 몫 20을 쓰고, 그 아래에 나누는 수와 몫의 곱 3 × 20을 써요. 3 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["몫 20은 10이 2개 — 3 × 20 = 60이에요.","60 − 60 = 0 — 남는 수가 없어요.","그래서 60 ÷ 3 = 20이고 나누어떨어져요."],"variant_rule":{"alt":[{"stem":"80 ÷ 4를 세로셈으로 계산할 때 몫 20을 쓰고, 그 아래에 나누는 수와 몫의 곱 4 × 20을 써요. 4 × 20은 얼마인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["몫 20은 10이 2개 — 4 × 20 = 80이에요.","80 − 80 = 0 — 남는 수가 없어요.","그래서 80 ÷ 4 = 20이에요."]},{"stem":"90 ÷ 3을 세로셈으로 계산할 때 몫 30을 쓰고, 그 아래에 나누는 수와 몫의 곱 3 × 30을 써요. 3 × 30은 얼마인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["몫 30은 10이 3개 — 3 × 30 = 90이에요.","90 − 90 = 0 — 남는 수가 없어요.","그래서 90 ÷ 3 = 30이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#8','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'essay','teacher','봉사 동아리 학생 60명이 버스 3대에 똑같이 나누어 타요. 60 ÷ 3을 10 카드로 구하는 방법과 6 ÷ 3을 이용하는 방법으로 각각 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C1","difficulty":4,"kind":"essay","stem":"봉사 동아리 학생 60명이 버스 3대에 똑같이 나누어 타요. 60 ÷ 3을 10 카드로 구하는 방법과 6 ÷ 3을 이용하는 방법으로 각각 설명해 보세요.","answer_guide":{"answer":"예: ① 60은 10 카드 6장이다. 6장을 3곳에 똑같이 나누면 한 곳에 10 카드 2장이 놓이고, 10 카드 2장이 나타내는 수는 20이다. ② 6 ÷ 3 = 2이고 나누어지는 수 60은 6의 10배이므로 몫도 10배인 20이다. 버스 한 대에 20명씩 탄다.","scoring_points":["10 카드 6장을 3곳에 나누어 20을 구했는가","6 ÷ 3 = 2의 10배로 설명했는가","버스 한 대에 20명이라고 답했는가"]},"explanation":["10 카드 6장 → 3곳에 2장씩 — 20.","6 ÷ 3 = 2 → 10배 하면 20.","60 ÷ 3 = 20 — 버스 한 대에 20명."],"asset":{"type":"ldiv","a":60,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#9','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'essay','teacher','친구가 80 ÷ 4를 세로로 계산하면서 몫 2를 일의 자리 위에만 쓰고 몫을 2라고 했어요. 무엇이 잘못되었는지 쓰고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C1","difficulty":4,"kind":"essay","stem":"친구가 80 ÷ 4를 세로로 계산하면서 몫 2를 일의 자리 위에만 쓰고 몫을 2라고 했어요. 무엇이 잘못되었는지 쓰고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 8 ÷ 4 = 2는 10 카드 8장을 4곳에 나눈 것이라 2는 10 카드 2장, 곧 20을 뜻한다. 그래서 몫의 십의 자리에 2, 일의 자리에 0을 써야 한다. 80 ÷ 4 = 20이고, 확인하면 4 × 20 = 80이다.","scoring_points":["몫을 자리에 맞추어 써야 한다고 했는가","80 ÷ 4 = 20을 구했는가","4 × 20 = 80으로 확인했는가"]},"explanation":["8 ÷ 4 = 2 — 십의 자리에서 나눈 몫이에요.","몫 2는 십의 자리 위에 — 80 ÷ 4 = 20.","4 × 20 = 80 — 바르게 계산했어요."],"asset":{"type":"ldiv","a":80,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L02_challenge#10','math',3,2,'u2','L02','tb_g3_2_math_u2_L02_challenge','lesson_challenge','M3-2-u2-C1',4,'essay','teacher','80 ÷ 4에 알맞은 생활 속 문제를 만들고 해결해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C1","difficulty":4,"kind":"essay","stem":"80 ÷ 4에 알맞은 생활 속 문제를 만들고 해결해 보세요.","answer_guide":{"answer":"예: 학생 80명을 4모둠으로 똑같이 나누려고 한다. 한 모둠에 몇 명의 학생이 있는지 구해 보세요. → 80 ÷ 4 = 20이므로 한 모둠에 20명이다.","scoring_points":["80을 4로 똑같이 나누는 상황을 만들었는가","80 ÷ 4 = 20을 구했는가","몫의 뜻을 살려 단위를 붙여 답했는가"]},"explanation":["80은 나누어지는 수, 4는 나누는 수가 되게 상황을 만들어요.","80 ÷ 4 = 20 — 8 ÷ 4 = 2의 10배예요.","「한 모둠에 20명」처럼 몫의 뜻을 살려 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#1','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'sa','auto','30 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"30 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 확인: 2 × 15 = 30이에요."],"variant_rule":{"alt":[{"stem":"50 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 확인: 2 × 25 = 50이에요."]},{"stem":"70 ÷ 5는 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 확인: 5 × 14 = 70이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#2','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'sa','auto','30 ÷ 2를 수 카드로 계산해요. 10 카드 3장을 2곳에 1장씩 놓고 남은 10 카드 1장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C2","difficulty":1,"kind":"sa","stem":"30 ÷ 2를 수 카드로 계산해요. 10 카드 3장을 2곳에 1장씩 놓고 남은 10 카드 1장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["10 카드 3장을 2곳에 나누면 한 곳에 1장씩, 1장이 남아요.","남은 10 카드 1장 = 1 카드 10장.","1 카드 10장을 2곳에 나누면 5장씩 — 한 곳에 10 + 5 = 15예요."],"variant_rule":{"alt":[{"stem":"50 ÷ 2를 수 카드로 계산해요. 10 카드 5장을 2곳에 2장씩 놓고 남은 10 카드 1장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["10 카드 5장을 2곳에 나누면 한 곳에 2장씩, 1장이 남아요.","남은 10 카드 1장 = 1 카드 10장.","1 카드 10장을 2곳에 나누면 5장씩 — 한 곳에 20 + 5 = 25예요."]},{"stem":"70 ÷ 5를 수 카드로 계산해요. 10 카드 7장을 5곳에 1장씩 놓고 남은 10 카드 2장을 1 카드로 바꾸면 1 카드는 몇 장인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["10 카드 7장을 5곳에 나누면 한 곳에 1장씩, 2장이 남아요.","남은 10 카드 2장 = 1 카드 20장.","1 카드 20장을 5곳에 나누면 4장씩 — 한 곳에 10 + 4 = 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#3','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'mc','auto','60 ÷ 4는 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":1,"kind":"mc","stem":"60 ÷ 4는 얼마인가요?","options":[{"t":"15","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"16","mis":"M3-2-u2-X15"},{"t":"14","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 4 → 몫 5.","60 ÷ 4 = 15 — 확인: 4 × 15 = 60이에요."],"variant_rule":{"alt":[{"stem":"90 ÷ 6은 얼마인가요?","options":[{"t":"15","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"16","mis":"M3-2-u2-X15"},{"t":"14","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 확인: 6 × 15 = 90이에요."]},{"stem":"80 ÷ 5는 얼마인가요?","options":[{"t":"16","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"17","mis":"M3-2-u2-X15"},{"t":"15","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 확인: 5 × 16 = 80이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#4','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',1,'mc','auto','30 ÷ 2를 수 카드로 계산해요. 10 카드 3장을 2곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":4,"concept":"M3-2-u2-C2","difficulty":1,"kind":"mc","stem":"30 ÷ 2를 수 카드로 계산해요. 10 카드 3장을 2곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 1장, 1 카드 5장","correct":true},{"t":"10 카드 1장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 5장, 1 카드 1장","mis":"M3-2-u2-X04"},{"t":"10 카드 1장, 1 카드 6장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 3장을 2곳에 1장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 10장 — 2곳에 5장씩 놓아요.","한 곳에 10 카드 1장과 1 카드 5장 — 15예요."],"variant_rule":{"alt":[{"stem":"50 ÷ 2를 수 카드로 계산해요. 10 카드 5장을 2곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 2장, 1 카드 5장","correct":true},{"t":"10 카드 2장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 5장, 1 카드 2장","mis":"M3-2-u2-X04"},{"t":"10 카드 2장, 1 카드 6장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 5장을 2곳에 2장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 10장 — 2곳에 5장씩 놓아요.","한 곳에 10 카드 2장과 1 카드 5장 — 25예요."]},{"stem":"70 ÷ 2를 수 카드로 계산해요. 10 카드 7장을 2곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 3장, 1 카드 5장","correct":true},{"t":"10 카드 3장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 5장, 1 카드 3장","mis":"M3-2-u2-X04"},{"t":"10 카드 3장, 1 카드 6장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 7장을 2곳에 3장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 10장 — 2곳에 5장씩 놓아요.","한 곳에 10 카드 3장과 1 카드 5장 — 35예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#5','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'mc','auto','공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심으려고 해요. 화단 한 개에 금잔화를 몇 포기씩 심어야 하나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03']::text[],true,'{"seq":5,"concept":"M3-2-u2-C2","difficulty":2,"kind":"mc","stem":"공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심으려고 해요. 화단 한 개에 금잔화를 몇 포기씩 심어야 하나요?","options":[{"t":"15포기","correct":true},{"t":"28포기","mis":"M3-2-u2-X14"},{"t":"60포기","mis":"M3-2-u2-X14"},{"t":"10포기","mis":"M3-2-u2-X03"}],"explanation":["전체 금잔화 수를 화단 수로 나누어요 — 식은 30 ÷ 2.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 몫 15는 화단 한 개에 심는 금잔화 수예요."],"variant_rule":{"alt":[{"stem":"공원을 가꾸기 위해 금잔화 50포기를 화단 2개에 똑같이 나누어 심으려고 해요. 화단 한 개에 금잔화를 몇 포기씩 심어야 하나요?","options":[{"t":"25포기","correct":true},{"t":"48포기","mis":"M3-2-u2-X14"},{"t":"100포기","mis":"M3-2-u2-X14"},{"t":"20포기","mis":"M3-2-u2-X03"}],"explanation":["전체 금잔화 수를 화단 수로 나누어요 — 식은 50 ÷ 2.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","50 ÷ 2 = 25 — 몫 25는 화단 한 개에 심는 금잔화 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#6','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'sa','auto','30 ÷ 2를 20과 10으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"30 ÷ 2를 20과 10으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["30을 20과 10으로 갈라요 — 둘 다 2로 나누어떨어져요.","20 ÷ 2 = 10, 10 ÷ 2 = 5예요.","10 + 5 = 15 — 30 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["20 ÷ 2","=","10"],["10 ÷ 2","=",null],["10 + □","=","15"]]},"variant_rule":{"alt":[{"stem":"50 ÷ 2를 40과 10으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["50을 40과 10으로 갈라요 — 둘 다 2로 나누어떨어져요.","40 ÷ 2 = 20, 10 ÷ 2 = 5예요.","20 + 5 = 25 — 50 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["40 ÷ 2","=","20"],["10 ÷ 2","=",null],["20 + □","=","25"]]}},{"stem":"70 ÷ 5를 50과 20으로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["70을 50과 20으로 갈라요 — 둘 다 5로 나누어떨어져요.","50 ÷ 5 = 10, 20 ÷ 5 = 4예요.","10 + 4 = 14 — 70 ÷ 5의 몫이에요."],"asset":{"type":"expr_grid","rows":[["50 ÷ 5","=","10"],["20 ÷ 5","=",null],["10 + □","=","14"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#7','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'ox','auto','30 ÷ 2 = 10이에요.',ARRAY['M3-2-u2-X03']::text[],true,'{"seq":7,"concept":"M3-2-u2-C2","difficulty":2,"kind":"ox","stem":"30 ÷ 2 = 10이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"mis":"M3-2-u2-X03","explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 30 ÷ 2 = 15.","남은 수는 아래로 내리기 — 확인: 2 × 15 = 30이에요."],"asset":{"type":"ldiv","a":30,"b":2,"upto":0},"variant_rule":{"alt":[{"stem":"50 ÷ 2 = 20이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 50 ÷ 2 = 25.","남은 수는 아래로 내리기 — 확인: 2 × 25 = 50이에요."],"asset":{"type":"ldiv","a":50,"b":2,"upto":0}},{"stem":"90 ÷ 2 = 40이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 90 ÷ 2 = 45.","남은 수는 아래로 내리기 — 확인: 2 × 45 = 90이에요."],"asset":{"type":"ldiv","a":90,"b":2,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#8','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'sa','auto','60 ÷ 4의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"60 ÷ 4의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 4 → 몫 5.","60 ÷ 4 = 15 — 몫의 일의 자리 숫자는 5예요."],"asset":{"type":"ldiv","a":60,"b":4,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"90 ÷ 6의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 몫의 일의 자리 숫자는 5예요."],"asset":{"type":"ldiv","a":90,"b":6,"hide":[["q",1]]}},{"stem":"60 ÷ 5의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","60 ÷ 5 = 12 — 몫의 일의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":60,"b":5,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#9','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',2,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 30 ÷ 2 ○ 60 ÷ 4',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":9,"concept":"M3-2-u2-C2","difficulty":2,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 30 ÷ 2 ○ 60 ÷ 4","options":[{"t":"=","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"<","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["30 ÷ 2의 몫은 15예요.","60 ÷ 4의 몫은 15예요.","15 = 15 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_basic#10','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_basic','lesson_basic','M3-2-u2-C2',3,'error','auto','붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 친구들이 80 ÷ 5를 계산하고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 친구들이 80 ÷ 5를 계산하고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「80 ÷ 5의 몫은 61이야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"소율 — 「8을 5로 나누고 남은 30을 다시 5로 나누어」","mis":"M3-2-u2-X17"},{"t":"민서 — 「한 명에게 16장씩 줄 수 있어」","mis":"M3-2-u2-X17"}],"explanation":["8 ÷ 5 → 몫 1, 3 남음 · 남은 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 확인: 5 × 16 = 80이에요.","지아는 몫을 거꾸로 썼어요 — 몫은 높은 자리부터 그 자리 위에 써요."],"asset":{"type":"ldiv","a":80,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#1','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',2,'mc','auto','90 ÷ 5는 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X15']::text[],true,'{"seq":1,"concept":"M3-2-u2-C2","difficulty":2,"kind":"mc","stem":"90 ÷ 5는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"19","mis":"M3-2-u2-X15"},{"t":"17","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","90 ÷ 5 = 18 — 확인: 5 × 18 = 90이에요."],"variant_rule":{"alt":[{"stem":"70 ÷ 2는 얼마인가요?","options":[{"t":"35","correct":true},{"t":"30","mis":"M3-2-u2-X03"},{"t":"36","mis":"M3-2-u2-X15"},{"t":"34","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","70 ÷ 2 = 35 — 확인: 2 × 35 = 70이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#2','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',2,'sa','auto','붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 붙임딱지를 한 명에게 몇 장씩 나누어 줄 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 붙임딱지를 한 명에게 몇 장씩 나누어 줄 수 있나요? 숫자로 쓰세요.","answer":["16"],"explanation":["전체 붙임딱지 수를 사람 수로 나누어요 — 식은 80 ÷ 5.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 몫 16은 한 명이 받는 붙임딱지 수예요."],"variant_rule":{"alt":[{"stem":"달걀 90개를 바구니 6개에 똑같이 나누어 담으려고 해요. 바구니 한 개에 달걀을 몇 개씩 담으면 되나요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 달걀 수를 바구니 수로 나누어요 — 식은 90 ÷ 6.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 몫 15는 바구니 한 개에 담는 달걀 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#3','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'mc','auto','나눗셈의 몫이 큰 것부터 차례대로 쓴 것은 어느 것인가요? 70 ÷ 5, 50 ÷ 2, 60 ÷ 4',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":3,"concept":"M3-2-u2-C2","difficulty":3,"kind":"mc","stem":"나눗셈의 몫이 큰 것부터 차례대로 쓴 것은 어느 것인가요? 70 ÷ 5, 50 ÷ 2, 60 ÷ 4","options":[{"t":"50 ÷ 2, 60 ÷ 4, 70 ÷ 5","correct":true},{"t":"70 ÷ 5, 60 ÷ 4, 50 ÷ 2","mis":"M3-2-u2-X17"},{"t":"70 ÷ 5, 50 ÷ 2, 60 ÷ 4","mis":"M3-2-u2-X15"},{"t":"60 ÷ 4, 50 ÷ 2, 70 ÷ 5","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","70 ÷ 5 = 14, 50 ÷ 2 = 25, 60 ÷ 4 = 15.","몫이 큰 것부터 — 50 ÷ 2, 60 ÷ 4, 70 ÷ 5."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#4','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'sa','auto','지아가 90 ÷ 5를 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C2","difficulty":3,"kind":"sa","stem":"지아가 90 ÷ 5를 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["지아 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 40 ÷ 5 → 몫 8.","바른 몫은 18 — 확인: 5 × 18 = 90이에요."],"variant_rule":{"alt":[{"stem":"소율이 70 ÷ 2를 계산하고 몫을 30이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["소율 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바른 몫은 35 — 확인: 2 × 35 = 70이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#5','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'sa','auto','70 ÷ 5에서 십의 자리 7을 5로 나누면 몫 1이 서고 2가 남아요. 남은 수와 일의 자리 수 0을 더하면 몇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C2","difficulty":3,"kind":"sa","stem":"70 ÷ 5에서 십의 자리 7을 5로 나누면 몫 1이 서고 2가 남아요. 남은 수와 일의 자리 수 0을 더하면 몇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["십의 자리에서 남은 2는 20을 뜻해요.","20 + 0 = 20이에요.","20 ÷ 5 = 4 — 몫은 1과 4를 이어 14예요."],"asset":{"type":"ldiv","a":70,"b":5,"hide":[["r",1]]},"variant_rule":{"alt":[{"stem":"90 ÷ 6에서 십의 자리 9를 6으로 나누면 몫 1이 서고 3이 남아요. 남은 수와 일의 자리 수 0을 더하면 몇인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["십의 자리에서 남은 3은 30을 뜻해요.","30 + 0 = 30이에요.","30 ÷ 6 = 5 — 몫은 1과 5를 이어 15예요."],"asset":{"type":"ldiv","a":90,"b":6,"hide":[["r",1]]}},{"stem":"50 ÷ 2에서 십의 자리 5를 2로 나누면 몫 2가 서고 1이 남아요. 남은 수와 일의 자리 수 0을 더하면 몇인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["십의 자리에서 남은 1은 10을 뜻해요.","10 + 0 = 10이에요.","10 ÷ 2 = 5 — 몫은 2와 5를 이어 25예요."],"asset":{"type":"ldiv","a":50,"b":2,"hide":[["r",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#6','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'mc','auto','공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03']::text[],false,'{"seq":6,"concept":"M3-2-u2-C2","difficulty":3,"kind":"mc","stem":"공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한가요?","options":[{"t":"14개","correct":true},{"t":"65개","mis":"M3-2-u2-X14"},{"t":"350개","mis":"M3-2-u2-X14"},{"t":"10개","mis":"M3-2-u2-X03"}],"explanation":["전체 공깃돌 수를 주머니 한 개에 담는 공깃돌 수로 나누어요 — 식은 70 ÷ 5.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 몫 14는 필요한 주머니 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#7','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',3,'error','auto','60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C2","difficulty":3,"kind":"error","stem":"60 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「60 ÷ 5 = 10이야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지아 — 「60 ÷ 5 = 12야」","mis":"M3-2-u2-X17"},{"t":"민서 — 「60 ÷ 5는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 5 → 몫 2.","바르게 계산하면 60 ÷ 5 = 12.","민준이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"90 ÷ 2를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「90 ÷ 2 = 46이야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"소율 — 「90 ÷ 2 = 45야」","mis":"M3-2-u2-X17"},{"t":"민서 — 「확인하면 2 × 45 = 90이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 2 → 몫 4, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","바르게 계산하면 90 ÷ 2 = 45.","지아가 잘못 말했어요 — 나누는 수 × 몫으로 확인."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#8','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'essay','teacher','공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심어요. 10 카드와 1 카드를 써서 30 ÷ 2를 구하는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C2","difficulty":4,"kind":"essay","stem":"공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심어요. 10 카드와 1 카드를 써서 30 ÷ 2를 구하는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 30은 10 카드 3장이다. 10 카드를 2곳에 1장씩 놓으면 1장이 남는다. 남은 10 카드 1장을 1 카드 10장으로 바꾸어 2곳에 5장씩 놓으면 한 곳에 10 카드 1장과 1 카드 5장이 놓인다. 화단 한 개에 15포기씩 심는다.","scoring_points":["10 카드를 1장씩 놓고 1장이 남는다고 했는가","남은 10 카드를 1 카드 10장으로 바꾸어 나누었는가","15포기라고 답했는가"]},"explanation":["10 카드 3장 → 2곳에 1장씩, 1장 남음.","1 카드 10장 → 2곳에 5장씩.","10 + 5 = 15 — 몫 15는 화단 한 개에 심는 금잔화 수예요."],"asset":{"type":"ldiv","a":30,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#9','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'essay','teacher','공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C2","difficulty":4,"kind":"essay","stem":"공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 전체 공깃돌의 수를 주머니 한 개에 담는 공깃돌의 수로 나누면 되므로 70 ÷ 5를 계산한다. 7 ÷ 5 = 1 … 2이고 남은 20을 5로 나누면 4이므로 70 ÷ 5 = 14이다. 주머니는 14개 필요하다.","scoring_points":["식 70 ÷ 5를 세웠는가","남은 수를 내려 14를 구했는가","주머니 14개라고 답했는가"]},"explanation":["전체 공깃돌 수 ÷ 한 주머니에 담는 수 — 식은 70 ÷ 5.","7 ÷ 5 → 몫 1, 2 남음 · 남은 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 주머니는 14개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L03_challenge#10','math',3,2,'u2','L03','tb_g3_2_math_u2_L03_challenge','lesson_challenge','M3-2-u2-C2',4,'essay','teacher','친구가 80 ÷ 5를 세로셈으로 계산하고 몫을 61이라고 썼어요. 잘못된 점을 찾고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C2","difficulty":4,"kind":"essay","stem":"친구가 80 ÷ 5를 세로셈으로 계산하고 몫을 61이라고 썼어요. 잘못된 점을 찾고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 몫을 쓰는 자리가 바뀌었다. 십의 자리 8을 5로 나눈 몫 1은 몫의 십의 자리에, 남은 30을 5로 나눈 몫 6은 몫의 일의 자리에 써야 한다. 80 ÷ 5 = 16이고, 확인하면 5 × 16 = 80이다.","scoring_points":["몫을 쓰는 자리가 바뀌었다고 찾았는가","80 ÷ 5 = 16을 구했는가","5 × 16 = 80으로 확인했는가"]},"explanation":["8 ÷ 5 → 몫 1은 십의 자리에.","남은 30 ÷ 5 → 몫 6은 일의 자리에 — 80 ÷ 5 = 16.","5 × 16 = 80 — 61이 아니라 16이에요."],"asset":{"type":"ldiv","a":80,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#1','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'sa','auto','26 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"26 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 6 ÷ 2 → 몫 3.","26 ÷ 2 = 13 — 확인: 2 × 13 = 26이에요."],"variant_rule":{"alt":[{"stem":"93 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","93 ÷ 3 = 31 — 확인: 3 × 31 = 93이에요."]},{"stem":"84 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","84 ÷ 4 = 21 — 확인: 4 × 21 = 84예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#2','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C4',1,'mc','auto','배지 26개를 한 명에게 2개씩 나누어 줄 때, 계산하기 전에 26 ÷ 2의 몫을 어림하면 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"배지 26개를 한 명에게 2개씩 나누어 줄 때, 계산하기 전에 26 ÷ 2의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"10과 15 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"15보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 150 사이","mis":"M3-2-u2-X02"}],"explanation":["26을 20으로 보면 20 ÷ 2 = 10이에요.","26을 30으로 보면 30 ÷ 2 = 15예요.","그래서 몫은 10과 15 사이 — 실제로 계산한 몫 13이에요."],"variant_rule":{"alt":[{"stem":"학생 28명이 2명씩 짝을 지을 때, 계산하기 전에 28 ÷ 2의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"10과 15 사이","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"15보다 커요","mis":"M3-2-u2-X16"},{"t":"100과 150 사이","mis":"M3-2-u2-X02"}],"explanation":["28을 20으로 보면 20 ÷ 2 = 10이에요.","28을 30으로 보면 30 ÷ 2 = 15예요.","그래서 몫은 10과 15 사이 — 실제로 계산한 몫 14예요."]},{"stem":"계산하기 전에 46 ÷ 2의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"20과 25 사이","correct":true},{"t":"20보다 작아요","mis":"M3-2-u2-X16"},{"t":"25보다 커요","mis":"M3-2-u2-X16"},{"t":"200과 250 사이","mis":"M3-2-u2-X02"}],"explanation":["46을 40으로 보면 40 ÷ 2 = 20이에요.","46을 50으로 보면 50 ÷ 2 = 25예요.","그래서 몫은 20과 25 사이 — 실제로 계산한 몫 23이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#3','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'sa','auto','배지 26개를 한 명에게 2개씩 나누어 주는 것을 수 카드로 알아봐요. 10 카드 2장과 1 카드 6장에서 10 카드 2장을 1 카드로 바꾸면 1 카드 몇 장이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"배지 26개를 한 명에게 2개씩 나누어 주는 것을 수 카드로 알아봐요. 10 카드 2장과 1 카드 6장에서 10 카드 2장을 1 카드로 바꾸면 1 카드 몇 장이 되나요? 숫자로 쓰세요.","answer":["20"],"explanation":["10 카드 1장은 1 카드 10장이에요.","10 카드 2장은 1 카드 20장 — 원래 있던 6장과 모두 26장이 돼요.","1 카드 26장을 2장씩 묶으면 13묶음 — 26 ÷ 2 = 13이에요."],"variant_rule":{"alt":[{"stem":"감귤 39개로 한 컵에 3개씩 주스를 만드는 것을 수 카드로 알아봐요. 10 카드 3장과 1 카드 9장에서 10 카드 3장을 1 카드로 바꾸면 1 카드 몇 장이 되나요? 숫자로 쓰세요.","answer":["30"],"explanation":["10 카드 1장은 1 카드 10장이에요.","10 카드 3장은 1 카드 30장 — 원래 있던 9장과 모두 39장이 돼요.","1 카드 39장을 3장씩 묶으면 13묶음 — 39 ÷ 3 = 13이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#4','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',1,'mc','auto','배지 26개를 한 명에게 2개씩 나누어 주면 26 ÷ 2 = 13이에요. 몫 13은 무엇을 나타내나요?',ARRAY['M3-2-u2-X13','M3-2-u2-X17']::text[],false,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"배지 26개를 한 명에게 2개씩 나누어 주면 26 ÷ 2 = 13이에요. 몫 13은 무엇을 나타내나요?","options":[{"t":"배지를 나누어 줄 수 있는 사람 수","correct":true},{"t":"한 명이 받는 배지 수","mis":"M3-2-u2-X13"},{"t":"남는 배지 수","mis":"M3-2-u2-X13"},{"t":"전체 배지 수","mis":"M3-2-u2-X17"}],"explanation":["한 명에게 2개씩 — 2개씩 묶은 묶음의 수를 구하는 나눗셈이에요.","26에서 20은 2씩 10묶음, 남은 6은 2씩 3묶음 — 모두 13묶음.","몫 13은 배지를 나누어 줄 수 있는 사람 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#5','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'sa','auto','93 ÷ 3의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"93 ÷ 3의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","93 ÷ 3 = 31 — 몫의 십의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":93,"b":3,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"84 ÷ 4의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","84 ÷ 4 = 21 — 몫의 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":84,"b":4,"hide":[["q",0]]}},{"stem":"64 ÷ 2의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 4 ÷ 2 → 몫 2.","64 ÷ 2 = 32 — 몫의 십의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":64,"b":2,"hide":[["q",0]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#6','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'ox','auto','39 ÷ 3 = 31이에요.',ARRAY['M3-2-u2-X04']::text[],true,'{"seq":6,"concept":"M3-2-u2-C3","difficulty":2,"kind":"ox","stem":"39 ÷ 3 = 31이에요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"mis":"M3-2-u2-X04","explanation":["십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 9 ÷ 3 → 몫 3.","바르게 계산하면 39 ÷ 3 = 13.","높은 자리부터 그 자리 위에 — 확인: 3 × 13 = 39예요."],"variant_rule":{"alt":[{"stem":"93 ÷ 3 = 13이에요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"explanation":["십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","바르게 계산하면 93 ÷ 3 = 31.","높은 자리부터 그 자리 위에 — 확인: 3 × 31 = 93이에요."]},{"stem":"84 ÷ 4 = 12예요.","answer":"X","reason_options":[{"t":"몫은 높은 자리부터 그 자리 위에 써야 해서","correct":true},{"t":"몫은 낮은 자리부터 써도 되어서","mis":"M3-2-u2-X04"}],"explanation":["십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","바르게 계산하면 84 ÷ 4 = 21.","높은 자리부터 그 자리 위에 — 확인: 4 × 21 = 84예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#7','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'mc','auto','감귤이 39개 있어요. 감귤주스 한 컵을 만드는 데 감귤이 3개 필요해요. 감귤주스는 모두 몇 컵을 만들 수 있나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X04']::text[],true,'{"seq":7,"concept":"M3-2-u2-C3","difficulty":2,"kind":"mc","stem":"감귤이 39개 있어요. 감귤주스 한 컵을 만드는 데 감귤이 3개 필요해요. 감귤주스는 모두 몇 컵을 만들 수 있나요?","options":[{"t":"13컵","correct":true},{"t":"36컵","mis":"M3-2-u2-X14"},{"t":"117컵","mis":"M3-2-u2-X14"},{"t":"31컵","mis":"M3-2-u2-X04"}],"explanation":["전체 감귤 수를 한 컵에 드는 감귤 수로 나누어요 — 식은 39 ÷ 3.","십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 9 ÷ 3 → 몫 3.","39 ÷ 3 = 13 — 몫 13은 만들 수 있는 감귤주스 컵 수예요."],"variant_rule":{"alt":[{"stem":"환경 보호 배지 63개를 한 명에게 3개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요?","options":[{"t":"21명","correct":true},{"t":"60명","mis":"M3-2-u2-X14"},{"t":"189명","mis":"M3-2-u2-X14"},{"t":"12명","mis":"M3-2-u2-X04"}],"explanation":["전체 배지 수를 한 명에게 주는 배지 수로 나누어요 — 식은 63 ÷ 3.","십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 3 ÷ 3 → 몫 1.","63 ÷ 3 = 21 — 몫 21은 배지를 받는 사람 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#8','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'mc','auto','몫이 다른 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":8,"concept":"M3-2-u2-C3","difficulty":2,"kind":"mc","stem":"몫이 다른 나눗셈은 어느 것인가요?","options":[{"t":"66 ÷ 6","correct":true},{"t":"44 ÷ 2","mis":"M3-2-u2-X15"},{"t":"66 ÷ 3","mis":"M3-2-u2-X15"},{"t":"88 ÷ 4","mis":"M3-2-u2-X15"}],"explanation":["44 ÷ 2 = 22, 66 ÷ 3 = 22, 88 ÷ 4 = 22.","66 ÷ 6 = 11이에요.","그래서 몫이 다른 것은 66 ÷ 6 — 나누는 수가 클수록 몫은 작아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#9','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C3","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"68 ÷ 2","r":"34"},{"l":"55 ÷ 5","r":"11"},{"l":"46 ÷ 2","r":"23"}],"mis":"M3-2-u2-X04","explanation":["높은 자리부터 차례로 나누어요.","68 ÷ 2 = 34, 55 ÷ 5 = 11, 46 ÷ 2 = 23.","나누는 수 × 몫 + 나머지로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_basic#10','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_basic','lesson_basic','M3-2-u2-C3',3,'error','auto','84 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C3","difficulty":3,"kind":"error","stem":"84 ÷ 4를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"채원 — 「84 ÷ 4 = 12야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"서윤 — 「84 ÷ 4 = 21이야」","mis":"M3-2-u2-X17"},{"t":"지아 — 「84 ÷ 4는 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","바르게 계산하면 84 ÷ 4 = 21.","채원이 잘못 말했어요 — 높은 자리부터 그 자리 위에."],"variant_rule":{"alt":[{"stem":"69 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「69 ÷ 3 = 24야」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"민준 — 「69 ÷ 3 = 23이야」","mis":"M3-2-u2-X17"},{"t":"지아 — 「확인하면 3 × 23 = 69야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 9 ÷ 3 → 몫 3.","바르게 계산하면 69 ÷ 3 = 23.","서윤이 잘못 말했어요 — 나누는 수 × 몫으로 확인."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#1','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',2,'blank','auto','나눗셈을 계산하여 이야기 「해님과 달님」을 완성해요. 엄마는 오누이에게 문을 열어 주면 안 된다고 36 ÷ 3 = □(번)이나 강조하셨어요. □에 알맞은 수는 어느 것인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X15','M3-2-u2-X14']::text[],true,'{"seq":1,"concept":"M3-2-u2-C3","difficulty":2,"kind":"blank","stem":"나눗셈을 계산하여 이야기 「해님과 달님」을 완성해요. 엄마는 오누이에게 문을 열어 주면 안 된다고 36 ÷ 3 = □(번)이나 강조하셨어요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"12","correct":true},{"t":"21","mis":"M3-2-u2-X04"},{"t":"11","mis":"M3-2-u2-X15"},{"t":"108","mis":"M3-2-u2-X14"}],"explanation":["십의 자리 3 ÷ 3 → 몫 1, 일의 자리 6 ÷ 3 → 몫 2.","36 ÷ 3 = 12예요.","확인: 3 × 12 = 36 — 엄마는 12번이나 강조하셨어요."],"variant_rule":{"alt":[{"stem":"나눗셈을 계산하여 이야기 「해님과 달님」을 완성해요. 엄마는 떡 48 ÷ 2 = □(개)를 들고 시장으로 가셨어요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"24","correct":true},{"t":"42","mis":"M3-2-u2-X04"},{"t":"22","mis":"M3-2-u2-X15"},{"t":"96","mis":"M3-2-u2-X14"}],"explanation":["십의 자리 4 ÷ 2 → 몫 2, 일의 자리 8 ÷ 2 → 몫 4.","48 ÷ 2 = 24예요.","확인: 2 × 24 = 48 — 떡은 24개예요."]},{"stem":"나눗셈을 계산하여 이야기 「해님과 달님」을 완성해요. 호랑이가 찾아왔을 때는 벌써 99 ÷ 9 = □(시)였어요. □에 알맞은 수는 어느 것인가요?","options":[{"t":"11","correct":true},{"t":"9","mis":"M3-2-u2-X15"},{"t":"10","mis":"M3-2-u2-X15"},{"t":"891","mis":"M3-2-u2-X14"}],"explanation":["십의 자리 9 ÷ 9 → 몫 1, 일의 자리 9 ÷ 9 → 몫 1.","99 ÷ 9 = 11이에요.","확인: 9 × 11 = 99 — 벌써 11시였어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#2','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C4',2,'ox','auto','배지 26개를 한 명에게 2개씩 나누어 주면 몇 명에게 줄 수 있는지 계산했더니 31명이 나왔어요. 어림해 보면 알맞은 답이에요.',ARRAY['M3-2-u2-X16']::text[],false,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":2,"kind":"ox","stem":"배지 26개를 한 명에게 2개씩 나누어 주면 몇 명에게 줄 수 있는지 계산했더니 31명이 나왔어요. 어림해 보면 알맞은 답이에요.","answer":"X","reason_options":[{"t":"어림한 10명과 15명 사이에 들지 않아서","correct":true},{"t":"계산했으니 어림은 하지 않아도 되어서","mis":"M3-2-u2-X16"}],"mis":"M3-2-u2-X16","explanation":["20 ÷ 2 = 10, 30 ÷ 2 = 15 — 10명과 15명 사이일 거예요.","31명은 어림한 사이에 들지 않으니 다시 계산해야 해요.","바르게 계산하면 26 ÷ 2 = 13 — 13명이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#3','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'sa','auto','어떤 수를 2로 나누어야 할 것을 잘못하여 2를 곱했더니 84가 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C3","difficulty":3,"kind":"sa","stem":"어떤 수를 2로 나누어야 할 것을 잘못하여 2를 곱했더니 84가 되었어요. 바르게 계산한 값은 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["어떤 수 × 2 = 84 → 어떤 수는 84 ÷ 2 = 42예요.","바르게 계산하면 42 ÷ 2예요.","42 ÷ 2 = 21 — 바르게 계산한 값은 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#4','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'mc','auto','서윤이네 반 학생 28명이 운동장에 서 있어요. 2명씩 짝을 지어 모둠 활동을 해요. 몇 모둠이 되나요?',ARRAY['M3-2-u2-X14','M3-2-u2-X04']::text[],false,'{"seq":4,"concept":"M3-2-u2-C3","difficulty":3,"kind":"mc","stem":"서윤이네 반 학생 28명이 운동장에 서 있어요. 2명씩 짝을 지어 모둠 활동을 해요. 몇 모둠이 되나요?","options":[{"t":"14모둠","correct":true},{"t":"26모둠","mis":"M3-2-u2-X14"},{"t":"56모둠","mis":"M3-2-u2-X14"},{"t":"41모둠","mis":"M3-2-u2-X04"}],"explanation":["전체 학생 수를 한 모둠의 학생 수로 나누어요 — 식은 28 ÷ 2.","십의 자리 2 ÷ 2 → 몫 1 · 일의 자리 8 ÷ 2 → 몫 4.","28 ÷ 2 = 14 — 몫 14는 모둠 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#5','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 36 ÷ 3 ○ 44 ÷ 4',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 36 ÷ 3 ○ 44 ÷ 4","options":[{"t":">","correct":true},{"t":"<","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["36 ÷ 3의 몫은 12예요.","44 ÷ 4의 몫은 11이에요.","12 > 11 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 24 ÷ 2 ○ 36 ÷ 3","options":[{"t":"=","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"<","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["24 ÷ 2의 몫은 12예요.","36 ÷ 3의 몫은 12예요.","12 = 12 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#6','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'sa','auto','민서가 84 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C3","difficulty":3,"kind":"sa","stem":"민서가 84 ÷ 4를 계산하고 몫을 12라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["민서 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","바른 몫은 21 — 확인: 4 × 21 = 84예요."],"variant_rule":{"alt":[{"stem":"태민이 64 ÷ 2를 계산하고 몫을 23이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["태민 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 4 ÷ 2 → 몫 2.","바른 몫은 32 — 확인: 2 × 32 = 64예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#7','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',3,'mc','auto','배지 26개를 「2상자에 똑같이 나누어 담는 것」과 「한 명에게 2개씩 나누어 주는 것」을 견주었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X20','M3-2-u2-X13']::text[],false,'{"seq":7,"concept":"M3-2-u2-C3","difficulty":3,"kind":"mc","stem":"배지 26개를 「2상자에 똑같이 나누어 담는 것」과 「한 명에게 2개씩 나누어 주는 것」을 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 26 ÷ 2 = 13으로 계산하지만 몫 13이 뜻하는 것이 달라요","correct":true},{"t":"「한 명에게 2개씩」은 26 × 2로 계산해요","mis":"M3-2-u2-X14"},{"t":"「2상자에 똑같이」만 나눗셈으로 계산해요","mis":"M3-2-u2-X20"},{"t":"두 상황 모두 몫 13은 남는 배지 수예요","mis":"M3-2-u2-X13"}],"explanation":["2상자에 똑같이 나누면 한 상자에 13개 — 몫은 한 묶음의 수예요.","한 명에게 2개씩 주면 13명에게 줄 수 있어요 — 몫은 묶음의 수예요.","같은 26 ÷ 2 = 13이어도 상황에 따라 몫의 뜻을 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#8','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C4',4,'essay','teacher','환경 보호 배지 26개를 한 명에게 2개씩 나누어 주려고 해요. 계산하기 전에 몇 명에게 줄 수 있을지 어림하고, 26 ÷ 2를 계산한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C4","difficulty":4,"kind":"essay","stem":"환경 보호 배지 26개를 한 명에게 2개씩 나누어 주려고 해요. 계산하기 전에 몇 명에게 줄 수 있을지 어림하고, 26 ÷ 2를 계산한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 배지를 20개로 생각하면 20 ÷ 2 = 10(명), 30개로 생각하면 30 ÷ 2 = 15(명)이므로 약 15명쯤이다. 26에서 20은 2씩 10묶음, 남은 6은 2씩 3묶음이므로 26 ÷ 2 = 13이다. 13명은 어림한 값과 비슷하다.","scoring_points":["20 ÷ 2와 30 ÷ 2로 어림했는가","자리마다 나누어 13을 구했는가","어림한 값과 견주었는가"]},"explanation":["20 ÷ 2 = 10, 30 ÷ 2 = 15.","26 ÷ 2 = 13 — 10묶음과 3묶음.","13명은 어림한 값과 비슷해요."],"asset":{"type":"ldiv","a":26,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#9','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',4,'essay','teacher','감귤 39개로 한 컵에 3개씩 감귤주스를 만들어요. 친구가 39 ÷ 3을 세로셈으로 계산하고 몫을 31이라고 썼어요. 잘못된 점을 찾고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C3","difficulty":4,"kind":"essay","stem":"감귤 39개로 한 컵에 3개씩 감귤주스를 만들어요. 친구가 39 ÷ 3을 세로셈으로 계산하고 몫을 31이라고 썼어요. 잘못된 점을 찾고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 몫을 쓰는 자리가 바뀌었다. 십의 자리 3 ÷ 3 = 1은 몫의 십의 자리에, 일의 자리 9 ÷ 3 = 3은 몫의 일의 자리에 써야 하므로 몫은 13이다. 감귤주스는 13컵을 만들 수 있다. 확인하면 3 × 13 = 39이다.","scoring_points":["몫의 자리가 바뀌었다고 찾았는가","39 ÷ 3 = 13을 구했는가","곱셈으로 확인했는가"]},"explanation":["3 ÷ 3 = 1 → 몫의 십의 자리.","9 ÷ 3 = 3 → 몫의 일의 자리 — 39 ÷ 3 = 13.","3 × 13 = 39 — 31이 아니라 13이에요."],"asset":{"type":"ldiv","a":39,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L04_challenge#10','math',3,2,'u2','L04','tb_g3_2_math_u2_L04_challenge','lesson_challenge','M3-2-u2-C3',4,'essay','teacher','좋아하는 이야기 속 두 자리 수를 (몇십몇) ÷ (몇)의 나눗셈으로 바꾸어 짧은 이야기를 만들고, 나눗셈의 몫을 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C3","difficulty":4,"kind":"essay","stem":"좋아하는 이야기 속 두 자리 수를 (몇십몇) ÷ (몇)의 나눗셈으로 바꾸어 짧은 이야기를 만들고, 나눗셈의 몫을 구해 보세요.","answer_guide":{"answer":"예: 엄마는 떡 48 ÷ 2개를 들고 시장에 가셨어요. → 48 ÷ 2 = 24이므로 떡은 24개이다. (십의 자리 4 ÷ 2 = 2, 일의 자리 8 ÷ 2 = 4)","scoring_points":["이야기 속 수를 (몇십몇) ÷ (몇)으로 바꾸었는가","몫을 바르게 구했는가","몫이 이야기에서 무엇을 뜻하는지 썼는가"]},"explanation":["두 자리 수를 나눗셈식으로 바꾸어 이야기에 넣어요.","십의 자리와 일의 자리를 차례로 나누어 몫을 구해요.","친구의 이야기에서 나눗셈이 어떻게 쓰였는지 찾아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#1','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'sa','auto','45 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"45 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","45 ÷ 3 = 15 — 확인: 3 × 15 = 45예요."],"variant_rule":{"alt":[{"stem":"52 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","52 ÷ 4 = 13 — 확인: 4 × 13 = 52예요."]},{"stem":"87 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","87 ÷ 3 = 29 — 확인: 3 × 29 = 87이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#2','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'sa','auto','45 ÷ 3에서 십의 자리 4를 3으로 나누면 몫 1이 서고 1이 남아요. 남은 수와 일의 자리 수 5를 더하면 몇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"45 ÷ 3에서 십의 자리 4를 3으로 나누면 몫 1이 서고 1이 남아요. 남은 수와 일의 자리 수 5를 더하면 몇인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["십의 자리에서 남은 1은 10을 뜻해요.","10 + 5 = 15예요.","15 ÷ 3 = 5 — 몫은 1과 5를 이어 15예요."],"asset":{"type":"ldiv","a":45,"b":3,"hide":[["r",1]]},"variant_rule":{"alt":[{"stem":"52 ÷ 4에서 십의 자리 5를 4로 나누면 몫 1이 서고 1이 남아요. 남은 수와 일의 자리 수 2를 더하면 몇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["십의 자리에서 남은 1은 10을 뜻해요.","10 + 2 = 12예요.","12 ÷ 4 = 3 — 몫은 1과 3을 이어 13이에요."],"asset":{"type":"ldiv","a":52,"b":4,"hide":[["r",1]]}},{"stem":"87 ÷ 3에서 십의 자리 8을 3으로 나누면 몫 2가 서고 2가 남아요. 남은 수와 일의 자리 수 7을 더하면 몇인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["십의 자리에서 남은 2는 20을 뜻해요.","20 + 7 = 27이에요.","27 ÷ 3 = 9 — 몫은 2와 9를 이어 29예요."],"asset":{"type":"ldiv","a":87,"b":3,"hide":[["r",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#3','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'mc','auto','96 ÷ 8은 얼마인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"mc","stem":"96 ÷ 8은 얼마인가요?","options":[{"t":"12","correct":true},{"t":"10","mis":"M3-2-u2-X03"},{"t":"21","mis":"M3-2-u2-X04"},{"t":"13","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 8 → 몫 2.","96 ÷ 8 = 12 — 확인: 8 × 12 = 96이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 2는 얼마인가요?","options":[{"t":"18","correct":true},{"t":"13","mis":"M3-2-u2-X03"},{"t":"81","mis":"M3-2-u2-X04"},{"t":"19","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 2 → 몫 8.","36 ÷ 2 = 18 — 확인: 2 × 18 = 36이에요."]},{"stem":"72 ÷ 3은 얼마인가요?","options":[{"t":"24","correct":true},{"t":"20","mis":"M3-2-u2-X03"},{"t":"42","mis":"M3-2-u2-X04"},{"t":"25","mis":"M3-2-u2-X15"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 3 → 몫 4.","72 ÷ 3 = 24 — 확인: 3 × 24 = 72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#4','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',1,'mc','auto','45 ÷ 3을 수 카드로 계산해요. 10 카드 4장과 1 카드 5장을 3곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X15']::text[],true,'{"seq":4,"concept":"M3-2-u2-C5","difficulty":1,"kind":"mc","stem":"45 ÷ 3을 수 카드로 계산해요. 10 카드 4장과 1 카드 5장을 3곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 1장, 1 카드 5장","correct":true},{"t":"10 카드 1장, 1 카드 1장","mis":"M3-2-u2-X03"},{"t":"10 카드 5장, 1 카드 1장","mis":"M3-2-u2-X04"},{"t":"10 카드 1장, 1 카드 6장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 4장을 3곳에 1장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 15장 — 3곳에 5장씩 놓아요.","한 곳에 10 카드 1장과 1 카드 5장 — 15예요."],"variant_rule":{"alt":[{"stem":"52 ÷ 4를 수 카드로 계산해요. 10 카드 5장과 1 카드 2장을 4곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 1장, 1 카드 3장","correct":true},{"t":"10 카드 1장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 3장, 1 카드 1장","mis":"M3-2-u2-X04"},{"t":"10 카드 1장, 1 카드 4장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 5장을 4곳에 1장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 12장 — 4곳에 3장씩 놓아요.","한 곳에 10 카드 1장과 1 카드 3장 — 13이에요."]},{"stem":"72 ÷ 3을 수 카드로 계산해요. 10 카드 7장과 1 카드 2장을 3곳에 똑같이 나누어 놓으면 한 곳에 놓이는 카드는 어느 것인가요?","options":[{"t":"10 카드 2장, 1 카드 4장","correct":true},{"t":"10 카드 2장, 1 카드 0장","mis":"M3-2-u2-X03"},{"t":"10 카드 4장, 1 카드 2장","mis":"M3-2-u2-X04"},{"t":"10 카드 2장, 1 카드 5장","mis":"M3-2-u2-X15"}],"explanation":["10 카드 7장을 3곳에 2장씩 놓으면 1장이 남아요.","남은 10 카드 1장을 1 카드 10장으로 바꾸면 1 카드는 12장 — 3곳에 4장씩 놓아요.","한 곳에 10 카드 2장과 1 카드 4장 — 24예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#5','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'mc','auto','노인 복지관에 오시는 분들께 드릴 손수건 45장을 상자 3개에 똑같이 나누어 담으려고 해요. 상자 한 개에 담을 수 있는 손수건은 몇 장인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03']::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":2,"kind":"mc","stem":"노인 복지관에 오시는 분들께 드릴 손수건 45장을 상자 3개에 똑같이 나누어 담으려고 해요. 상자 한 개에 담을 수 있는 손수건은 몇 장인가요?","options":[{"t":"15장","correct":true},{"t":"42장","mis":"M3-2-u2-X14"},{"t":"135장","mis":"M3-2-u2-X14"},{"t":"11장","mis":"M3-2-u2-X03"}],"explanation":["전체 손수건 수를 상자 수로 나누어요 — 식은 45 ÷ 3.","십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","45 ÷ 3 = 15 — 몫 15는 상자 한 개에 담는 손수건 수예요."],"variant_rule":{"alt":[{"stem":"노인 복지관에 오시는 분들께 드릴 손수건 52장을 상자 2개에 똑같이 나누어 담으려고 해요. 상자 한 개에 담을 수 있는 손수건은 몇 장인가요?","options":[{"t":"26장","correct":true},{"t":"50장","mis":"M3-2-u2-X14"},{"t":"104장","mis":"M3-2-u2-X14"},{"t":"21장","mis":"M3-2-u2-X03"}],"explanation":["전체 손수건 수를 상자 수로 나누어요 — 식은 52 ÷ 2.","십의 자리 5 ÷ 2 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 2 → 몫 6.","52 ÷ 2 = 26 — 몫 26은 상자 한 개에 담는 손수건 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#6','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'sa','auto','45 ÷ 3을 30과 15로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"45 ÷ 3을 30과 15로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["45를 30과 15로 갈라요 — 둘 다 3으로 나누어떨어져요.","30 ÷ 3 = 10, 15 ÷ 3 = 5예요.","10 + 5 = 15 — 45 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["30 ÷ 3","=","10"],["15 ÷ 3","=",null],["10 + □","=","15"]]},"variant_rule":{"alt":[{"stem":"52 ÷ 4를 40과 12로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["52를 40과 12로 갈라요 — 둘 다 4로 나누어떨어져요.","40 ÷ 4 = 10, 12 ÷ 4 = 3이에요.","10 + 3 = 13 — 52 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["40 ÷ 4","=","10"],["12 ÷ 4","=",null],["10 + □","=","13"]]}},{"stem":"87 ÷ 3을 60과 27로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["87을 60과 27로 갈라요 — 둘 다 3으로 나누어떨어져요.","60 ÷ 3 = 20, 27 ÷ 3 = 9예요.","20 + 9 = 29 — 87 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 3","=","20"],["27 ÷ 3","=",null],["20 + □","=","29"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#7','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'ox','auto','36 ÷ 2 = 13이에요.',ARRAY['M3-2-u2-X03']::text[],true,'{"seq":7,"concept":"M3-2-u2-C5","difficulty":2,"kind":"ox","stem":"36 ÷ 2 = 13이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"mis":"M3-2-u2-X03","explanation":["십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 2 → 몫 8.","바르게 계산하면 36 ÷ 2 = 18.","남은 수는 아래로 내리기 — 확인: 2 × 18 = 36이에요."],"asset":{"type":"ldiv","a":36,"b":2,"upto":0},"variant_rule":{"alt":[{"stem":"52 ÷ 4 = 10이에요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","바르게 계산하면 52 ÷ 4 = 13.","남은 수는 아래로 내리기 — 확인: 4 × 13 = 52예요."],"asset":{"type":"ldiv","a":52,"b":4,"upto":0}},{"stem":"87 ÷ 3 = 22예요.","answer":"X","reason_options":[{"t":"남은 수는 아래 자리로 내려 함께 나누어야 해서","correct":true},{"t":"남은 수는 버려도 되어서","mis":"M3-2-u2-X03"}],"explanation":["십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","바르게 계산하면 87 ÷ 3 = 29.","남은 수는 아래로 내리기 — 확인: 3 × 29 = 87이에요."],"asset":{"type":"ldiv","a":87,"b":3,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#8','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'sa','auto','87 ÷ 3의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"87 ÷ 3의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["9"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","87 ÷ 3 = 29 — 몫의 일의 자리 숫자는 9예요."],"asset":{"type":"ldiv","a":87,"b":3,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"52 ÷ 4의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 5 ÷ 4 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 4 → 몫 3.","52 ÷ 4 = 13 — 몫의 일의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":52,"b":4,"hide":[["q",1]]}},{"stem":"96 ÷ 8의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 8 → 몫 2.","96 ÷ 8 = 12 — 몫의 일의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":96,"b":8,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#9','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',2,'mc','auto','나눗셈의 몫이 큰 것부터 차례대로 쓴 것은 어느 것인가요? ㉠ 34 ÷ 2, ㉡ 72 ÷ 6, ㉢ 91 ÷ 7, ㉣ 64 ÷ 4',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":9,"concept":"M3-2-u2-C5","difficulty":2,"kind":"mc","stem":"나눗셈의 몫이 큰 것부터 차례대로 쓴 것은 어느 것인가요? ㉠ 34 ÷ 2, ㉡ 72 ÷ 6, ㉢ 91 ÷ 7, ㉣ 64 ÷ 4","options":[{"t":"㉠, ㉣, ㉢, ㉡","correct":true},{"t":"㉡, ㉢, ㉣, ㉠","mis":"M3-2-u2-X17"},{"t":"㉠, ㉡, ㉢, ㉣","mis":"M3-2-u2-X15"},{"t":"㉣, ㉠, ㉢, ㉡","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","34 ÷ 2 = 17, 72 ÷ 6 = 12, 91 ÷ 7 = 13, 64 ÷ 4 = 16.","몫이 큰 것부터 — ㉠, ㉣, ㉢, ㉡."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_basic#10','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_basic','lesson_basic','M3-2-u2-C5',3,'error','auto','87 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X17']::text[],true,'{"seq":10,"concept":"M3-2-u2-C5","difficulty":3,"kind":"error","stem":"87 ÷ 3을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「87 ÷ 3 = 22야」","correct":true,"mis_target":"M3-2-u2-X03"},{"t":"지아 — 「87 ÷ 3 = 29야」","mis":"M3-2-u2-X17"},{"t":"민서 — 「87 ÷ 3은 나누어떨어져」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","바르게 계산하면 87 ÷ 3 = 29.","민준이 잘못 말했어요 — 남은 수는 아래로 내리기."],"variant_rule":{"alt":[{"stem":"96 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「96 ÷ 8 = 21이야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"소율 — 「96 ÷ 8 = 12야」","mis":"M3-2-u2-X17"},{"t":"민서 — 「확인하면 8 × 12 = 96이야」","mis":"M3-2-u2-X17"}],"explanation":["십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 16 ÷ 8 → 몫 2.","바르게 계산하면 96 ÷ 8 = 12.","지아가 잘못 말했어요 — 높은 자리부터 그 자리 위에."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#1','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',2,'mc','auto','54를 2로 나눈 몫과 3으로 나눈 몫을 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X03','M3-2-u2-X17']::text[],false,'{"seq":1,"concept":"M3-2-u2-C5","difficulty":2,"kind":"mc","stem":"54를 2로 나눈 몫과 3으로 나눈 몫을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"27, 18","correct":true},{"t":"72, 81","mis":"M3-2-u2-X04"},{"t":"22, 11","mis":"M3-2-u2-X03"},{"t":"18, 27","mis":"M3-2-u2-X17"}],"explanation":["54 ÷ 2 — 5 ÷ 2 = 2 … 1, 남은 1을 내려 14 ÷ 2 = 7 → 27.","54 ÷ 3 — 5 ÷ 3 = 1 … 2, 남은 2를 내려 24 ÷ 3 = 8 → 18.","확인: 2 × 27 = 54, 3 × 18 = 54."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#2','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',2,'sa','auto','윷가락 76개를 한 상자에 4개씩 담으려고 해요. 상자는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C5","difficulty":2,"kind":"sa","stem":"윷가락 76개를 한 상자에 4개씩 담으려고 해요. 상자는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["19"],"explanation":["전체 윷가락 수를 한 상자에 담는 윷가락 수로 나누어요 — 식은 76 ÷ 4.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 36 ÷ 4 → 몫 9.","76 ÷ 4 = 19 — 몫 19는 필요한 상자 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#3','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','나눗셈과 곱셈의 계산 결과가 같도록 □ 안에 알맞은 수를 쓰세요. 96 ÷ 2 = 3 × □','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"나눗셈과 곱셈의 계산 결과가 같도록 □ 안에 알맞은 수를 쓰세요. 96 ÷ 2 = 3 × □","answer":["16"],"explanation":["96 ÷ 2 = 48이에요.","3 × □ = 48이니 □는 48 ÷ 3 = 16이에요.","확인: 3 × 16 = 48."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#4','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'mc','auto','정후는 파란색 구슬 65개, 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이를 5개 만들려고 해요. 목걸이 한 개에 사용하는 파란색 구슬과 빨간색 구슬의 개수를 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X03','M3-2-u2-X04','M3-2-u2-X17']::text[],false,'{"seq":4,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"정후는 파란색 구슬 65개, 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이를 5개 만들려고 해요. 목걸이 한 개에 사용하는 파란색 구슬과 빨간색 구슬의 개수를 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"13개, 17개","correct":true},{"t":"11개, 11개","mis":"M3-2-u2-X03"},{"t":"31개, 71개","mis":"M3-2-u2-X04"},{"t":"17개, 13개","mis":"M3-2-u2-X17"}],"explanation":["파란색 구슬: 65 ÷ 5 = 13.","빨간색 구슬: 85 ÷ 5 = 17.","목걸이 한 개에 파란색 13개, 빨간색 17개를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#5','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','소율이 76 ÷ 4를 계산하고 몫을 11이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"소율이 76 ÷ 4를 계산하고 몫을 11이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["소율 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 4 → 몫 1, 3 남음 · 남은 3을 내려 36 ÷ 4 → 몫 9.","바른 몫은 19 — 확인: 4 × 19 = 76이에요."],"variant_rule":{"alt":[{"stem":"민서가 72 ÷ 3을 계산하고 몫을 20이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["민서 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 12 ÷ 3 → 몫 4.","바른 몫은 24 — 확인: 3 × 24 = 72예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#6','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'mc','auto','45 ÷ 3을 수 카드로 계산해요. 남은 10 카드 1장을 1 카드 10장으로 바꾼 뒤 두 친구가 1 카드를 3곳에 놓았어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":6,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"45 ÷ 3을 수 카드로 계산해요. 남은 10 카드 1장을 1 카드 10장으로 바꾼 뒤 두 친구가 1 카드를 3곳에 놓았어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 방법 모두 한 곳에 1 카드가 5장씩 놓여요","correct":true},{"t":"1장씩 번갈아 놓아야만 맞아요","mis":"M3-2-u2-X17"},{"t":"2장씩 놓으면 한 곳에 1 카드가 6장씩 놓여요","mis":"M3-2-u2-X15"}],"explanation":["1 카드는 원래 있던 5장과 바꾼 10장 — 모두 15장이에요.","1장씩 놓든 2장씩 놓든 15장을 3곳에 똑같이 나누면 5장씩이에요.","한 곳에 10 카드 1장과 1 카드 5장 — 45 ÷ 3 = 15예요."],"asset":{"type":"speech","turns":[{"who":"채원","text":"나는 1 카드를 한 장씩 3곳에 번갈아 놓았어."},{"who":"서윤","text":"나는 1 카드를 2장씩 번갈아 놓다가 남은 것은 1장씩 놓았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#7','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',3,'sa','auto','수 모형으로 45 ÷ 3을 해요. 십 모형 4개와 일 모형 5개를 3묶음으로 똑같이 나누는데, 십 모형을 1개씩 나누고 남은 십 모형 1개를 일 모형으로 바꾸었어요. 일 모형은 모두 몇 개가 되나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u2-C5","difficulty":3,"kind":"sa","stem":"수 모형으로 45 ÷ 3을 해요. 십 모형 4개와 일 모형 5개를 3묶음으로 똑같이 나누는데, 십 모형을 1개씩 나누고 남은 십 모형 1개를 일 모형으로 바꾸었어요. 일 모형은 모두 몇 개가 되나요? 숫자로 쓰세요.","answer":["15"],"explanation":["십 모형 4개를 3묶음에 1개씩 나누면 1개가 남아요.","남은 십 모형 1개는 일 모형 10개 — 원래 있던 5개와 모두 15개예요.","일 모형 15개를 3묶음에 5개씩 — 45 ÷ 3 = 15예요."],"asset":{"type":"blocks3","h":0,"t":4,"o":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#8','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'essay','teacher','노인 복지관에 드릴 손수건 45장을 상자 3개에 똑같이 나누어 담아요. 45 ÷ 3을 세로셈으로 계산하는 방법을 쓰고, 십의 자리에서 남은 수를 어떻게 했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C5","difficulty":4,"kind":"essay","stem":"노인 복지관에 드릴 손수건 45장을 상자 3개에 똑같이 나누어 담아요. 45 ÷ 3을 세로셈으로 계산하는 방법을 쓰고, 십의 자리에서 남은 수를 어떻게 했는지 설명해 보세요.","answer_guide":{"answer":"예: 십의 자리 4를 3으로 나눈 몫 1을 몫의 십의 자리에 쓰면 1이 남는다. 남은 1은 10을 뜻하므로 일의 자리 5와 더한 15를 3으로 나누어 몫 5를 몫의 일의 자리에 쓴다. 45 ÷ 3 = 15이므로 상자 한 개에 15장씩 담는다. 확인하면 3 × 15 = 45이다.","scoring_points":["4 ÷ 3에서 1이 남는다고 했는가","남은 수와 일의 자리 수를 더한 15를 다시 나누었는가","15장이라고 답하고 확인했는가"]},"explanation":["4 ÷ 3 → 몫 1, 1 남음.","남은 10과 5를 더해 15 ÷ 3 = 5.","45 ÷ 3 = 15 — 3 × 15 = 45."],"asset":{"type":"ldiv","a":45,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#9','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'essay','teacher','친구가 36 ÷ 2를 세로셈으로 계산하면서 「3 ÷ 2 = 1, 6 ÷ 2 = 3이니까 몫은 13」이라고 했어요. 잘못된 점을 찾고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C5","difficulty":4,"kind":"essay","stem":"친구가 36 ÷ 2를 세로셈으로 계산하면서 「3 ÷ 2 = 1, 6 ÷ 2 = 3이니까 몫은 13」이라고 했어요. 잘못된 점을 찾고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 십의 자리 3을 2로 나누면 몫 1이 서고 1이 남는데, 남은 1(10)을 버렸다. 남은 10과 일의 자리 6을 더한 16을 2로 나누면 8이므로 36 ÷ 2 = 18이다. 확인하면 2 × 18 = 36이다.","scoring_points":["십의 자리에서 남은 수를 버렸다고 찾았는가","16 ÷ 2 = 8을 구했는가","18을 구하고 확인했는가"]},"explanation":["3 ÷ 2 → 몫 1, 1 남음 — 남은 1은 10이에요.","10 + 6 = 16, 16 ÷ 2 = 8 — 36 ÷ 2 = 18.","2 × 18 = 36 — 13이 아니라 18이에요."],"asset":{"type":"ldiv","a":36,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L05_challenge#10','math',3,2,'u2','L05','tb_g3_2_math_u2_L05_challenge','lesson_challenge','M3-2-u2-C5',4,'mc','auto','정후가 파란색 구슬 65개와 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이 5개를 만들었어요. 목걸이 한 개에 사용한 구슬은 모두 몇 개인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X03','M3-2-u2-X15']::text[],false,'{"seq":10,"concept":"M3-2-u2-C5","difficulty":4,"kind":"mc","stem":"정후가 파란색 구슬 65개와 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이 5개를 만들었어요. 목걸이 한 개에 사용한 구슬은 모두 몇 개인가요?","options":[{"t":"30개","correct":true},{"t":"150개","mis":"M3-2-u2-X14"},{"t":"22개","mis":"M3-2-u2-X03"},{"t":"26개","mis":"M3-2-u2-X15"}],"explanation":["파란색 65 ÷ 5 = 13, 빨간색 85 ÷ 5 = 17.","13 + 17 = 30 — 한 개에 30개예요.","확인: 65 + 85 = 150, 150 ÷ 5 = 30."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#1','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'mc','auto','종이꽃 한 송이를 만드는 데 한지 4장이 필요해요. 한지는 25장 있어요. 종이꽃을 몇 송이 만들 수 있나요? 한지는 몇 장이 남나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":1,"concept":"M3-2-u2-C6","difficulty":1,"kind":"mc","stem":"종이꽃 한 송이를 만드는 데 한지 4장이 필요해요. 한지는 25장 있어요. 종이꽃을 몇 송이 만들 수 있나요? 한지는 몇 장이 남나요?","options":[{"t":"종이꽃 6송이, 한지 1장이 남아요","correct":true},{"t":"종이꽃 5송이, 한지 5장이 남아요","mis":"M3-2-u2-X05"},{"t":"종이꽃 1송이, 한지 6장이 남아요","mis":"M3-2-u2-X06"},{"t":"종이꽃 6송이, 한지 0장이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 한지 수를 한 송이에 드는 한지 수로 나누어요 — 식은 25 ÷ 4.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 몫 6은 만들 수 있는 종이꽃 수, 나머지 1은 남는 한지 수예요."],"variant_rule":{"alt":[{"stem":"종이꽃 한 송이를 만드는 데 한지 6장이 필요해요. 한지는 45장 있어요. 종이꽃을 몇 송이 만들 수 있나요? 한지는 몇 장이 남나요?","options":[{"t":"종이꽃 7송이, 한지 3장이 남아요","correct":true},{"t":"종이꽃 6송이, 한지 9장이 남아요","mis":"M3-2-u2-X05"},{"t":"종이꽃 3송이, 한지 7장이 남아요","mis":"M3-2-u2-X06"},{"t":"종이꽃 7송이, 한지 0장이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 한지 수를 한 송이에 드는 한지 수로 나누어요 — 식은 45 ÷ 6.","6 × 7 = 42 — 몫 7, 45 − 42 = 3이 남아요.","45 ÷ 6 = 7 … 3 — 몫 7은 만들 수 있는 종이꽃 수, 나머지 3은 남는 한지 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#2','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'sa','auto','25 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"25 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 4의 단에서 25보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 나머지 1은 나누는 수 4보다 작아요."],"variant_rule":{"alt":[{"stem":"16 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 3의 단에서 16보다 크지 않은 가장 큰 곱을 찾아요.","3 × 5 = 15 — 몫 5, 16 − 15 = 1이 남아요.","16 ÷ 3 = 5 … 1 — 나머지 1은 나누는 수 3보다 작아요."]},{"stem":"42 ÷ 5의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나누는 수 5의 단에서 42보다 크지 않은 가장 큰 곱을 찾아요.","5 × 8 = 40 — 몫 8, 42 − 40 = 2가 남아요.","42 ÷ 5 = 8 … 2 — 나머지 2는 나누는 수 5보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#3','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'mc','auto','35 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X07','M3-2-u2-X15']::text[],true,'{"seq":3,"concept":"M3-2-u2-C6","difficulty":1,"kind":"mc","stem":"35 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 … 5","correct":true},{"t":"4 … 11","mis":"M3-2-u2-X05"},{"t":"5","mis":"M3-2-u2-X07"},{"t":"6 … 4","mis":"M3-2-u2-X15"}],"explanation":["나누는 수 6의 단에서 35보다 크지 않은 가장 큰 곱을 찾아요.","6 × 5 = 30 — 몫 5, 35 − 30 = 5가 남아요.","35 ÷ 6 = 5 … 5 — 나머지 5는 나누는 수 6보다 작아요."],"variant_rule":{"alt":[{"stem":"67 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"8 … 3","correct":true},{"t":"7 … 11","mis":"M3-2-u2-X05"},{"t":"3 … 8","mis":"M3-2-u2-X06"},{"t":"8","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 8의 단에서 67보다 크지 않은 가장 큰 곱을 찾아요.","8 × 8 = 64 — 몫 8, 67 − 64 = 3이 남아요.","67 ÷ 8 = 8 … 3 — 나머지 3은 나누는 수 8보다 작아요."]},{"stem":"16 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"5 … 1","correct":true},{"t":"4 … 4","mis":"M3-2-u2-X05"},{"t":"1 … 5","mis":"M3-2-u2-X06"},{"t":"5","mis":"M3-2-u2-X07"}],"explanation":["나누는 수 3의 단에서 16보다 크지 않은 가장 큰 곱을 찾아요.","3 × 5 = 15 — 몫 5, 16 − 15 = 1이 남아요.","16 ÷ 3 = 5 … 1 — 나머지 1은 나누는 수 3보다 작아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#4','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',1,'sa','auto','어떤 수를 3으로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C6","difficulty":1,"kind":"sa","stem":"어떤 수를 3으로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["나머지가 3이 되면 3씩 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 나누는 수 3보다 작아요.","가장 큰 나머지는 2예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 4로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나머지가 4가 되면 4씩 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 나누는 수 4보다 작아요.","가장 큰 나머지는 3이에요."]},{"stem":"어떤 수를 9로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["나머지가 9가 되면 9씩 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 나누는 수 9보다 작아요.","가장 큰 나머지는 8이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#5','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'sa','auto','두 자리 수를 3으로 나누었을 때의 몫과 나머지를 차례로 구했어요. ?에 알맞은 몫을 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"두 자리 수를 3으로 나누었을 때의 몫과 나머지를 차례로 구했어요. ?에 알맞은 몫을 쓰세요.","answer":["4"],"explanation":["나누어지는 수가 1씩 커지면 나머지도 1씩 커지다가 3이 되기 전에 0으로 돌아가요.","14 ÷ 3 = 4 … 2 — 3 × 4 = 12, 14 − 12 = 2.","나머지는 0, 1, 2 — 나누는 수 3보다 언제나 작아요."],"asset":{"type":"expr_grid","rows":[["10 ÷ 3","=","3","…","1"],["11 ÷ 3","=","3","…","2"],["12 ÷ 3","=","4","…","0"],["13 ÷ 3","=","4","…","1"],["14 ÷ 3","=",null,"…","2"],["15 ÷ 3","=","5","…","0"]]},"variant_rule":{"alt":[{"stem":"두 자리 수를 3으로 나누었을 때의 몫과 나머지를 차례로 구했어요. ?에 알맞은 나머지를 쓰세요.","answer":["0"],"explanation":["15는 3씩 5묶음이에요.","15 ÷ 3 = 5 — 남는 것이 없어 나머지는 0이에요.","나머지가 0이면 나누어떨어진다고 해요."],"asset":{"type":"expr_grid","rows":[["10 ÷ 3","=","3","…","1"],["11 ÷ 3","=","3","…","2"],["12 ÷ 3","=","4","…","0"],["13 ÷ 3","=","4","…","1"],["14 ÷ 3","=","4","…","2"],["15 ÷ 3","=","5","…",null]]}},{"stem":"두 자리 수를 3으로 나누었을 때의 몫과 나머지를 차례로 구했어요. ?에 알맞은 나머지를 쓰세요.","answer":["1"],"explanation":["13은 3씩 4묶음이고 1이 남아요.","13 ÷ 3 = 4 … 1 — 3 × 4 = 12, 13 − 12 = 1.","나머지 1은 나누는 수 3보다 작아요."],"asset":{"type":"expr_grid","rows":[["10 ÷ 3","=","3","…","1"],["11 ÷ 3","=","3","…","2"],["12 ÷ 3","=","4","…","0"],["13 ÷ 3","=","4","…",null],["14 ÷ 3","=","4","…","2"],["15 ÷ 3","=","5","…","0"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#6','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"25 ÷ 4","mis":"M3-2-u2-X07"},{"t":"35 ÷ 6","mis":"M3-2-u2-X07"},{"t":"16 ÷ 3","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","24 ÷ 4 = 6이에요 — 나머지가 0이에요.","나머지는 25 ÷ 4 → 1, 35 ÷ 6 → 5, 16 ÷ 3 → 1."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"16 ÷ 2","correct":true},{"t":"17 ÷ 6","mis":"M3-2-u2-X07"},{"t":"32 ÷ 5","mis":"M3-2-u2-X07"},{"t":"44 ÷ 9","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","16 ÷ 2 = 8이에요 — 나머지가 0이에요.","나머지는 17 ÷ 6 → 5, 32 ÷ 5 → 2, 44 ÷ 9 → 8."]},{"stem":"이번에는 다른 수예요. 나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"27 ÷ 3","correct":true},{"t":"32 ÷ 7","mis":"M3-2-u2-X07"},{"t":"37 ÷ 4","mis":"M3-2-u2-X07"},{"t":"33 ÷ 6","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","27 ÷ 3 = 9예요 — 나머지가 0이에요.","나머지는 32 ÷ 7 → 4, 37 ÷ 4 → 1, 33 ÷ 6 → 3."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#7','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'ox','auto','42 ÷ 5는 몫이 8이라 나누어떨어지는 나눗셈이에요.',ARRAY['M3-2-u2-X18']::text[],true,'{"seq":7,"concept":"M3-2-u2-C6","difficulty":2,"kind":"ox","stem":"42 ÷ 5는 몫이 8이라 나누어떨어지는 나눗셈이에요.","answer":"X","reason_options":[{"t":"나머지가 2가 있어서","correct":true},{"t":"몫이 있으면 나누어떨어지는 것이라서","mis":"M3-2-u2-X18"}],"mis":"M3-2-u2-X18","explanation":["나누어떨어진다는 것은 나머지가 0이라는 뜻이에요.","42 ÷ 5 = 8 … 2.","나머지가 2라 나누어떨어지지 않아요."],"variant_rule":{"alt":[{"stem":"25 ÷ 4는 몫이 6이라 나누어떨어지는 나눗셈이에요.","answer":"X","reason_options":[{"t":"나머지가 1이 있어서","correct":true},{"t":"몫이 있으면 나누어떨어지는 것이라서","mis":"M3-2-u2-X18"}],"explanation":["나누어떨어진다는 것은 나머지가 0이라는 뜻이에요.","25 ÷ 4 = 6 … 1.","나머지가 1이라 나누어떨어지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#8','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'ox','auto','종이꽃 한 송이에 한지 4장이 필요해요. 한지 25장으로 종이꽃을 만드는 것을 나눗셈식으로 25 ÷ 4 = 6이라고 썼어요. 바르게 쓴 것이에요.',ARRAY['M3-2-u2-X07']::text[],true,'{"seq":8,"concept":"M3-2-u2-C6","difficulty":2,"kind":"ox","stem":"종이꽃 한 송이에 한지 4장이 필요해요. 한지 25장으로 종이꽃을 만드는 것을 나눗셈식으로 25 ÷ 4 = 6이라고 썼어요. 바르게 쓴 것이에요.","answer":"X","reason_options":[{"t":"남는 한지 1장을 나머지로 써야 해서","correct":true},{"t":"종이꽃 수만 알면 되어서","mis":"M3-2-u2-X07"}],"mis":"M3-2-u2-X07","explanation":["25는 4씩 6묶음이고 1이 남아요.","25 ÷ 4 = 6 … 1 — 1은 나머지예요.","24 ÷ 4 = 6처럼 나머지가 0일 때만 몫만 써요."],"variant_rule":{"alt":[{"stem":"35 ÷ 6 = 5라고 썼어요. 바르게 쓴 것이에요.","answer":"X","reason_options":[{"t":"35 − 30 = 5가 남으니 나머지까지 써야 해서","correct":true},{"t":"몫만 쓰면 되어서","mis":"M3-2-u2-X07"}],"explanation":["6 × 5 = 30, 35 − 30 = 5가 남아요.","35 ÷ 6 = 5 … 5 — 5는 나머지예요.","30 ÷ 6 = 5와 견주면 5만큼 더 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#9','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',2,'match','auto','나눗셈의 나머지가 같은 것끼리 이으세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"match","stem":"나눗셈의 나머지가 같은 것끼리 이으세요.","pairs":[{"l":"17 ÷ 2","r":"26 ÷ 5"},{"l":"31 ÷ 4","r":"24 ÷ 7"},{"l":"44 ÷ 6","r":"18 ÷ 8"}],"mis":"M3-2-u2-X15","explanation":["17 ÷ 2 = 8 … 1, 31 ÷ 4 = 7 … 3, 44 ÷ 6 = 7 … 2.","26 ÷ 5 = 5 … 1, 24 ÷ 7 = 3 … 3, 18 ÷ 8 = 2 … 2.","나머지 1끼리, 3끼리, 2끼리 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_basic#10','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_basic','lesson_basic','M3-2-u2-C6',3,'mc','auto','어떤 두 자리 수를 4로 나누려고 해요. 0, 1, 2, 3, 4, 5 가운데 나머지가 될 수 없는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X18','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"어떤 두 자리 수를 4로 나누려고 해요. 0, 1, 2, 3, 4, 5 가운데 나머지가 될 수 없는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"4, 5","correct":true},{"t":"5","mis":"M3-2-u2-X05"},{"t":"0, 4, 5","mis":"M3-2-u2-X18"},{"t":"1, 2, 3","mis":"M3-2-u2-X17"}],"explanation":["나머지는 나누는 수 4보다 작아야 해요.","나머지가 될 수 있는 수는 0, 1, 2, 3이에요.","4가 남으면 4씩 한 묶음을 더 만들 수 있어요 — 4와 5는 나머지가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#1','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',2,'mc','auto','나눗셈의 나머지에 알맞은 색을 찾아 칠해요. 나머지가 8일 때 보라색으로 칠해요. 보라색으로 칠할 칸은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X05','M3-2-u2-X06']::text[],true,'{"seq":1,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나눗셈의 나머지에 알맞은 색을 찾아 칠해요. 나머지가 8일 때 보라색으로 칠해요. 보라색으로 칠할 칸은 어느 것인가요?","options":[{"t":"44 ÷ 9","correct":true},{"t":"70 ÷ 9","mis":"M3-2-u2-X15"},{"t":"54 ÷ 8","mis":"M3-2-u2-X05"},{"t":"17 ÷ 6","mis":"M3-2-u2-X06"}],"explanation":["44 ÷ 9 = 4 … 8, 70 ÷ 9 = 7 … 7.","54 ÷ 8 = 6 … 6, 17 ÷ 6 = 2 … 5.","나머지가 8인 것은 44 ÷ 9 — 보라색으로 칠해요."],"variant_rule":{"alt":[{"stem":"나눗셈의 나머지에 알맞은 색을 찾아 칠해요. 나머지가 4 또는 5일 때 노란색으로 칠해요. 노란색으로 칠할 칸은 어느 것인가요?","options":[{"t":"32 ÷ 7","correct":true},{"t":"16 ÷ 2","mis":"M3-2-u2-X07"},{"t":"37 ÷ 4","mis":"M3-2-u2-X15"},{"t":"54 ÷ 8","mis":"M3-2-u2-X15"}],"explanation":["32 ÷ 7 = 4 … 4, 16 ÷ 2 = 8.","37 ÷ 4 = 9 … 1, 54 ÷ 8 = 6 … 6.","나머지가 4인 32 ÷ 7을 노란색으로 칠해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#2','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',2,'sa','auto','클립 60개를 8명에게 똑같이 나누어 주려고 해요. 나누어 주고 남는 클립은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"클립 60개를 8명에게 똑같이 나누어 주려고 해요. 나누어 주고 남는 클립은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["똑같이 나누고 남는 것이 나머지예요 — 식은 60 ÷ 8.","8 × 7 = 56 — 몫 7, 60 − 56 = 4가 남아요.","60 ÷ 8 = 7 … 4 — 몫 7은 한 명이 받는 클립 수, 나머지 4는 남는 클립 수예요."],"variant_rule":{"alt":[{"stem":"종이꽃 한 송이를 만드는 데 한지 6장이 필요해요. 한지는 45장 있어요. 한지는 몇 장이 남나요? 숫자로 쓰세요.","answer":["3"],"explanation":["똑같이 나누고 남는 것이 나머지예요 — 식은 45 ÷ 6.","6 × 7 = 42 — 몫 7, 45 − 42 = 3이 남아요.","45 ÷ 6 = 7 … 3 — 몫 7은 만들 수 있는 종이꽃 수, 나머지 3은 남는 한지 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#3','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'sa','auto','다음 나눗셈의 나머지가 2일 때 □ 안에 알맞은 수를 쓰세요. 5□ ÷ 9','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C6","difficulty":3,"kind":"sa","stem":"다음 나눗셈의 나머지가 2일 때 □ 안에 알맞은 수를 쓰세요. 5□ ÷ 9","answer":["6"],"explanation":["9의 단에서 50과 59 사이에 있는 곱은 9 × 6 = 54예요.","나머지가 2가 되려면 54 + 2 = 56이어야 해요.","56 ÷ 9 = 6 … 2 — □는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#4','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'mc','auto','22 ÷ 4, 14 ÷ 5, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":4,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"22 ÷ 4, 14 ÷ 5, 64 ÷ 9 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"14 ÷ 5","correct":true},{"t":"22 ÷ 4","mis":"M3-2-u2-X15"},{"t":"64 ÷ 9","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","22 ÷ 4 = 5 … 2, 14 ÷ 5 = 2 … 4, 64 ÷ 9 = 7 … 1.","나머지가 가장 큰 것은 14 ÷ 5 — 몫이 큰 것과 헷갈리지 않아요."],"variant_rule":{"alt":[{"stem":"17 ÷ 2, 31 ÷ 4, 44 ÷ 6 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"31 ÷ 4","correct":true},{"t":"17 ÷ 2","mis":"M3-2-u2-X17"},{"t":"44 ÷ 6","mis":"M3-2-u2-X15"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","17 ÷ 2 = 8 … 1, 31 ÷ 4 = 7 … 3, 44 ÷ 6 = 7 … 2.","나머지가 가장 큰 것은 31 ÷ 4 — 몫이 큰 것과 헷갈리지 않아요."]},{"stem":"16 ÷ 3, 42 ÷ 5, 35 ÷ 6 가운데 나머지가 가장 큰 것은 어느 것인가요?","options":[{"t":"35 ÷ 6","correct":true},{"t":"16 ÷ 3","mis":"M3-2-u2-X15"},{"t":"42 ÷ 5","mis":"M3-2-u2-X17"},{"t":"모두 같아요","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫과 나머지를 구해요.","16 ÷ 3 = 5 … 1, 42 ÷ 5 = 8 … 2, 35 ÷ 6 = 5 … 5.","나머지가 가장 큰 것은 35 ÷ 6 — 몫이 큰 것과 헷갈리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#5','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'mc','auto','친구와 주사위를 던져 나온 눈의 수가 나머지가 되는 나눗셈을 찾아 색칠해요. 주사위 눈 6이 나왔어요. 나눗셈판의 60 ÷ 9와 52 ÷ 6 가운데 색칠할 수 있는 칸은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":5,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"친구와 주사위를 던져 나온 눈의 수가 나머지가 되는 나눗셈을 찾아 색칠해요. 주사위 눈 6이 나왔어요. 나눗셈판의 60 ÷ 9와 52 ÷ 6 가운데 색칠할 수 있는 칸은 어느 것인가요?","options":[{"t":"60 ÷ 9","correct":true},{"t":"52 ÷ 6","mis":"M3-2-u2-X05"},{"t":"둘 다 칠할 수 있어요","mis":"M3-2-u2-X17"},{"t":"둘 다 칠할 수 없어요","mis":"M3-2-u2-X15"}],"explanation":["60 ÷ 9 = 6 … 6 — 나머지가 6이에요.","52 ÷ 6 = 8 … 4 — 나머지가 4예요.","나머지가 6이 되려면 나누는 수가 6보다 커야 해요 — 60 ÷ 9를 칠해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#6','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'ox','auto','35 ÷ 6 = 4 … 11이에요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":6,"concept":"M3-2-u2-C6","difficulty":3,"kind":"ox","stem":"35 ÷ 6 = 4 … 11이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["6 × 5 = 30 — 몫 5, 35 − 30 = 5가 남아요.","바르게 계산하면 35 ÷ 6 = 5 … 5.","나머지 < 나누는 수 — 확인: 6 × 5 + 5 = 35예요."],"asset":{"type":"ldiv","a":35,"b":6,"upto":0},"variant_rule":{"alt":[{"stem":"25 ÷ 4 = 5 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","바르게 계산하면 25 ÷ 4 = 6 … 1.","나머지 < 나누는 수 — 확인: 4 × 6 + 1 = 25예요."],"asset":{"type":"ldiv","a":25,"b":4,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#7','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',3,'error','auto','67 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":7,"concept":"M3-2-u2-C6","difficulty":3,"kind":"error","stem":"67 ÷ 8을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「67 ÷ 8 = 8 … 4」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"민서 — 「67 ÷ 8 = 8 … 3」","mis":"M3-2-u2-X17"},{"t":"정후 — 「나머지 3은 8보다 작아」","mis":"M3-2-u2-X17"}],"explanation":["8 × 8 = 64 — 몫 8, 67 − 64 = 3이 남아요.","바르게 계산하면 67 ÷ 8 = 8 … 3.","소율이 잘못 말했어요 — 나누는 수 × 몫으로 확인."],"variant_rule":{"alt":[{"stem":"42 ÷ 5를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「42 ÷ 5 = 9 … 1」","correct":true,"mis_target":"M3-2-u2-X15"},{"t":"태민 — 「42 ÷ 5 = 8 … 2」","mis":"M3-2-u2-X17"},{"t":"정후 — 「확인하면 5 × 8 + 2 = 42」","mis":"M3-2-u2-X17"}],"explanation":["5 × 8 = 40 — 몫 8, 42 − 40 = 2가 남아요.","바르게 계산하면 42 ÷ 5 = 8 … 2.","민서가 잘못 말했어요 — 나누는 수 × 몫으로 확인."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#8','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'essay','teacher','종이꽃 한 송이를 만드는 데 한지 4장이 필요하고, 한지는 25장 있어요. 종이꽃 수와 남는 한지 수를 나눗셈식으로 나타내어 몫과 나머지가 무엇인지 쓰고, 24 ÷ 4와 견주어 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"종이꽃 한 송이를 만드는 데 한지 4장이 필요하고, 한지는 25장 있어요. 종이꽃 수와 남는 한지 수를 나눗셈식으로 나타내어 몫과 나머지가 무엇인지 쓰고, 24 ÷ 4와 견주어 설명해 보세요.","answer_guide":{"answer":"예: 25는 4씩 6묶음이고 25 − 24 = 1이 남으므로 25 ÷ 4 = 6 … 1이다. 몫 6은 만들 수 있는 종이꽃 수, 나머지 1은 남는 한지 수이다. 24 ÷ 4 = 6은 나머지가 0이라 나누어떨어지지만 25 ÷ 4는 1이 남아 나누어떨어지지 않는다.","scoring_points":["25 ÷ 4 = 6 … 1로 나타냈는가","몫과 나머지가 무엇을 뜻하는지 썼는가","24 ÷ 4와 견주어 나누어떨어짐을 설명했는가"]},"explanation":["4 × 6 = 24, 25 − 24 = 1.","25 ÷ 4 = 6 … 1 — 6은 몫, 1은 나머지.","24 ÷ 4 = 6 — 나머지 0, 나누어떨어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#9','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'essay','teacher','10 ÷ 3, 11 ÷ 3, 12 ÷ 3, …의 나머지는 1, 2, 0, …으로 되풀이돼요. 나누는 수를 4로 바꾸어 10 ÷ 4부터 15 ÷ 4까지 나머지를 구하고, 나누는 수와 나머지 사이에 어떤 관계가 있는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"10 ÷ 3, 11 ÷ 3, 12 ÷ 3, …의 나머지는 1, 2, 0, …으로 되풀이돼요. 나누는 수를 4로 바꾸어 10 ÷ 4부터 15 ÷ 4까지 나머지를 구하고, 나누는 수와 나머지 사이에 어떤 관계가 있는지 설명해 보세요.","answer_guide":{"answer":"예: 10 ÷ 4 = 2 … 2, 11 ÷ 4 = 2 … 3, 12 ÷ 4 = 3, 13 ÷ 4 = 3 … 1, 14 ÷ 4 = 3 … 2, 15 ÷ 4 = 3 … 3이다. 나머지는 0, 1, 2, 3만 나오고 나누는 수 4보다 작다. 나머지는 언제나 나누는 수보다 작다.","scoring_points":["10 ÷ 4부터 15 ÷ 4까지 나머지를 바르게 구했는가","나머지가 0~3만 나온다고 썼는가","나머지는 나누는 수보다 작다고 설명했는가"]},"explanation":["10 ÷ 4 = 2 … 2, 12 ÷ 4 = 3, 15 ÷ 4 = 3 … 3.","나누는 수가 4이면 나머지는 0, 1, 2, 3 가운데 하나예요.","나머지는 나누는 수보다 언제나 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L06_challenge#10','math',3,2,'u2','L06','tb_g3_2_math_u2_L06_challenge','lesson_challenge','M3-2-u2-C6',4,'mc','auto','사탕 13개를 4명이 똑같이 나누어 가지려고 해요. 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X07']::text[],false,'{"seq":10,"concept":"M3-2-u2-C6","difficulty":4,"kind":"mc","stem":"사탕 13개를 4명이 똑같이 나누어 가지려고 해요. 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"13 ÷ 4 = 3 … 1","correct":true},{"t":"13 ÷ 4 = 2 … 5","mis":"M3-2-u2-X05"},{"t":"13 ÷ 4 = 1 … 9","mis":"M3-2-u2-X05"},{"t":"13 ÷ 4 = 3","mis":"M3-2-u2-X07"}],"explanation":["한 사람이 1개씩 가지면 9개, 2개씩 가지면 5개가 남아 더 나누어 줄 수 있어요.","3개씩 가지면 1개가 남고 더는 똑같이 나누어 줄 수 없어요.","나머지는 나누는 수 4보다 작아야 하니 13 ÷ 4 = 3 … 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#1','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'mc','auto','노인 복지관에서 약과 67개를 한 접시에 5개씩 나누어 담으려고 해요. 접시는 몇 개 필요한가요? 약과는 몇 개 남나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":1,"concept":"M3-2-u2-C7","difficulty":1,"kind":"mc","stem":"노인 복지관에서 약과 67개를 한 접시에 5개씩 나누어 담으려고 해요. 접시는 몇 개 필요한가요? 약과는 몇 개 남나요?","options":[{"t":"접시 13개, 약과 2개가 남아요","correct":true},{"t":"접시 12개, 약과 7개가 남아요","mis":"M3-2-u2-X05"},{"t":"접시 2개, 약과 13개가 남아요","mis":"M3-2-u2-X06"},{"t":"접시 13개, 약과 0개가 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 약과 수를 한 접시에 담는 약과 수로 나누어요 — 식은 67 ÷ 5.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","67 ÷ 5 = 13 … 2 — 몫 13은 필요한 접시 수, 나머지 2는 남는 약과 수예요."],"variant_rule":{"alt":[{"stem":"노인 복지관에서 약과 75개를 한 접시에 2개씩 나누어 담으려고 해요. 접시는 몇 개 필요한가요? 약과는 몇 개 남나요?","options":[{"t":"접시 37개, 약과 1개가 남아요","correct":true},{"t":"접시 36개, 약과 3개가 남아요","mis":"M3-2-u2-X05"},{"t":"접시 1개, 약과 37개가 남아요","mis":"M3-2-u2-X06"},{"t":"접시 37개, 약과 0개가 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 약과 수를 한 접시에 담는 약과 수로 나누어요 — 식은 75 ÷ 2.","십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 15 ÷ 2 → 몫 7.","75 ÷ 2 = 37 … 1 — 몫 37은 필요한 접시 수, 나머지 1은 남는 약과 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#2','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','73 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"73 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","73 ÷ 3 = 24 … 1 — 확인: 3 × 24 + 1 = 73이에요."],"variant_rule":{"alt":[{"stem":"82 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 7 → 몫 1.","82 ÷ 7 = 11 … 5 — 확인: 7 × 11 + 5 = 82예요."]},{"stem":"89 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 6 → 몫 4.","89 ÷ 6 = 14 … 5 — 확인: 6 × 14 + 5 = 89예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#3','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','82 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"82 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 7 → 몫 1.","82 ÷ 7 = 11 … 5 — 확인: 7 × 11 + 5 = 82예요."],"variant_rule":{"alt":[{"stem":"89 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 6 → 몫 4.","89 ÷ 6 = 14 … 5 — 확인: 6 × 14 + 5 = 89예요."]},{"stem":"91 ÷ 9의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 1은 9로 나눌 수 없어 몫 0.","91 ÷ 9 = 10 … 1 — 확인: 9 × 10 + 1 = 91이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#4','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',1,'sa','auto','44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["나누는 수 × 몫 = 3 × 14 = 42예요.","여기에 나머지 2를 더하면 44예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 14","=",null],["□ + 2","=","44"]]},"variant_rule":{"alt":[{"stem":"99 ÷ 8 = 12 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["96"],"explanation":["나누는 수 × 몫 = 8 × 12 = 96이에요.","여기에 나머지 3을 더하면 99예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["8 × 12","=",null],["□ + 3","=","99"]]}},{"stem":"53 ÷ 4 = 13 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["52"],"explanation":["나누는 수 × 몫 = 4 × 13 = 52예요.","여기에 나머지 1을 더하면 53이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["4 × 13","=",null],["□ + 1","=","53"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#5','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'mc','auto','99 ÷ 8 = 12 … 3을 바르게 계산했는지 확인하는 식은 어느 것인가요?',ARRAY['M3-2-u2-X08','M3-2-u2-X09','M3-2-u2-X14']::text[],true,'{"seq":5,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"99 ÷ 8 = 12 … 3을 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"8 × 12 + 3 = 99","correct":true},{"t":"3 × 12 + 8 = 44","mis":"M3-2-u2-X08"},{"t":"8 × 12 = 96","mis":"M3-2-u2-X09"},{"t":"8 + 12 + 3 = 23","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수와 몫의 곱에 나머지를 더해요.","8 × 12 = 96, 96 + 3 = 99예요.","나누어지는 수 99와 같으니 바르게 계산했어요."],"variant_rule":{"alt":[{"stem":"44 ÷ 3 = 14 … 2를 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"3 × 14 + 2 = 44","correct":true},{"t":"2 × 14 + 3 = 31","mis":"M3-2-u2-X08"},{"t":"3 × 14 = 42","mis":"M3-2-u2-X09"},{"t":"3 + 14 + 2 = 19","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수와 몫의 곱에 나머지를 더해요.","3 × 14 = 42, 42 + 2 = 44예요.","나누어지는 수 44와 같으니 바르게 계산했어요."]},{"stem":"53 ÷ 4 = 13 … 1을 바르게 계산했는지 확인하는 식은 어느 것인가요?","options":[{"t":"4 × 13 + 1 = 53","correct":true},{"t":"1 × 13 + 4 = 17","mis":"M3-2-u2-X08"},{"t":"4 × 13 = 52","mis":"M3-2-u2-X09"},{"t":"4 + 13 + 1 = 18","mis":"M3-2-u2-X14"}],"explanation":["확인은 나누는 수와 몫의 곱에 나머지를 더해요.","4 × 13 = 52, 52 + 1 = 53이에요.","나누어지는 수 53과 같으니 바르게 계산했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#6','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'sa','auto','67 ÷ 5의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"67 ÷ 5의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["3"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3.","67 ÷ 5 = 13 … 2 — 몫의 일의 자리 숫자는 3이에요."],"asset":{"type":"ldiv","a":67,"b":5,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"89 ÷ 6의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 6 → 몫 4.","89 ÷ 6 = 14 … 5 — 몫의 일의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":89,"b":6,"hide":[["q",1]]}},{"stem":"91 ÷ 9의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 1은 9로 나눌 수 없어 몫 0.","91 ÷ 9 = 10 … 1 — 몫의 일의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":91,"b":9,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#7','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'ox','auto','73 ÷ 3 = 23 … 4예요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":2,"kind":"ox","stem":"73 ÷ 3 = 23 … 4예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","바르게 계산하면 73 ÷ 3 = 24 … 1.","나머지 < 나누는 수 — 확인: 3 × 24 + 1 = 73이에요."],"asset":{"type":"ldiv","a":73,"b":3,"upto":0},"variant_rule":{"alt":[{"stem":"75 ÷ 2 = 36 … 3이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 15 ÷ 2 → 몫 7.","바르게 계산하면 75 ÷ 2 = 37 … 1.","나머지 < 나누는 수 — 확인: 2 × 37 + 1 = 75예요."],"asset":{"type":"ldiv","a":75,"b":2,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#8','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'mc','auto','91 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X01','M3-2-u2-X05','M3-2-u2-X07']::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"91 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"10 … 1","correct":true},{"t":"1 … 1","mis":"M3-2-u2-X01"},{"t":"9 … 10","mis":"M3-2-u2-X05"},{"t":"10","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 1은 9로 나눌 수 없어 몫 0.","91 ÷ 9 = 10 … 1 — 확인: 9 × 10 + 1 = 91이에요."],"asset":{"type":"ldiv","a":91,"b":9,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#9','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',2,'sa','auto','채원이의 말을 읽고 계산 결과가 맞는지 알아봐요. 3장씩 묶은 1 카드의 수를 곱셈식으로 나타내면 3 × 14 = □예요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"채원이의 말을 읽고 계산 결과가 맞는지 알아봐요. 3장씩 묶은 1 카드의 수를 곱셈식으로 나타내면 3 × 14 = □예요. □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["3장씩 14묶음 — 3 × 14 = 42장이에요.","남은 2장을 더하면 42 + 2 = 44 — 처음 1 카드 수와 같아요.","나누는 수와 몫의 곱에 나머지를 더하면 나누어지는 수가 돼요."],"asset":{"type":"speech","turns":[{"who":"채원","text":"1 카드 44장을 3장씩 묶으면 14묶음이 되고 2장이 남으니까 44 ÷ 3 = 14 … 2가 맞겠지?"}]},"variant_rule":{"alt":[{"stem":"채원이의 말을 읽고 계산 결과가 맞는지 알아봐요. 1 카드는 모두 몇 장인지 덧셈식으로 나타내면 42 + 2 = □예요. □에 알맞은 수를 쓰세요.","answer":["44"],"explanation":["3장씩 14묶음은 3 × 14 = 42장이에요.","42 + 2 = 44 — 나누어지는 수 44와 같아요.","그래서 44 ÷ 3 = 14 … 2는 바르게 계산한 거예요."],"asset":{"type":"speech","turns":[{"who":"채원","text":"1 카드 44장을 3장씩 묶으면 14묶음이 되고 2장이 남으니까 44 ÷ 3 = 14 … 2가 맞겠지?"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_basic#10','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_basic','lesson_basic','M3-2-u2-C7',3,'error','auto','99 ÷ 8 = 12 … 3을 계산한 뒤 친구들이 맞는지 확인했어요. 잘못 확인한 친구는 누구인가요?',ARRAY['M3-2-u2-X08','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":3,"kind":"error","stem":"99 ÷ 8 = 12 … 3을 계산한 뒤 친구들이 맞는지 확인했어요. 잘못 확인한 친구는 누구인가요?","options":[{"t":"민준 — 「3 × 12 = 36, 36 + 8 = 44 — 틀렸어」","correct":true,"mis_target":"M3-2-u2-X08"},{"t":"지아 — 「8 × 12 = 96, 96 + 3 = 99 — 맞아」","mis":"M3-2-u2-X17"},{"t":"소율 — 「나머지 3은 8보다 작고, 8 × 12 + 3 = 99라 맞아」","mis":"M3-2-u2-X17"}],"explanation":["확인은 나누는 수와 몫의 곱에 나머지를 더해요.","8 × 12 = 96, 96 + 3 = 99 — 나누어지는 수와 같아요.","민준이는 나누는 수 8과 나머지 3을 바꾸어 썼어요."],"asset":{"type":"ldiv","a":99,"b":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#1','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',2,'sa','auto','어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","7 × 13 = 91, 91 + 4 = 95예요.","확인: 95 ÷ 7 = 13 … 4."],"variant_rule":{"alt":[{"stem":"어떤 수를 7로 나누었더니 몫이 4이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","7 × 4 = 28, 28 + 6 = 34예요.","확인: 34 ÷ 7 = 4 … 6."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#2','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',2,'mc','auto','색종이 92장을 한 명에게 8장씩 나누어 주려고 해요. 색종이를 몇 명에게 나누어 줄 수 있나요? 남는 색종이는 몇 장인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":2,"concept":"M3-2-u2-C7","difficulty":2,"kind":"mc","stem":"색종이 92장을 한 명에게 8장씩 나누어 주려고 해요. 색종이를 몇 명에게 나누어 줄 수 있나요? 남는 색종이는 몇 장인가요?","options":[{"t":"11명에게 나누어 주고, 4장이 남아요","correct":true},{"t":"10명에게 나누어 주고, 12장이 남아요","mis":"M3-2-u2-X05"},{"t":"4명에게 나누어 주고, 11장이 남아요","mis":"M3-2-u2-X06"},{"t":"11명에게 나누어 주고, 0장이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 색종이 수를 한 명에게 주는 색종이 수로 나누어요 — 식은 92 ÷ 8.","십의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 8 → 몫 1.","92 ÷ 8 = 11 … 4 — 몫 11은 색종이를 받는 사람 수, 나머지 4는 남는 색종이 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#3','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'sa','auto','매실 76개를 6명에게 똑같이 나누어 주려고 해요. 매실을 몇 개 더 가져와서 남는 매실 없이 6명에게 똑같이 나누어 주려면, 적어도 몇 개를 더 가져와야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"매실 76개를 6명에게 똑같이 나누어 주려고 해요. 매실을 몇 개 더 가져와서 남는 매실 없이 6명에게 똑같이 나누어 주려면, 적어도 몇 개를 더 가져와야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["76 ÷ 6 = 12 … 4 — 한 명에게 12개씩 주고 4개가 남아요.","남은 4개에 2개를 더하면 6개 — 6명에게 1개씩 더 줄 수 있어요.","6 − 4 = 2 — 적어도 2개를 더 가져와야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#4','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'error','auto','89 ÷ 6을 세로셈으로 계산한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X17']::text[],false,'{"seq":4,"concept":"M3-2-u2-C7","difficulty":3,"kind":"error","stem":"89 ÷ 6을 세로셈으로 계산한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민서 — 「몫은 41, 나머지는 5야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"태민 — 「8을 6으로 나누고 남은 2를 내려 29를 6으로 나누어」","mis":"M3-2-u2-X17"},{"t":"정후 — 「몫은 14, 나머지는 5야」","mis":"M3-2-u2-X17"}],"explanation":["8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 29 ÷ 6 → 몫 4, 5 남음.","89 ÷ 6 = 14 … 5 — 확인: 6 × 14 + 5 = 89예요.","민서는 몫을 거꾸로 썼어요 — 몫은 자리에 맞추어 앞에서부터 써요."],"asset":{"type":"ldiv","a":89,"b":6,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#5','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'error','auto','나눗셈의 계산 결과가 맞는지 확인해 보고, 잘못 계산한 것을 찾으세요.',ARRAY['M3-2-u2-X05','M3-2-u2-X17']::text[],false,'{"seq":5,"concept":"M3-2-u2-C7","difficulty":3,"kind":"error","stem":"나눗셈의 계산 결과가 맞는지 확인해 보고, 잘못 계산한 것을 찾으세요.","options":[{"t":"53 ÷ 4 = 12 … 5","correct":true,"mis_target":"M3-2-u2-X05"},{"t":"73 ÷ 3 = 24 … 1","mis":"M3-2-u2-X17"},{"t":"82 ÷ 7 = 11 … 5","mis":"M3-2-u2-X17"},{"t":"89 ÷ 6 = 14 … 5","mis":"M3-2-u2-X17"}],"explanation":["3 × 24 + 1 = 73, 7 × 11 + 5 = 82, 6 × 14 + 5 = 89 — 모두 맞아요.","4 × 12 + 5 = 53이 되지만 나머지 5가 나누는 수 4보다 커요.","바르게 하면 53 ÷ 4 = 13 … 1 — 4 × 13 + 1 = 53이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#6','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'sa','auto','태민이 82 ÷ 7을 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"태민이 82 ÷ 7을 계산하고 몫을 10이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["태민 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 12 ÷ 7 → 몫 1.","바른 몫은 11 — 확인: 7 × 11 + 5 = 82예요."],"variant_rule":{"alt":[{"stem":"정후가 73 ÷ 3을 계산하고 몫을 21이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["정후 — 윗자리에서 남은 수를 아래 자리로 내리지 않고 버린다.","십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","바른 몫은 24 — 확인: 3 × 24 + 1 = 73이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#7','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',3,'mc','auto','어떤 나눗셈을 확인했더니 4 × 13 = 52, 52 + 1 = 53이었어요. 이 확인에 알맞은 나눗셈식은 어느 것인가요?',ARRAY['M3-2-u2-X09','M3-2-u2-X06','M3-2-u2-X20']::text[],false,'{"seq":7,"concept":"M3-2-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 나눗셈을 확인했더니 4 × 13 = 52, 52 + 1 = 53이었어요. 이 확인에 알맞은 나눗셈식은 어느 것인가요?","options":[{"t":"53 ÷ 4 = 13 … 1","correct":true},{"t":"52 ÷ 4 = 13 … 1","mis":"M3-2-u2-X09"},{"t":"53 ÷ 4 = 1 … 13","mis":"M3-2-u2-X06"},{"t":"13 ÷ 4 = 53 … 1","mis":"M3-2-u2-X20"}],"explanation":["확인식에서 곱하는 4가 나누는 수, 13이 몫, 더하는 1이 나머지예요.","마지막에 나온 53이 나누어지는 수예요.","그래서 53 ÷ 4 = 13 … 1 — 나머지 1은 4보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#8','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'essay','teacher','노인 복지관에서 약과 67개를 한 접시에 5개씩 나누어 담아요. 67 ÷ 5를 계산하고, 몫과 나머지가 무엇을 뜻하는지와 계산이 맞는지 확인하는 방법까지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"노인 복지관에서 약과 67개를 한 접시에 5개씩 나누어 담아요. 67 ÷ 5를 계산하고, 몫과 나머지가 무엇을 뜻하는지와 계산이 맞는지 확인하는 방법까지 써 보세요.","answer_guide":{"answer":"예: 67에서 50은 5씩 10묶음이고, 남은 17은 5씩 3묶음과 2가 남는다. 67 ÷ 5 = 13 … 2이다. 몫 13은 필요한 접시 수, 나머지 2는 남는 약과 수이다. 확인: 5 × 13 = 65, 65 + 2 = 67이다.","scoring_points":["67 ÷ 5 = 13 … 2를 구했는가","몫과 나머지의 뜻을 썼는가","5 × 13 + 2 = 67로 확인했는가"]},"explanation":["6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 17 ÷ 5 → 몫 3, 2 남음.","67 ÷ 5 = 13 … 2 — 접시 13개, 약과 2개 남음.","5 × 13 + 2 = 67."],"asset":{"type":"ldiv","a":67,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#9','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'essay','teacher','친구가 99 ÷ 8 = 12 … 3을 「3 × 12 = 36, 36 + 8 = 44」로 확인하고 틀렸다고 했어요. 친구의 확인에서 잘못된 점을 찾고 바르게 확인해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"친구가 99 ÷ 8 = 12 … 3을 「3 × 12 = 36, 36 + 8 = 44」로 확인하고 틀렸다고 했어요. 친구의 확인에서 잘못된 점을 찾고 바르게 확인해 보세요.","answer_guide":{"answer":"예: 나누는 수 8 대신 나머지 3을 몫에 곱하고 나누는 수 8을 더했다. 바르게 확인하면 나누는 수와 몫의 곱에 나머지를 더해 8 × 12 = 96, 96 + 3 = 99이고, 나누어지는 수 99와 같으므로 계산은 맞다.","scoring_points":["나누는 수와 나머지를 바꾸었다고 찾았는가","8 × 12 + 3으로 확인했는가","99가 되어 맞다고 판단했는가"]},"explanation":["확인 = 나누는 수 × 몫 + 나머지.","8 × 12 = 96, 96 + 3 = 99.","99 ÷ 8 = 12 … 3은 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["8 × 12","=","96"],["96 + 3","=","99"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L07_challenge#10','math',3,2,'u2','L07','tb_g3_2_math_u2_L07_challenge','lesson_challenge','M3-2-u2-C7',4,'essay','teacher','친구가 약과 75개를 한 접시에 2개씩 담는 것을 75 ÷ 2 = 36 … 3이라고 계산하고, 2 × 36 + 3 = 75라서 맞다고 했어요. 친구의 계산이 맞는지 판단하고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"친구가 약과 75개를 한 접시에 2개씩 담는 것을 75 ÷ 2 = 36 … 3이라고 계산하고, 2 × 36 + 3 = 75라서 맞다고 했어요. 친구의 계산이 맞는지 판단하고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 2 × 36 + 3 = 75로 확인식은 맞지만 나머지 3이 나누는 수 2보다 커서 한 접시를 더 채울 수 있다. 나머지는 나누는 수보다 작아야 하므로 75 ÷ 2 = 37 … 1이다. 확인하면 2 × 37 + 1 = 75이다.","scoring_points":["맞지 않다고 판단했는가","나머지가 나누는 수보다 작아야 한다고 썼는가","37 … 1을 구하고 확인했는가"]},"explanation":["확인식이 맞아도 나머지가 나누는 수보다 작은지 함께 봐요.","나머지 3은 2보다 커서 2개를 한 접시에 더 담을 수 있어요.","75 ÷ 2 = 37 … 1 — 2 × 37 + 1 = 75."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#1','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','8 ÷ 4 = 2예요. 그러면 800 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"8 ÷ 4 = 2예요. 그러면 800 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["200"],"explanation":["800은 8의 100배예요.","나누어지는 수가 100배 커지면 몫도 100배 커져요.","2의 100배 — 800 ÷ 4 = 200이에요."],"variant_rule":{"alt":[{"stem":"84 ÷ 2 = 42예요. 그러면 840 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["420"],"explanation":["840은 84의 10배예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","42의 10배 — 840 ÷ 2 = 420이에요."]},{"stem":"93 ÷ 3 = 31이에요. 그러면 930 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["310"],"explanation":["930은 93의 10배예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","31의 10배 — 930 ÷ 3 = 310이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#2','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'mc','auto','공공 도서관에서 책 800권을 책장 4개에 똑같이 나누어 꽂으려고 해요. 책장 한 개에 꽂을 수 있는 책은 몇 권인가요?',ARRAY['M3-2-u2-X14','M3-2-u2-X01']::text[],true,'{"seq":2,"concept":"M3-2-u2-C8","difficulty":1,"kind":"mc","stem":"공공 도서관에서 책 800권을 책장 4개에 똑같이 나누어 꽂으려고 해요. 책장 한 개에 꽂을 수 있는 책은 몇 권인가요?","options":[{"t":"200권","correct":true},{"t":"796권","mis":"M3-2-u2-X14"},{"t":"3200권","mis":"M3-2-u2-X14"},{"t":"20권","mis":"M3-2-u2-X01"}],"explanation":["전체 책 수를 책장 수로 나누어요 — 식은 800 ÷ 4.","나누어지는 수가 100배 커지면 몫도 100배 커져요.","800 ÷ 4 = 200 — 몫 200은 책장 한 개에 꽂는 책 수예요."],"variant_rule":{"alt":[{"stem":"공공 도서관에서 책 808권을 책장 8개에 똑같이 나누어 정리하려고 해요. 책장 한 개에 꽂을 수 있는 책은 몇 권인가요?","options":[{"t":"101권","correct":true},{"t":"800권","mis":"M3-2-u2-X14"},{"t":"6464권","mis":"M3-2-u2-X14"},{"t":"11권","mis":"M3-2-u2-X10"}],"explanation":["전체 책 수를 책장 수로 나누어요 — 식은 808 ÷ 8.","백의 자리 8 ÷ 8 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 8 ÷ 8 → 몫 1.","808 ÷ 8 = 101 — 몫 101은 책장 한 개에 꽂는 책 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#3','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',1,'sa','auto','307 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C8","difficulty":1,"kind":"sa","stem":"307 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","307 ÷ 3 = 102 … 1 — 확인: 3 × 102 + 1 = 307이에요."],"variant_rule":{"alt":[{"stem":"607 ÷ 6의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 6 → 몫 1.","607 ÷ 6 = 101 … 1 — 확인: 6 × 101 + 1 = 607이에요."]},{"stem":"409 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["102"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2.","409 ÷ 4 = 102 … 1 — 확인: 4 × 102 + 1 = 409예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
