INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#7','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'sa','auto','638 ÷ 3 = 212 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"638 ÷ 3 = 212 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["636"],"explanation":["나누는 수 × 몫 = 3 × 212 = 636이에요.","여기에 나머지 2를 더하면 638이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 212","=",null],["□ + 2","=","638"]]},"variant_rule":{"alt":[{"stem":"607 ÷ 6 = 101 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["606"],"explanation":["나누는 수 × 몫 = 6 × 101 = 606이에요.","여기에 나머지 1을 더하면 607이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["6 × 101","=",null],["□ + 1","=","607"]]}},{"stem":"307 ÷ 3 = 102 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["306"],"explanation":["나누는 수 × 몫 = 3 × 102 = 306이에요.","여기에 나머지 1을 더하면 307이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 102","=",null],["□ + 1","=","307"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#8','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'sa','auto','638 ÷ 3의 세로셈이에요. 몫의 백의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"638 ÷ 3의 세로셈이에요. 몫의 백의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 8 ÷ 3 → 몫 2.","638 ÷ 3 = 212 … 2 — 몫의 백의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":638,"b":3,"hide":[["q",0]]},"variant_rule":{"alt":[{"stem":"669 ÷ 6의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 6 ÷ 6 → 몫 1 · 일의 자리 9 ÷ 6 → 몫 1.","669 ÷ 6 = 111 … 3 — 몫의 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":669,"b":6,"hide":[["q",1]]}},{"stem":"367 ÷ 3의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 7 ÷ 3 → 몫 2.","367 ÷ 3 = 122 … 1 — 몫의 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":367,"b":3,"hide":[["q",1]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#9','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',2,'mc','auto','어느 빵집에서 빵 367개를 한 봉지에 3개씩 담아 포장하려고 해요. 빵은 몇 봉지가 되나요? 남는 빵은 몇 개인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":9,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"어느 빵집에서 빵 367개를 한 봉지에 3개씩 담아 포장하려고 해요. 빵은 몇 봉지가 되나요? 남는 빵은 몇 개인가요?","options":[{"t":"122봉지가 되고, 빵 1개가 남아요","correct":true},{"t":"121봉지가 되고, 빵 4개가 남아요","mis":"M3-2-u2-X05"},{"t":"1봉지가 되고, 빵 122개가 남아요","mis":"M3-2-u2-X06"},{"t":"122봉지가 되고, 빵 0개가 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 빵 수를 한 봉지에 담는 빵 수로 나누어요 — 식은 367 ÷ 3.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 7 ÷ 3 → 몫 2.","367 ÷ 3 = 122 … 1 — 몫 122는 빵 봉지 수, 나머지 1은 남는 빵 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_basic#10','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_basic','lesson_basic','M3-2-u2-C8',3,'error','auto','색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 친구들의 풀이를 보고 잘못 계산한 친구를 찾으세요.',ARRAY['M3-2-u2-X11','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C8","difficulty":3,"kind":"error","stem":"색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 친구들의 풀이를 보고 잘못 계산한 친구를 찾으세요.","options":[{"t":"태민 — 「한 명이 120장씩 가지고, 1장이 남아요」","correct":true,"mis_target":"M3-2-u2-X11"},{"t":"정후 — 「한 명이 102장씩 가지고, 1장이 남아요」","mis":"M3-2-u2-X17"},{"t":"채원 — 「확인하면 4 × 102 + 1 = 409예요」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2, 1 남음.","409 ÷ 4 = 102 … 1 — 확인: 4 × 102 + 1 = 409예요.","태민이는 몫의 0을 끝에 붙였어요 — 십의 자리에서 나눌 수 없으면 몫의 십의 자리에 0을 써요."],"asset":{"type":"ldiv","a":409,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#1','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',2,'mc','auto','669 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":1,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"669 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"111 … 3","correct":true},{"t":"110 … 9","mis":"M3-2-u2-X05"},{"t":"3 … 111","mis":"M3-2-u2-X06"},{"t":"111","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 6 ÷ 6 → 몫 1 · 일의 자리 9 ÷ 6 → 몫 1.","669 ÷ 6 = 111 … 3 — 확인: 6 × 111 + 3 = 669예요."],"variant_rule":{"alt":[{"stem":"995 ÷ 9의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"110 … 5","correct":true},{"t":"109 … 14","mis":"M3-2-u2-X05"},{"t":"5 … 110","mis":"M3-2-u2-X06"},{"t":"110","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 9 → 몫 1 · 십의 자리 9 ÷ 9 → 몫 1 · 일의 자리 5는 9로 나눌 수 없어 몫 0.","995 ÷ 9 = 110 … 5 — 확인: 9 × 110 + 5 = 995예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#2','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',2,'sa','auto','민준이는 문구점에서 가격이 같은 연필 2자루를 840원에 샀어요. 연필 한 자루는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C8","difficulty":2,"kind":"sa","stem":"민준이는 문구점에서 가격이 같은 연필 2자루를 840원에 샀어요. 연필 한 자루는 얼마인가요? 숫자로 쓰세요.","answer":["420"],"explanation":["전체 값을 연필 수로 나누어요 — 식은 840 ÷ 2.","백의 자리 8 ÷ 2 → 몫 4 · 십의 자리 4 ÷ 2 → 몫 2 · 일의 자리 0 → 몫 0.","840 ÷ 2 = 420 — 연필 한 자루는 420원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#3','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'mc','auto','605를 2로 나눈 몫과 나머지, 605를 3으로 나눈 몫과 나머지를 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X10','M3-2-u2-X11','M3-2-u2-X15']::text[],false,'{"seq":3,"concept":"M3-2-u2-C8","difficulty":3,"kind":"mc","stem":"605를 2로 나눈 몫과 나머지, 605를 3으로 나눈 몫과 나머지를 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"302 … 1, 201 … 2","correct":true},{"t":"32 … 1, 21 … 2","mis":"M3-2-u2-X10"},{"t":"320 … 1, 210 … 2","mis":"M3-2-u2-X11"},{"t":"302 … 1, 201 … 1","mis":"M3-2-u2-X15"}],"explanation":["605 ÷ 2 — 6 ÷ 2 = 3, 십의 자리 0 → 몫 0, 5 ÷ 2 = 2 … 1.","605 ÷ 3 — 6 ÷ 3 = 2, 십의 자리 0 → 몫 0, 5 ÷ 3 = 1 … 2.","605 ÷ 2 = 302 … 1, 605 ÷ 3 = 201 … 2."],"asset":{"type":"ldiv","a":605,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#4','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'sa','auto','딸기 5개로 딸기주스 한 컵을 만들 수 있어요. 딸기는 505개 있어요. 만들 수 있는 딸기주스는 몇 컵인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":3,"kind":"sa","stem":"딸기 5개로 딸기주스 한 컵을 만들 수 있어요. 딸기는 505개 있어요. 만들 수 있는 딸기주스는 몇 컵인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["전체 딸기 수를 한 컵에 드는 딸기 수로 나누어요 — 식은 505 ÷ 5.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 5 ÷ 5 → 몫 1.","505 ÷ 5 = 101 — 몫 101은 만들 수 있는 딸기주스 컵 수예요."],"variant_rule":{"alt":[{"stem":"귤 930개를 상자 3개에 똑같이 나누어 담으려고 해요. 상자 한 개에 담는 귤은 몇 개인가요? 숫자로 쓰세요.","answer":["310"],"explanation":["전체 귤 수를 상자 수로 나누어요 — 식은 930 ÷ 3.","백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 0 → 몫 0.","930 ÷ 3 = 310 — 몫 310은 상자 한 개에 담는 귤 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#5','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'error','auto','721 ÷ 7을 세로셈으로 계산했어요. 친구들의 말 가운데 잘못된 것은 어느 것인가요?',ARRAY['M3-2-u2-X10','M3-2-u2-X17']::text[],false,'{"seq":5,"concept":"M3-2-u2-C8","difficulty":3,"kind":"error","stem":"721 ÷ 7을 세로셈으로 계산했어요. 친구들의 말 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"소율 — 「7을 7로, 21을 7로 나누니까 몫은 13이야」","correct":true,"mis_target":"M3-2-u2-X10"},{"t":"민서 — 「십의 자리 2는 7로 나눌 수 없으니 몫의 십의 자리에 0을 써」","mis":"M3-2-u2-X17"},{"t":"태민 — 「721 ÷ 7 = 103이야」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 7 ÷ 7 → 몫 1 · 십의 자리 2는 7로 나눌 수 없어 몫 0 · 21 ÷ 7 → 몫 3.","721 ÷ 7 = 103 — 확인: 7 × 103 = 721이에요.","소율이는 0을 써야 하는 자리를 무시했어요 — 나눌 수 없으면 몫에 0."],"asset":{"type":"ldiv","a":721,"b":7,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#6','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'ox','auto','418 ÷ 4 = 142예요.',ARRAY['M3-2-u2-X19']::text[],false,'{"seq":6,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"418 ÷ 4 = 142예요.","answer":"X","reason_options":[{"t":"십의 자리 1은 4로 나눌 수 없어 몫에 0을 쓰고 18을 함께 나누어야 해서","correct":true},{"t":"1이 4보다 작으면 4 ÷ 1을 하면 되어서","mis":"M3-2-u2-X19"}],"mis":"M3-2-u2-X19","explanation":["백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 1은 4로 나눌 수 없어 몫 0 · 18 ÷ 4 → 몫 4, 2 남음.","418 ÷ 4 = 104 … 2 — 확인: 4 × 104 + 2 = 418이에요.","나누어지는 수의 자리 숫자를 나누는 수로 나누어요 — 거꾸로 나누지 않아요."],"asset":{"type":"ldiv","a":418,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#7','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',3,'sa','auto','어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C8","difficulty":3,"kind":"sa","stem":"어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["638"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","3 × 212 = 636, 636 + 2 = 638이에요.","확인: 638 ÷ 3 = 212 … 2."],"variant_rule":{"alt":[{"stem":"어떤 수를 6으로 나누었더니 몫이 101이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["607"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","6 × 101 = 606, 606 + 1 = 607이에요.","확인: 607 ÷ 6 = 101 … 1."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#8','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'essay','teacher','공공 도서관 봉사 활동 중이에요. 307 ÷ 3을 계산하는 방법을 쓰고, 몫의 0을 빠뜨리면 어떻게 되는지 확인하는 방법으로 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"공공 도서관 봉사 활동 중이에요. 307 ÷ 3을 계산하는 방법을 쓰고, 몫의 0을 빠뜨리면 어떻게 되는지 확인하는 방법으로 설명해 보세요.","answer_guide":{"answer":"예: 307의 백의 자리 수 3을 3으로 나누어 몫의 백의 자리에 1을 쓰고, 십의 자리 0은 3으로 나눌 수 없어 몫의 십의 자리에 0을 쓴다. 일의 자리 7을 3으로 나누어 몫의 일의 자리에 2를 쓰면 1이 남는다. 307 ÷ 3 = 102 … 1이다. 0을 빠뜨려 몫을 12라고 하면 3 × 12 + 1 = 37이 되어 307과 다르다.","scoring_points":["몫의 십의 자리에 0을 썼는가","307 ÷ 3 = 102 … 1을 구했는가","0을 빠뜨리면 확인한 값이 달라진다고 설명했는가"]},"explanation":["3 ÷ 3 = 1 · 십의 자리 0 → 몫 0 · 7 ÷ 3 = 2 … 1.","307 ÷ 3 = 102 … 1 — 3 × 102 + 1 = 307.","몫을 12로 쓰면 3 × 12 + 1 = 37 — 307이 아니에요."],"asset":{"type":"ldiv","a":307,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#9','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'essay','teacher','367 ÷ 3에 알맞은 생활 속 문제를 만들고 해결해 보세요. 또, 친구가 같은 문제의 답을 「121봉지, 4개」라고 한 것이 맞는지 판단해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"367 ÷ 3에 알맞은 생활 속 문제를 만들고 해결해 보세요. 또, 친구가 같은 문제의 답을 「121봉지, 4개」라고 한 것이 맞는지 판단해 보세요.","answer_guide":{"answer":"예: 어느 빵집에서 빵 367개를 한 봉지에 3개씩 담아 포장하려고 한다. 빵은 몇 봉지가 되고, 남는 빵은 몇 개인가? → 367 ÷ 3 = 122 … 1이므로 122봉지가 되고 1개가 남는다. 「121봉지, 4개」는 나머지 4가 나누는 수 3보다 커서 한 봉지를 더 만들 수 있으므로 틀렸다.","scoring_points":["367 ÷ 3에 맞는 상황을 만들었는가","122 … 1을 구해 몫과 나머지의 뜻대로 답했는가","121 … 4가 나머지 때문에 틀렸다고 판단했는가"]},"explanation":["367은 나누어지는 수, 3은 나누는 수가 되게 상황을 만들어요.","367 ÷ 3 = 122 … 1 — 122봉지, 1개 남음.","나머지 4는 3보다 커서 121 … 4는 틀린 답이에요."],"asset":{"type":"ldiv","a":367,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L08_challenge#10','math',3,2,'u2','L08','tb_g3_2_math_u2_L08_challenge','lesson_challenge','M3-2-u2-C8',4,'essay','teacher','색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 친구가 「한 명이 120장씩 가지고, 1장이 남는다」고 풀었어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 친구가 「한 명이 120장씩 가지고, 1장이 남는다」고 풀었어요. 잘못 계산한 곳을 찾아 이유를 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 십의 자리 0은 4로 나눌 수 없으므로 몫의 십의 자리에 0을 쓰고 일의 자리 9를 4로 나누어 몫의 일의 자리에 2를 써야 하는데, 0을 끝에 붙였다. 409 ÷ 4 = 102 … 1이므로 한 명이 102장씩 가지고 1장이 남는다. 확인: 4 × 102 + 1 = 409.","scoring_points":["0을 쓰는 자리가 잘못되었다고 찾았는가","409 ÷ 4 = 102 … 1을 구했는가","4 × 102 + 1 = 409로 확인했는가"]},"explanation":["십의 자리 0 → 몫의 십의 자리에 0.","9 ÷ 4 = 2 … 1 — 409 ÷ 4 = 102 … 1.","4 × 102 + 1 = 409 — 120장이 아니라 102장이에요."],"asset":{"type":"ldiv","a":409,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#1','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'mc','auto','공공 도서관에서 책 526권을 5권씩 봉투에 담아 각 가정으로 보내려고 해요. 봉투는 몇 장 필요한가요? 남는 책은 몇 권인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],true,'{"seq":1,"concept":"M3-2-u2-C9","difficulty":1,"kind":"mc","stem":"공공 도서관에서 책 526권을 5권씩 봉투에 담아 각 가정으로 보내려고 해요. 봉투는 몇 장 필요한가요? 남는 책은 몇 권인가요?","options":[{"t":"봉투 105장, 책 1권이 남아요","correct":true},{"t":"봉투 104장, 책 6권이 남아요","mis":"M3-2-u2-X05"},{"t":"봉투 1장, 책 105권이 남아요","mis":"M3-2-u2-X06"},{"t":"봉투 105장, 책 0권이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 책 수를 봉투 한 장에 담는 책 수로 나누어요 — 식은 526 ÷ 5.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 2는 5로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 26 ÷ 5 → 몫 5.","526 ÷ 5 = 105 … 1 — 몫 105는 필요한 봉투 수, 나머지 1은 남는 책 수예요."],"variant_rule":{"alt":[{"stem":"공공 도서관에서 책 256권을 3권씩 봉투에 담아 각 가정으로 보내려고 해요. 봉투는 몇 장 필요한가요? 남는 책은 몇 권인가요?","options":[{"t":"봉투 85장, 책 1권이 남아요","correct":true},{"t":"봉투 84장, 책 4권이 남아요","mis":"M3-2-u2-X05"},{"t":"봉투 1장, 책 85권이 남아요","mis":"M3-2-u2-X06"},{"t":"봉투 85장, 책 0권이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 책 수를 봉투 한 장에 담는 책 수로 나누어요 — 식은 256 ÷ 3.","백의 자리 2는 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 3 → 몫 8, 1 남음 · 남은 1을 내려 16 ÷ 3 → 몫 5.","256 ÷ 3 = 85 … 1 — 몫 85는 필요한 봉투 수, 나머지 1은 남는 책 수예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#2','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C4',1,'mc','auto','책 526권을 5권씩 봉투에 담을 때, 계산하기 전에 526 ÷ 5의 몫을 어림하면 어느 사이에 있나요?',ARRAY['M3-2-u2-X16','M3-2-u2-X02']::text[],true,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"책 526권을 5권씩 봉투에 담을 때, 계산하기 전에 526 ÷ 5의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"100과 110 사이","correct":true},{"t":"100보다 작아요","mis":"M3-2-u2-X16"},{"t":"110보다 커요","mis":"M3-2-u2-X16"},{"t":"1000과 1100 사이","mis":"M3-2-u2-X02"}],"explanation":["526을 500으로 보면 500 ÷ 5 = 100이에요.","526을 550으로 보면 550 ÷ 5 = 110이에요.","그래서 몫은 100과 110 사이 — 실제로 계산한 몫 105예요."],"variant_rule":{"alt":[{"stem":"계산하기 전에 258 ÷ 4의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"50과 75 사이","correct":true},{"t":"50보다 작아요","mis":"M3-2-u2-X16"},{"t":"75보다 커요","mis":"M3-2-u2-X16"},{"t":"500과 750 사이","mis":"M3-2-u2-X02"}],"explanation":["258을 200으로 보면 200 ÷ 4 = 50이에요.","258을 300으로 보면 300 ÷ 4 = 75예요.","그래서 몫은 50과 75 사이 — 실제로 계산한 몫 64예요."]},{"stem":"계산하기 전에 197 ÷ 3의 몫을 어림하면 어느 사이에 있나요?","options":[{"t":"60과 70 사이","correct":true},{"t":"60보다 작아요","mis":"M3-2-u2-X16"},{"t":"70보다 커요","mis":"M3-2-u2-X16"},{"t":"600과 700 사이","mis":"M3-2-u2-X02"}],"explanation":["197을 180으로 보면 180 ÷ 3 = 60이에요.","197을 210으로 보면 210 ÷ 3 = 70이에요.","그래서 몫은 60과 70 사이 — 실제로 계산한 몫 65예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#3','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'sa','auto','258 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C9","difficulty":1,"kind":"sa","stem":"258 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","258 ÷ 4 = 64 … 2 — 확인: 4 × 64 + 2 = 258이에요."],"variant_rule":{"alt":[{"stem":"197 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["65"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 19로 보고 19 ÷ 3 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 3 → 몫 5.","197 ÷ 3 = 65 … 2 — 확인: 3 × 65 + 2 = 197이에요."]},{"stem":"831 ÷ 7의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["118"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 7 → 몫 1, 6 남음 · 남은 6을 내려 61 ÷ 7 → 몫 8.","831 ÷ 7 = 118 … 5 — 확인: 7 × 118 + 5 = 831이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#4','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',1,'sa','auto','258 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C9","difficulty":1,"kind":"sa","stem":"258 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","258 ÷ 4 = 64 … 2 — 확인: 4 × 64 + 2 = 258이에요."],"variant_rule":{"alt":[{"stem":"831 ÷ 7의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 7 → 몫 1, 6 남음 · 남은 6을 내려 61 ÷ 7 → 몫 8.","831 ÷ 7 = 118 … 5 — 확인: 7 × 118 + 5 = 831이에요."]},{"stem":"197 ÷ 3의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 19로 보고 19 ÷ 3 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 3 → 몫 5.","197 ÷ 3 = 65 … 2 — 확인: 3 × 65 + 2 = 197이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#5','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'sa','auto','197 ÷ 3 = 65 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"197 ÷ 3 = 65 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["195"],"explanation":["나누는 수 × 몫 = 3 × 65 = 195예요.","여기에 나머지 2를 더하면 197이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 65","=",null],["□ + 2","=","197"]]},"variant_rule":{"alt":[{"stem":"831 ÷ 7 = 118 … 5를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["826"],"explanation":["나누는 수 × 몫 = 7 × 118 = 826이에요.","여기에 나머지 5를 더하면 831이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["7 × 118","=",null],["□ + 5","=","831"]]}},{"stem":"256 ÷ 3 = 85 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["255"],"explanation":["나누는 수 × 몫 = 3 × 85 = 255예요.","여기에 나머지 1을 더하면 256이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 85","=",null],["□ + 1","=","256"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#6','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'mc','auto','258 ÷ 4의 몫은 몇 자리 수인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X12']::text[],true,'{"seq":6,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"258 ÷ 4의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 2와 나누는 수 4와 견주어요.","2는 4보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","258 ÷ 4 = 64 … 2."],"variant_rule":{"alt":[{"stem":"526 ÷ 5의 몫은 몇 자리 수인가요?","options":[{"t":"세 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"두 자리 수","mis":"M3-2-u2-X16"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 5와 나누는 수 5와 견주어요.","5 ÷ 5 — 백의 자리에 몫이 서요 — 몫은 세 자리.","526 ÷ 5 = 105 … 1."]},{"stem":"197 ÷ 3의 몫은 몇 자리 수인가요?","options":[{"t":"두 자리 수","correct":true},{"t":"한 자리 수","mis":"M3-2-u2-X16"},{"t":"세 자리 수","mis":"M3-2-u2-X12"},{"t":"네 자리 수","mis":"M3-2-u2-X16"}],"explanation":["백의 자리 1과 나누는 수 3과 견주어요.","1은 3보다 작아 백의 자리에는 몫이 서지 않아요 — 몫은 두 자리.","197 ÷ 3 = 65 … 2."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#7','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'sa','auto','526 ÷ 5의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"526 ÷ 5의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["0"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 5 ÷ 5 → 몫 1 · 십의 자리 2는 5로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 26 ÷ 5 → 몫 5.","526 ÷ 5 = 105 … 1 — 몫의 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":526,"b":5,"hide":[["q",1]]},"variant_rule":{"alt":[{"stem":"831 ÷ 7의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["1"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 13 ÷ 7 → 몫 1, 6 남음 · 남은 6을 내려 61 ÷ 7 → 몫 8.","831 ÷ 7 = 118 … 5 — 몫의 십의 자리 숫자는 1이에요."],"asset":{"type":"ldiv","a":831,"b":7,"hide":[["q",1]]}},{"stem":"258 ÷ 4의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["4"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","258 ÷ 4 = 64 … 2 — 몫의 일의 자리 숫자는 4예요."],"asset":{"type":"ldiv","a":258,"b":4,"hide":[["q",2]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#8','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'mc','auto','496 ÷ 6에 대해 옳게 설명한 것은 어느 것인가요?',ARRAY['M3-2-u2-X07','M3-2-u2-X20']::text[],false,'{"seq":8,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"496 ÷ 6에 대해 옳게 설명한 것은 어느 것인가요?","options":[{"t":"몫은 100보다 작아요","correct":true},{"t":"나머지는 0이에요","mis":"M3-2-u2-X07"},{"t":"나누어지는 수는 6이에요","mis":"M3-2-u2-X20"}],"explanation":["백의 자리 4는 6보다 작아 몫은 두 자리 — 100보다 작아요.","496 ÷ 6 = 82 … 4 — 나머지는 4예요.","496이 나누어지는 수, 6이 나누는 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#9','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',2,'ox','auto','257 ÷ 4 = 63 … 5예요.',ARRAY['M3-2-u2-X05']::text[],true,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":2,"kind":"ox","stem":"257 ÷ 4 = 63 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 4 → 몫 4.","바르게 계산하면 257 ÷ 4 = 64 … 1.","나머지 < 나누는 수 — 확인: 4 × 64 + 1 = 257이에요."],"asset":{"type":"ldiv","a":257,"b":4,"upto":0},"variant_rule":{"alt":[{"stem":"367 ÷ 3 = 121 … 4예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 7 ÷ 3 → 몫 2.","바르게 계산하면 367 ÷ 3 = 122 … 1.","나머지 < 나누는 수 — 확인: 3 × 122 + 1 = 367이에요."],"asset":{"type":"ldiv","a":367,"b":3,"upto":0}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_basic#10','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_basic','lesson_basic','M3-2-u2-C9',3,'error','auto','487 ÷ 5를 계산한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X17']::text[],false,'{"seq":10,"concept":"M3-2-u2-C9","difficulty":3,"kind":"error","stem":"487 ÷ 5를 계산한 친구들의 말이에요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지아 — 「몫은 79, 나머지는 2야」","correct":true,"mis_target":"M3-2-u2-X04"},{"t":"소율 — 「48을 5로 나누고 남은 3을 내려 37을 5로 나누어」","mis":"M3-2-u2-X17"},{"t":"민서 — 「몫은 97, 나머지는 2야」","mis":"M3-2-u2-X17"}],"explanation":["백의 자리 4는 5보다 작아 48을 함께 봐요 — 48 ÷ 5 → 몫 9, 3 남음.","남은 3을 내려 37 ÷ 5 → 몫 7, 2 남음 — 487 ÷ 5 = 97 … 2.","지아는 몫을 일의 자리부터 썼어요 — 몫은 높은 자리부터 써요."],"asset":{"type":"ldiv","a":487,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#1','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',2,'mc','auto','615 ÷ 6을 바르게 계산한 것은 어느 것인가요?',ARRAY['M3-2-u2-X11','M3-2-u2-X10','M3-2-u2-X05']::text[],false,'{"seq":1,"concept":"M3-2-u2-C9","difficulty":2,"kind":"mc","stem":"615 ÷ 6을 바르게 계산한 것은 어느 것인가요?","options":[{"t":"102 … 3","correct":true},{"t":"120 … 3","mis":"M3-2-u2-X11"},{"t":"12 … 3","mis":"M3-2-u2-X10"},{"t":"101 … 9","mis":"M3-2-u2-X05"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 1은 6으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 15 ÷ 6 → 몫 2.","615 ÷ 6 = 102 … 3 — 확인: 6 × 102 + 3 = 615예요."],"asset":{"type":"ldiv","a":615,"b":6,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#2','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C4',2,'sa','auto','지아는 485 ÷ 5의 몫을 약 100으로 어림했어요. 지아가 어림한 몫과 실제로 계산한 몫의 차는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C4","difficulty":2,"kind":"sa","stem":"지아는 485 ÷ 5의 몫을 약 100으로 어림했어요. 지아가 어림한 몫과 실제로 계산한 몫의 차는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["485는 500에 가까워 500 ÷ 5 = 100으로 어림했어요.","실제로 계산하면 485 ÷ 5 = 97이에요.","100 − 97 = 3 — 차는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#3','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'mc','auto','961, 269, 339, 594를 각각 8로 나누었을 때 나머지가 가장 큰 수는 어느 것인가요?',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":3,"concept":"M3-2-u2-C9","difficulty":3,"kind":"mc","stem":"961, 269, 339, 594를 각각 8로 나누었을 때 나머지가 가장 큰 수는 어느 것인가요?","options":[{"t":"269","correct":true},{"t":"961","mis":"M3-2-u2-X17"},{"t":"339","mis":"M3-2-u2-X15"},{"t":"594","mis":"M3-2-u2-X15"}],"explanation":["961 ÷ 8 = 120 … 1, 269 ÷ 8 = 33 … 5.","339 ÷ 8 = 42 … 3, 594 ÷ 8 = 74 … 2.","나머지가 가장 큰 수는 269 — 큰 수라고 나머지가 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#4','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'mc','auto','37□ ÷ 4는 나누어떨어지는 나눗셈이에요. 0부터 9까지의 수 가운데 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":4,"concept":"M3-2-u2-C9","difficulty":3,"kind":"mc","stem":"37□ ÷ 4는 나누어떨어지는 나눗셈이에요. 0부터 9까지의 수 가운데 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2, 6","correct":true},{"t":"2","mis":"M3-2-u2-X15"},{"t":"0, 4, 8","mis":"M3-2-u2-X15"},{"t":"6","mis":"M3-2-u2-X15"}],"explanation":["백의 자리 3은 4보다 작아 37을 봐요 — 37 ÷ 4 = 9 … 1.","남은 1을 내리면 1□가 4로 나누어떨어져야 해요 — 12와 16.","그래서 □는 2와 6 — 372 ÷ 4 = 93, 376 ÷ 4 = 94예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#5','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'mc','auto','달력에 숨어 있는 나눗셈이에요. 2026년 2월 28일은 토요일이에요. 1년은 365일이고 365 ÷ 7 = 52 … 1이에요. 2027년 2월 28일은 무슨 요일인가요?',ARRAY['M3-2-u2-X07','M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":5,"concept":"M3-2-u2-C9","difficulty":3,"kind":"mc","stem":"달력에 숨어 있는 나눗셈이에요. 2026년 2월 28일은 토요일이에요. 1년은 365일이고 365 ÷ 7 = 52 … 1이에요. 2027년 2월 28일은 무슨 요일인가요?","options":[{"t":"일요일","correct":true},{"t":"토요일","mis":"M3-2-u2-X07"},{"t":"월요일","mis":"M3-2-u2-X15"},{"t":"금요일","mis":"M3-2-u2-X17"}],"explanation":["365일은 7일씩 52주와 하루 — 365 ÷ 7 = 52 … 1이에요.","52주가 지나면 같은 토요일, 남은 하루만큼 한 요일 뒤로 가요.","그래서 2027년 2월 28일은 일요일이에요."],"asset":{"type":"cal","mon":2,"start":0,"days":28,"marks":{"28":"⭐"},"y":2026}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#6','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',3,'sa','auto','서윤이 487 ÷ 5를 계산하고 몫을 79라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-2-u2-C9","difficulty":3,"kind":"sa","stem":"서윤이 487 ÷ 5를 계산하고 몫을 79라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["97"],"explanation":["서윤 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","백의 자리 4는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 48로 보고 48 ÷ 5 → 몫 9, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","바른 몫은 97 — 확인: 5 × 97 + 2 = 487이에요."],"variant_rule":{"alt":[{"stem":"민준이 258 ÷ 4를 계산하고 몫을 46이라고 썼어요. 바르게 계산한 몫은 얼마인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["민준 — 몫을 낮은 자리부터 거꾸로 쓰거나 자리를 바꾸어 쓴다.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","바른 몫은 64 — 확인: 4 × 64 + 2 = 258이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#7','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C4',3,'mc','auto','526 ÷ 5의 몫을 500 ÷ 5 = 100으로 어림했어요. 실제 몫은 100과 견주어 어떤가요?',ARRAY['M3-2-u2-X16']::text[],true,'{"seq":7,"concept":"M3-2-u2-C4","difficulty":3,"kind":"mc","stem":"526 ÷ 5의 몫을 500 ÷ 5 = 100으로 어림했어요. 실제 몫은 100과 견주어 어떤가요?","options":[{"t":"100보다 커요","correct":true},{"t":"100보다 작아요","mis":"M3-2-u2-X16"},{"t":"100과 같아요","mis":"M3-2-u2-X16"}],"explanation":["526은 500보다 커요.","나누어지는 수가 크면 같은 수로 나눈 몫도 커요.","526 ÷ 5 = 105 … 1 — 실제 몫 105는 100보다 커요."],"variant_rule":{"alt":[{"stem":"60 ÷ 5의 몫을 50 ÷ 5 = 10으로 어림했어요. 실제 몫은 10과 견주어 어떤가요?","options":[{"t":"10보다 커요","correct":true},{"t":"10보다 작아요","mis":"M3-2-u2-X16"},{"t":"10과 같아요","mis":"M3-2-u2-X16"}],"explanation":["60은 50보다 커요.","나누어지는 수가 크면 같은 수로 나눈 몫도 커요.","60 ÷ 5 = 12 — 실제 몫 12는 10보다 커요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#8','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'essay','teacher','공공 도서관에서 책 526권을 5권씩 봉투에 담아 보내요. 필요한 봉투 수를 먼저 어림하고, 526 ÷ 5를 계산한 뒤 어림한 값과 견주어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C9","difficulty":4,"kind":"essay","stem":"공공 도서관에서 책 526권을 5권씩 봉투에 담아 보내요. 필요한 봉투 수를 먼저 어림하고, 526 ÷ 5를 계산한 뒤 어림한 값과 견주어 보세요.","answer_guide":{"answer":"예: 책을 약 500권으로 생각하면 500 ÷ 5 = 100이므로 봉투는 약 100장 필요하다. 526의 백의 자리 5를 5로 나누어 몫의 백의 자리에 1, 십의 자리 2는 5로 나눌 수 없어 몫의 십의 자리에 0, 26을 5로 나누어 몫의 일의 자리에 5를 쓰면 1이 남는다. 526 ÷ 5 = 105 … 1이므로 봉투 105장이 필요하고 책 1권이 남는다. 어림한 100장과 비슷하다.","scoring_points":["500 ÷ 5 = 100으로 어림했는가","526 ÷ 5 = 105 … 1을 구했는가","어림한 값과 견주었는가"]},"explanation":["어림: 500 ÷ 5 = 100.","5 ÷ 5 = 1 · 2 → 몫 0 · 26 ÷ 5 = 5 … 1.","526 ÷ 5 = 105 … 1 — 어림한 100과 비슷해요."],"asset":{"type":"ldiv","a":526,"b":5,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#9','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'essay','teacher','친구들이 257 ÷ 4를 「63 … 5」, 487 ÷ 5를 「79 … 2」라고 계산했어요. 잘못 계산한 곳을 찾아 각각 이유를 설명하고, 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C9","difficulty":4,"kind":"essay","stem":"친구들이 257 ÷ 4를 「63 … 5」, 487 ÷ 5를 「79 … 2」라고 계산했어요. 잘못 계산한 곳을 찾아 각각 이유를 설명하고, 바르게 계산해 보세요.","answer_guide":{"answer":"예: 257 ÷ 4는 나머지 5가 나누는 수 4보다 크므로 몫을 1 더 키워야 한다 — 257 ÷ 4 = 64 … 1. 487 ÷ 5는 몫을 일의 자리부터 썼다 — 높은 자리부터 써야 하므로 487 ÷ 5 = 97 … 2이다.","scoring_points":["257 ÷ 4의 나머지가 나누는 수보다 크다고 찾았는가","487 ÷ 5의 몫을 거꾸로 썼다고 찾았는가","64 … 1과 97 … 2를 구했는가"]},"explanation":["나머지는 나누는 수보다 작아야 해요 — 257 ÷ 4 = 64 … 1.","몫은 높은 자리부터 써요 — 487 ÷ 5 = 97 … 2.","확인: 4 × 64 + 1 = 257, 5 × 97 + 2 = 487."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L09_challenge#10','math',3,2,'u2','L09','tb_g3_2_math_u2_L09_challenge','lesson_challenge','M3-2-u2-C9',4,'mc','auto','2028년 2월 28일은 월요일이에요. 2028년에는 2월 29일이 있어서 2029년 2월 28일까지는 366일이에요. 2029년 2월 28일은 무슨 요일인가요?',ARRAY['M3-2-u2-X07','M3-2-u2-X15']::text[],false,'{"seq":10,"concept":"M3-2-u2-C9","difficulty":4,"kind":"mc","stem":"2028년 2월 28일은 월요일이에요. 2028년에는 2월 29일이 있어서 2029년 2월 28일까지는 366일이에요. 2029년 2월 28일은 무슨 요일인가요?","options":[{"t":"수요일","correct":true},{"t":"화요일","mis":"M3-2-u2-X07"},{"t":"월요일","mis":"M3-2-u2-X07"},{"t":"목요일","mis":"M3-2-u2-X15"}],"explanation":["366 ÷ 7 = 52 … 2 — 52주와 이틀이에요.","52주 뒤는 같은 월요일, 이틀 더 가면 수요일이에요.","2월 29일이 있는 해를 지나면 요일이 두 칸 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#1','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 빨간색 블록 480개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 빨간색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["120"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 480 ÷ 4.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 0 → 몫 0.","480 ÷ 4 = 120 — 한 개에 120개씩, 남는 블록은 없어요."],"variant_rule":{"alt":[{"stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 노란색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["25"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 150 ÷ 6.","백의 자리 1은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 15로 보고 15 ÷ 6 → 몫 2, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","150 ÷ 6 = 25 — 한 개에 25개씩, 남는 블록은 없어요."]},{"stem":"정후가 회색 블록 690개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 회색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["230"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 690 ÷ 3.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 0 → 몫 0.","690 ÷ 3 = 230 — 한 개에 230개씩, 남는 블록은 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#2','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["남는 블록은 나머지예요 — 식은 687 ÷ 4.","백의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 28 ÷ 4 → 몫 7 · 일의 자리 7 ÷ 4 → 몫 1.","687 ÷ 4 = 171 … 3 — 남는 블록 3개."],"variant_rule":{"alt":[{"stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리를 만들고 남는 흰색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["남는 블록은 나머지예요 — 식은 341 ÷ 6.","백의 자리 3은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 6 → 몫 5, 4 남음 · 남은 4를 내려 41 ÷ 6 → 몫 6.","341 ÷ 6 = 56 … 5 — 남는 블록 5개."]},{"stem":"정후가 검은색 블록 314개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 검은색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남는 블록은 나머지예요 — 식은 314 ÷ 3.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 1은 3으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 14 ÷ 3 → 몫 4.","314 ÷ 3 = 104 … 2 — 남는 블록 2개."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#3','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-2-u2-C10","difficulty":1,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["85"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 341 ÷ 4.","백의 자리 3은 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 4 → 몫 8, 2 남음 · 남은 2를 내려 21 ÷ 4 → 몫 5.","341 ÷ 4 = 85 … 1 — 한 개에 85개씩, 1개가 남아요."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 6개를 만들려고 해요. 열쇠고리 한 개에 갈색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["15"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 92 ÷ 6.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 6 → 몫 5.","92 ÷ 6 = 15 … 2 — 한 개에 15개씩, 2개가 남아요."]},{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 분홍색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["28"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 85 ÷ 3.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 25 ÷ 3 → 몫 8.","85 ÷ 3 = 28 … 1 — 한 개에 28개씩, 1개가 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#4','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',1,'mc','auto','태민이는 3가지 색깔의 블록을 골라 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개를 만드는 데 빨간색 블록(480개)을 몇 개까지 사용할 수 있는지 구하는 식은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X14']::text[],false,'{"seq":4,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"태민이는 3가지 색깔의 블록을 골라 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개를 만드는 데 빨간색 블록(480개)을 몇 개까지 사용할 수 있는지 구하는 식은 어느 것인가요?","options":[{"t":"480 ÷ 4","correct":true},{"t":"480 ÷ 3","mis":"M3-2-u2-X20"},{"t":"480 × 4","mis":"M3-2-u2-X14"},{"t":"480 − 4","mis":"M3-2-u2-X14"}],"explanation":["똑같은 열쇠고리 4개 — 블록을 4로 똑같이 나누어요.","고른 색깔 수 3은 나눗셈을 몇 번 할지 알려 줄 뿐이에요.","480 ÷ 4 = 120 — 한 개에 120개까지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#5','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이의 블록 가운데 주황색 252개, 초록색 90개, 검은색 687개, 흰색 341개를 골랐어요. 똑같은 열쇠고리 4개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],true,'{"seq":5,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이의 블록 가운데 주황색 252개, 초록색 90개, 검은색 687개, 흰색 341개를 골랐어요. 똑같은 열쇠고리 4개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"주황색","correct":true},{"t":"초록색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"},{"t":"흰색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 4로 나누어 나머지를 봐요.","주황색 252 ÷ 4 → 나머지 0, 초록색 90 ÷ 4 → 나머지 2, 검은색 687 ÷ 4 → 나머지 3, 흰색 341 ÷ 4 → 나머지 1.","나머지가 0인 주황색이 남는 블록이 없어요 — 나누어떨어져요."],"variant_rule":{"alt":[{"stem":"태민이의 블록 가운데 노란색 150개, 흰색 341개, 갈색 92개, 검은색 687개를 골랐어요. 똑같은 열쇠고리 6개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"노란색","correct":true},{"t":"흰색","mis":"M3-2-u2-X07"},{"t":"갈색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 6으로 나누어 나머지를 봐요.","노란색 150 ÷ 6 → 나머지 0, 흰색 341 ÷ 6 → 나머지 5, 갈색 92 ÷ 6 → 나머지 2, 검은색 687 ÷ 6 → 나머지 3.","나머지가 0인 노란색이 남는 블록이 없어요 — 나누어떨어져요."]},{"stem":"정후의 블록 가운데 분홍색 85개, 검은색 314개, 흰색 112개, 회색 690개를 골랐어요. 똑같은 열쇠고리 3개를 만들 때 남는 블록이 하나도 없는 색깔은 어느 것인가요?","options":[{"t":"회색","correct":true},{"t":"분홍색","mis":"M3-2-u2-X07"},{"t":"검은색","mis":"M3-2-u2-X07"},{"t":"흰색","mis":"M3-2-u2-X07"}],"explanation":["색깔마다 블록 수를 3으로 나누어 나머지를 봐요.","회색 690 ÷ 3 → 나머지 0, 분홍색 85 ÷ 3 → 나머지 1, 검은색 314 ÷ 3 → 나머지 2, 흰색 112 ÷ 3 → 나머지 1.","나머지가 0인 회색이 남는 블록이 없어요 — 나누어떨어져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#6','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이 파란색 블록 48개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":6,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 파란색 블록 48개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 9개씩 쓰고 3개가 남아요","correct":true},{"t":"한 개에 8개씩 쓰고 8개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 3개씩 쓰고 9개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 9개씩 쓰고 4개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["48 ÷ 5 — 몫은 한 개에 쓰는 블록 수, 나머지는 남는 블록 수.","5 × 9 = 45 — 몫 9, 48 − 45 = 3이 남아요.","48 ÷ 5 = 9 … 3."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 18개씩 쓰고 2개가 남아요","correct":true},{"t":"한 개에 17개씩 쓰고 7개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 2개씩 쓰고 18개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 18개씩 쓰고 3개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["92 ÷ 5 — 몫은 한 개에 쓰는 블록 수, 나머지는 남는 블록 수.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 42 ÷ 5 → 몫 8.","92 ÷ 5 = 18 … 2."]},{"stem":"태민이 주황색 블록 252개로 똑같은 열쇠고리 5개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 50개씩 쓰고 2개가 남아요","correct":true},{"t":"한 개에 49개씩 쓰고 7개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 2개씩 쓰고 50개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 50개씩 쓰고 3개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["252 ÷ 5 — 몫은 한 개에 쓰는 블록 수, 나머지는 남는 블록 수.","백의 자리 2는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 5 → 몫 5 · 일의 자리 2는 5로 나눌 수 없어 몫 0.","252 ÷ 5 = 50 … 2."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#7','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["137"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 687 ÷ 5.","백의 자리 6 ÷ 5 → 몫 1, 1 남음 · 남은 1을 내려 18 ÷ 5 → 몫 3, 3 남음 · 남은 3을 내려 37 ÷ 5 → 몫 7.","687 ÷ 5 = 137 … 2 — 한 개에 137개씩, 2개가 남아요."],"variant_rule":{"alt":[{"stem":"태민이 주황색 블록 252개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 주황색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["50"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 252 ÷ 5.","백의 자리 2는 5보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 5 → 몫 5 · 일의 자리 2는 5로 나눌 수 없어 몫 0.","252 ÷ 5 = 50 … 2 — 한 개에 50개씩, 2개가 남아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#8','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'error','auto','태민이가 빨간색, 검은색, 흰색을 골라 똑같은 열쇠고리 4개를 만들 때의 표를 썼어요. 잘못 쓴 줄은 어느 것인가요?',ARRAY['M3-2-u2-X07','M3-2-u2-X17']::text[],false,'{"seq":8,"concept":"M3-2-u2-C10","difficulty":2,"kind":"error","stem":"태민이가 빨간색, 검은색, 흰색을 골라 똑같은 열쇠고리 4개를 만들 때의 표를 썼어요. 잘못 쓴 줄은 어느 것인가요?","options":[{"t":"검은색 — 687 ÷ 4 = 171 … 3, 사용 171개, 남는 블록 0개","correct":true,"mis_target":"M3-2-u2-X07"},{"t":"빨간색 — 480 ÷ 4 = 120, 사용 120개, 남는 블록 0개","mis":"M3-2-u2-X17"},{"t":"흰색 — 341 ÷ 4 = 85 … 1, 사용 85개, 남는 블록 1개","mis":"M3-2-u2-X17"}],"explanation":["빨간색 480 ÷ 4 = 120 — 남는 블록은 없어요.","검은색 687 ÷ 4 = 171 … 3 — 나머지 3이 남는 블록 수예요.","나머지는 남는 블록 수로 써야 해요 — 검은색은 3개가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#9','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',2,'mc','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리를 4개 또는 6개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15','M3-2-u2-X17']::text[],true,'{"seq":9,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리를 4개 또는 6개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["341 ÷ 4 = 85 … 1.","341 ÷ 6 = 56 … 5.","남는 블록 1개와 5개 — 4개 만들 때 더 적어요."],"variant_rule":{"alt":[{"stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리를 4개 또는 5개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["687 ÷ 4 = 171 … 3.","687 ÷ 5 = 137 … 2.","남는 블록 3개와 2개 — 5개 만들 때 더 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_basic#10','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_basic','lesson_basic','M3-2-u2-C10',3,'mc','auto','정후는 분홍색 85개, 검은색 314개, 흰색 112개, 회색 690개를 골라 똑같은 열쇠고리 3개를 만들었어요. 남는 블록은 모두 몇 개인가요?',ARRAY['M3-2-u2-X07','M3-2-u2-X15','M3-2-u2-X05']::text[],false,'{"seq":10,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"정후는 분홍색 85개, 검은색 314개, 흰색 112개, 회색 690개를 골라 똑같은 열쇠고리 3개를 만들었어요. 남는 블록은 모두 몇 개인가요?","options":[{"t":"4개","correct":true},{"t":"0개","mis":"M3-2-u2-X07"},{"t":"3개","mis":"M3-2-u2-X15"},{"t":"12개","mis":"M3-2-u2-X05"}],"explanation":["분홍색 85 ÷ 3 = 28 … 1, 검은색 314 ÷ 3 = 104 … 2.","흰색 112 ÷ 3 = 37 … 1, 회색 690 ÷ 3 = 230.","남는 블록은 1 + 2 + 1 + 0 = 4 — 모두 4개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#1','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',2,'sa','auto','정후가 빨간색 블록 80개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 빨간색 블록은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"정후가 빨간색 블록 80개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 빨간색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남는 블록은 나머지예요 — 식은 80 ÷ 3.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 20 ÷ 3 → 몫 6.","80 ÷ 3 = 26 … 2 — 남는 블록 2개."],"variant_rule":{"alt":[{"stem":"정후가 초록색 블록 50개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 초록색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["남는 블록은 나머지예요 — 식은 50 ÷ 3.","십의 자리 5 ÷ 3 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 3 → 몫 6.","50 ÷ 3 = 16 … 2 — 남는 블록 2개."]},{"stem":"정후가 노란색 블록 100개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리를 만들고 남는 노란색 블록은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["남는 블록은 나머지예요 — 식은 100 ÷ 3.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 10으로 보고 10 ÷ 3 → 몫 3, 1 남음 · 남은 1을 내려 10 ÷ 3 → 몫 3.","100 ÷ 3 = 33 … 1 — 남는 블록 1개."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#2','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',2,'mc','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 어떻게 되나요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X15']::text[],true,'{"seq":2,"concept":"M3-2-u2-C10","difficulty":2,"kind":"mc","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 6개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 56개씩 쓰고 5개가 남아요","correct":true},{"t":"한 개에 55개씩 쓰고 11개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 5개씩 쓰고 56개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 57개씩 쓰고 4개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["341 ÷ 6 — 몫은 한 개에 쓰는 블록 수, 나머지는 남는 블록 수.","백의 자리 3은 6보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 34로 보고 34 ÷ 6 → 몫 5, 4 남음 · 남은 4를 내려 41 ÷ 6 → 몫 6.","341 ÷ 6 = 56 … 5."],"variant_rule":{"alt":[{"stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 6개를 만들려고 해요. 어떻게 되나요?","options":[{"t":"한 개에 15개씩 쓰고 2개가 남아요","correct":true},{"t":"한 개에 14개씩 쓰고 8개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 개에 2개씩 쓰고 15개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 개에 15개씩 쓰고 3개가 남아요","mis":"M3-2-u2-X15"}],"explanation":["92 ÷ 6 — 몫은 한 개에 쓰는 블록 수, 나머지는 남는 블록 수.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 32 ÷ 6 → 몫 5.","92 ÷ 6 = 15 … 2."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#3','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'error','auto','똑같은 열쇠고리 4개를 만들려고 빨간색, 검은색, 흰색 블록을 골랐어요. 친구들이 열쇠고리 한 개에 쓸 블록 수를 구했어요. 잘못 구한 친구는 누구인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X17']::text[],false,'{"seq":3,"concept":"M3-2-u2-C10","difficulty":3,"kind":"error","stem":"똑같은 열쇠고리 4개를 만들려고 빨간색, 검은색, 흰색 블록을 골랐어요. 친구들이 열쇠고리 한 개에 쓸 블록 수를 구했어요. 잘못 구한 친구는 누구인가요?","options":[{"t":"지아 — 「빨간색은 480 ÷ 3 = 160이라 한 개에 160개씩」","correct":true,"mis_target":"M3-2-u2-X20"},{"t":"채원 — 「빨간색은 480 ÷ 4 = 120이라 한 개에 120개씩」","mis":"M3-2-u2-X17"},{"t":"서윤 — 「흰색은 341 ÷ 4 = 85 … 1이라 85개씩 쓰고 1개 남아」","mis":"M3-2-u2-X17"}],"explanation":["똑같이 만들 열쇠고리 수 4가 나누는 수예요.","480 ÷ 4 = 120, 341 ÷ 4 = 85 … 1이에요.","지아는 고른 색깔 수 3으로 나누었어요 — 색깔 수는 나눗셈을 몇 번 할지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#4','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-2-u2-C10","difficulty":3,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["341 ÷ 4 = 85 … 1 — 한 개에 85개씩 쓰고 1개가 남아요.","한 개에 86개씩 쓰려면 4 × 86 = 344개가 필요해요.","344 − 341 = 3 — 적어도 3개 더 있어야 해요."],"variant_rule":{"alt":[{"stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 분홍색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["85 ÷ 3 = 28 … 1 — 한 개에 28개씩 쓰고 1개가 남아요.","한 개에 29개씩 쓰려면 3 × 29 = 87개가 필요해요.","87 − 85 = 2 — 적어도 2개 더 있어야 해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#5','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'mc','auto','태민이 노란색 블록 150개로 똑같은 열쇠고리를 4개 또는 6개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?',ARRAY['M3-2-u2-X13','M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":5,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"태민이 노란색 블록 150개로 똑같은 열쇠고리를 4개 또는 6개 만들려고 해요. 남는 블록이 더 적은 것은 열쇠고리를 몇 개 만들 때인가요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M3-2-u2-X13"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["150 ÷ 4 = 37 … 2.","150 ÷ 6 = 25.","남는 블록 2개와 0개 — 6개 만들 때 더 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#6','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'mc','auto','태민이가 똑같은 열쇠고리 4개를 만들 때, 해결 방안 1(빨간색 480개, 검은색 687개, 흰색 341개)과 해결 방안 2(주황색 252개, 초록색 90개, 검은색 687개) 가운데 남는 블록이 모두 더 적은 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":6,"concept":"M3-2-u2-C10","difficulty":3,"kind":"mc","stem":"태민이가 똑같은 열쇠고리 4개를 만들 때, 해결 방안 1(빨간색 480개, 검은색 687개, 흰색 341개)과 해결 방안 2(주황색 252개, 초록색 90개, 검은색 687개) 가운데 남는 블록이 모두 더 적은 것은 어느 것인가요?","options":[{"t":"해결 방안 1","correct":true},{"t":"해결 방안 2","mis":"M3-2-u2-X15"},{"t":"남는 블록이 같아요","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["해결 방안 1: 480 ÷ 4 = 120, 687 ÷ 4 = 171 … 3, 341 ÷ 4 = 85 … 1 — 남는 블록 0 + 3 + 1 = 4.","해결 방안 2: 252 ÷ 4 = 63, 90 ÷ 4 = 22 … 2, 687 ÷ 4 = 171 … 3 — 남는 블록 0 + 2 + 3 = 5.","4개가 5개보다 적어요 — 해결 방안 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#7','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',3,'sa','auto','정후는 파란색 60개, 분홍색 85개, 검은색 314개, 흰색 112개를 골라 똑같은 열쇠고리 3개를 만들었어요. 열쇠고리 한 개에 사용한 블록은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":3,"kind":"sa","stem":"정후는 파란색 60개, 분홍색 85개, 검은색 314개, 흰색 112개를 골라 똑같은 열쇠고리 3개를 만들었어요. 열쇠고리 한 개에 사용한 블록은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["189"],"explanation":["파란색 60 ÷ 3 = 20, 분홍색 85 ÷ 3 = 28 … 1.","검은색 314 ÷ 3 = 104 … 2, 흰색 112 ÷ 3 = 37 … 1.","한 개에 20 + 28 + 104 + 37 = 189 — 189개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#8','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'essay','teacher','태민이의 블록은 빨간색 480개, 검은색 687개, 흰색 341개예요. 이 3가지 색깔로 똑같은 열쇠고리 4개를 만들 때 색깔마다 한 개에 사용할 수 있는 블록 수와 남는 블록 수를 구하고, 몫과 나머지의 뜻을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"태민이의 블록은 빨간색 480개, 검은색 687개, 흰색 341개예요. 이 3가지 색깔로 똑같은 열쇠고리 4개를 만들 때 색깔마다 한 개에 사용할 수 있는 블록 수와 남는 블록 수를 구하고, 몫과 나머지의 뜻을 써 보세요.","answer_guide":{"answer":"예: 빨간색 480 ÷ 4 = 120이므로 한 개에 120개를 사용하고 남는 블록은 없다. 검은색 687 ÷ 4 = 171 … 3이므로 171개를 사용하고 3개가 남는다. 흰색 341 ÷ 4 = 85 … 1이므로 85개를 사용하고 1개가 남는다. 몫은 한 개에 사용할 수 있는 블록 수, 나머지는 남는 블록 수이다.","scoring_points":["480 ÷ 4 = 120을 구했는가","687 ÷ 4 = 171 … 3, 341 ÷ 4 = 85 … 1을 구했는가","몫과 나머지의 뜻을 썼는가"]},"explanation":["480 ÷ 4 = 120.","687 ÷ 4 = 171 … 3, 341 ÷ 4 = 85 … 1.","몫 = 한 개에 쓰는 블록, 나머지 = 남는 블록."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#9','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'essay','teacher','태민이의 블록(빨간색 480, 주황색 252, 초록색 90, 파란색 48, 노란색 150, 검은색 687, 흰색 341, 갈색 92)으로 고를 색깔 수와 만들 열쇠고리 수를 바꾸어 문제를 새로 만들고 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"태민이의 블록(빨간색 480, 주황색 252, 초록색 90, 파란색 48, 노란색 150, 검은색 687, 흰색 341, 갈색 92)으로 고를 색깔 수와 만들 열쇠고리 수를 바꾸어 문제를 새로 만들고 계산해 보세요.","answer_guide":{"answer":"예: 4가지 색깔(주황색, 파란색, 검은색, 갈색)로 똑같은 열쇠고리 5개를 만든다. 주황색 252 ÷ 5 = 50 … 2, 파란색 48 ÷ 5 = 9 … 3, 검은색 687 ÷ 5 = 137 … 2, 갈색 92 ÷ 5 = 18 … 2이므로 한 개에 주황색 50개, 파란색 9개, 검은색 137개, 갈색 18개를 쓰고 2개, 3개, 2개, 2개가 남는다.","scoring_points":["색깔 수와 열쇠고리 수를 바꾸어 문제를 만들었는가","열쇠고리 수로 나누어 몫과 나머지를 구했는가","몫과 나머지를 블록 수로 바르게 답했는가"]},"explanation":["만들 열쇠고리 수가 나누는 수예요.","색깔마다 블록 수 ÷ 열쇠고리 수를 계산해요.","몫은 한 개에 쓰는 블록, 나머지는 남는 블록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_L10_challenge#10','math',3,2,'u2','L10','tb_g3_2_math_u2_L10_challenge','lesson_challenge','M3-2-u2-C10',4,'essay','teacher','똑같은 열쇠고리 4개를 만들려고 빨간색 480개, 검은색 687개, 흰색 341개를 골랐는데, 친구가 480 ÷ 3, 687 ÷ 3, 341 ÷ 3을 계산했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"똑같은 열쇠고리 4개를 만들려고 빨간색 480개, 검은색 687개, 흰색 341개를 골랐는데, 친구가 480 ÷ 3, 687 ÷ 3, 341 ÷ 3을 계산했어요. 무엇이 잘못되었는지 설명하고 바르게 고쳐 보세요.","answer_guide":{"answer":"예: 고른 색깔 수 3으로 나누었다. 색깔 수 3은 나눗셈을 세 번 해야 한다는 뜻이고, 똑같이 만들 열쇠고리 수 4가 나누는 수가 되어야 한다. 바르게 하면 480 ÷ 4 = 120, 687 ÷ 4 = 171 … 3, 341 ÷ 4 = 85 … 1이다.","scoring_points":["색깔 수로 나눈 잘못을 찾았는가","열쇠고리 수 4가 나누는 수라고 설명했는가","세 나눗셈을 바르게 계산했는가"]},"explanation":["나누는 수 = 똑같이 만들 열쇠고리 수 4.","색깔 수 3 = 해야 할 나눗셈의 개수.","480 ÷ 4 = 120, 687 ÷ 4 = 171 … 3, 341 ÷ 4 = 85 … 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#1','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C1',1,'sa','auto','60 ÷ 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"60 ÷ 6은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["60은 10 카드 6장 — 6 ÷ 6 = 1이에요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","60 ÷ 6 = 10 — 확인: 6 × 10 = 60이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#2','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C3',1,'sa','auto','96 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"96 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 6 ÷ 3 → 몫 2.","96 ÷ 3 = 32 — 확인: 3 × 32 = 96이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#3','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C5',1,'sa','auto','계산해 보세요. 84 ÷ 6을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"계산해 보세요. 84 ÷ 6을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 6 → 몫 1, 2 남음 · 남은 2를 내려 24 ÷ 6 → 몫 4.","84 ÷ 6 = 14 — 확인: 6 × 14 = 84예요."],"asset":{"type":"ldiv","a":84,"b":6,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#4','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',1,'mc','auto','999 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":1,"kind":"mc","stem":"999 ÷ 8의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"124 … 7","correct":true},{"t":"123 … 15","mis":"M3-2-u2-X05"},{"t":"7 … 124","mis":"M3-2-u2-X06"},{"t":"124","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 8 → 몫 2, 3 남음 · 남은 3을 내려 39 ÷ 8 → 몫 4.","999 ÷ 8 = 124 … 7 — 확인: 8 × 124 + 7 = 999예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#5','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C3',1,'mc','auto','몫이 가장 큰 것은 어느 것인가요? 90 ÷ 3, 92 ÷ 4, 70 ÷ 2, 160 ÷ 5',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요? 90 ÷ 3, 92 ÷ 4, 70 ÷ 2, 160 ÷ 5","options":[{"t":"70 ÷ 2","correct":true},{"t":"90 ÷ 3","mis":"M3-2-u2-X15"},{"t":"92 ÷ 4","mis":"M3-2-u2-X15"},{"t":"160 ÷ 5","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","90 ÷ 3 = 30, 92 ÷ 4 = 23, 70 ÷ 2 = 35, 160 ÷ 5 = 32.","몫이 가장 큰 것은 70 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#6','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C4',1,'mc','auto','공깃돌 95개를 한 명에게 5개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있는지 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X16','M3-2-u2-X17']::text[],false,'{"seq":6,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"공깃돌 95개를 한 명에게 5개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있는지 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"약 20명, 19명","correct":true},{"t":"약 20명, 21명","mis":"M3-2-u2-X15"},{"t":"약 10명, 19명","mis":"M3-2-u2-X16"},{"t":"약 19명, 20명","mis":"M3-2-u2-X17"}],"explanation":["95를 100으로 보면 100 ÷ 5 = 20 — 약 20명이에요.","실제로 계산하면 95 ÷ 5 = 19 — 19명이에요.","어림한 값과 실제 값이 비슷해 알맞게 계산했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#7','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',1,'mc','auto','호두과자 120개를 7명에게 똑같이 나누어 주려고 해요. 한 명에게 줄 수 있는 호두과자는 몇 개인가요? 남는 호두과자는 몇 개인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"호두과자 120개를 7명에게 똑같이 나누어 주려고 해요. 한 명에게 줄 수 있는 호두과자는 몇 개인가요? 남는 호두과자는 몇 개인가요?","options":[{"t":"한 명에게 17개씩, 1개가 남아요","correct":true},{"t":"한 명에게 16개씩, 8개가 남아요","mis":"M3-2-u2-X05"},{"t":"한 명에게 1개씩, 17개가 남아요","mis":"M3-2-u2-X06"},{"t":"한 명에게 17개씩, 0개가 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 호두과자 수를 사람 수로 나누어요 — 식은 120 ÷ 7.","백의 자리 1은 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 12로 보고 12 ÷ 7 → 몫 1, 5 남음 · 남은 5를 내려 50 ÷ 7 → 몫 7.","120 ÷ 7 = 17 … 1 — 몫 17은 한 명에게 주는 호두과자 수, 나머지 1은 남는 호두과자 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#8','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',1,'sa','auto','어떤 수를 7로 나누었더니 몫이 4이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"어떤 수를 7로 나누었더니 몫이 4이고 나머지가 6이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["34"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","7 × 4 = 28, 28 + 6 = 34예요.","확인: 34 ÷ 7 = 4 … 6."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#9','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',2,'sa','auto','13 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"13 ÷ 4의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["나누는 수 4의 단에서 13보다 크지 않은 가장 큰 곱을 찾아요.","4 × 3 = 12 — 몫 3, 13 − 12 = 1이 남아요.","13 ÷ 4 = 3 … 1 — 나머지 1은 나누는 수 4보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#10','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',2,'sa','auto','13 ÷ 4 = 3 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"13 ÷ 4 = 3 … 1을 확인하는 식이에요. ?에 알맞은 수를 쓰세요.","answer":["13"],"explanation":["나누는 수 × 몫 = 4 × 3 = 12예요.","여기에 나머지 1을 더하면 13이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["4 × 3","=","12"],["12 + 1","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#11','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',2,'sa','auto','438 ÷ 9의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"438 ÷ 9의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["8"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 4는 9보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 43으로 보고 43 ÷ 9 → 몫 4, 7 남음 · 남은 7을 내려 78 ÷ 9 → 몫 8.","438 ÷ 9 = 48 … 6 — 몫의 일의 자리 숫자는 8이에요."],"asset":{"type":"ldiv","a":438,"b":9,"hide":[["q",2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#12','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',2,'mc','auto','902 ÷ 3의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":12,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"902 ÷ 3의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 2는 3으로 나눌 수 없어 몫 0.","몫 300 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":902,"b":3,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#13','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],false,'{"seq":13,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"25 ÷ 4","mis":"M3-2-u2-X07"},{"t":"35 ÷ 6","mis":"M3-2-u2-X07"},{"t":"16 ÷ 3","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","24 ÷ 4 = 6이에요 — 나머지가 0이에요.","나머지는 25 ÷ 4 → 1, 35 ÷ 6 → 5, 16 ÷ 3 → 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#14','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C3',2,'sa','auto','96 ÷ 3을 90과 6으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"96 ÷ 3을 90과 6으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["96을 90과 6으로 갈라요 — 둘 다 3으로 나누어떨어져요.","90 ÷ 3 = 30, 6 ÷ 3 = 2예요.","30 + 2 = 32 — 96 ÷ 3의 몫이에요."],"asset":{"type":"expr_grid","rows":[["90 ÷ 3","=","30"],["6 ÷ 3","=","2"],["30 + 2","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#15','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',2,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 4개를 만들려고 해요. 열쇠고리 한 개에 검은색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["171"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 687 ÷ 4.","백의 자리 6 ÷ 4 → 몫 1, 2 남음 · 남은 2를 내려 28 ÷ 4 → 몫 7 · 일의 자리 7 ÷ 4 → 몫 1.","687 ÷ 4 = 171 … 3 — 한 개에 171개씩, 3개가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#16','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C2',2,'sa','auto','공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심으려고 해요. 화단 한 개에 금잔화를 몇 포기씩 심어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"공원을 가꾸기 위해 금잔화 30포기를 화단 2개에 똑같이 나누어 심으려고 해요. 화단 한 개에 금잔화를 몇 포기씩 심어야 하나요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 금잔화 수를 화단 수로 나누어요 — 식은 30 ÷ 2.","십의 자리 3 ÷ 2 → 몫 1, 1 남음 · 남은 1을 내려 10 ÷ 2 → 몫 5.","30 ÷ 2 = 15 — 몫 15는 화단 한 개에 심는 금잔화 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#17','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C5',3,'mc','auto','소율이네 반 학생들이 환경 봉사 활동에서 페트병 57개를 수레에 똑같이 나누어 3번 옮기고, 유리병 72개를 수레에 똑같이 나누어 4번 옮겼어요. 한 번 나를 때 수레에 더 많이 실은 병은 무엇인가요?',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":17,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"소율이네 반 학생들이 환경 봉사 활동에서 페트병 57개를 수레에 똑같이 나누어 3번 옮기고, 유리병 72개를 수레에 똑같이 나누어 4번 옮겼어요. 한 번 나를 때 수레에 더 많이 실은 병은 무엇인가요?","options":[{"t":"페트병","correct":true},{"t":"유리병","mis":"M3-2-u2-X17"},{"t":"똑같아요","mis":"M3-2-u2-X15"}],"explanation":["페트병은 57 ÷ 3 = 19 — 한 번에 19개씩 옮겼어요.","유리병은 72 ÷ 4 = 18 — 한 번에 18개씩 옮겼어요.","19개가 18개보다 많아요 — 더 많이 실은 병은 페트병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#18','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',3,'mc','auto','3장의 수 카드 5, 7, 8을 한 번씩만 사용하여 (두 자리 수) ÷ (한 자리 수)의 나눗셈을 만들려고 해요. 몫이 가장 클 때의 몫과 나머지는 각각 얼마인가요?',ARRAY['M3-2-u2-X16','M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":18,"concept":"M3-2-u2-C7","difficulty":3,"kind":"mc","stem":"3장의 수 카드 5, 7, 8을 한 번씩만 사용하여 (두 자리 수) ÷ (한 자리 수)의 나눗셈을 만들려고 해요. 몫이 가장 클 때의 몫과 나머지는 각각 얼마인가요?","options":[{"t":"몫 17, 나머지 2","correct":true},{"t":"몫 15, 나머지 3","mis":"M3-2-u2-X16"},{"t":"몫 9, 나머지 3","mis":"M3-2-u2-X17"},{"t":"몫 12, 나머지 1","mis":"M3-2-u2-X15"}],"explanation":["몫이 가장 크려면 나누어지는 수는 가장 크게, 나누는 수는 가장 작게 해요.","가장 큰 두 자리 수는 87, 가장 작은 한 자리 수는 5예요.","87 ÷ 5 = 17 … 2 — 몫 17, 나머지 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#19','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C8',3,'ox','auto','409 ÷ 4 = 120 … 1이에요.',ARRAY['M3-2-u2-X11']::text[],false,'{"seq":19,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"409 ÷ 4 = 120 … 1이에요.","answer":"X","reason_options":[{"t":"몫의 0은 나눌 수 없는 그 자리에 써야 해서","correct":true},{"t":"0은 끝에 붙이면 되어서","mis":"M3-2-u2-X11"}],"mis":"M3-2-u2-X11","explanation":["백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2.","바르게 계산하면 409 ÷ 4 = 102 … 1.","0은 그 자리에 — 확인: 4 × 102 + 1 = 409예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#20','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C9',3,'ox','auto','257 ÷ 4 = 63 … 5예요.',ARRAY['M3-2-u2-X05']::text[],false,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"257 ÷ 4 = 63 … 5예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 4 → 몫 4.","바르게 계산하면 257 ÷ 4 = 64 … 1.","나머지 < 나누는 수 — 확인: 4 × 64 + 1 = 257이에요."],"asset":{"type":"ldiv","a":257,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#21','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',3,'sa','auto','매실 76개를 6명에게 똑같이 나누어 주려고 해요. 매실을 몇 개 더 가져와서 남는 매실 없이 6명에게 똑같이 나누어 주려면, 적어도 몇 개를 더 가져와야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"매실 76개를 6명에게 똑같이 나누어 주려고 해요. 매실을 몇 개 더 가져와서 남는 매실 없이 6명에게 똑같이 나누어 주려면, 적어도 몇 개를 더 가져와야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["76 ÷ 6 = 12 … 4 — 한 명에게 12개씩 주고 4개가 남아요.","남은 4개에 2개를 더하면 6개 — 6명에게 1개씩 더 줄 수 있어요.","6 − 4 = 2 — 적어도 2개를 더 가져와야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#22','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C6',3,'mc','auto','어떤 두 자리 수를 4로 나누려고 해요. 0, 1, 2, 3, 4, 5 가운데 나머지가 될 수 없는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X18','M3-2-u2-X17']::text[],false,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"mc","stem":"어떤 두 자리 수를 4로 나누려고 해요. 0, 1, 2, 3, 4, 5 가운데 나머지가 될 수 없는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"4, 5","correct":true},{"t":"5","mis":"M3-2-u2-X05"},{"t":"0, 4, 5","mis":"M3-2-u2-X18"},{"t":"1, 2, 3","mis":"M3-2-u2-X17"}],"explanation":["나머지는 나누는 수 4보다 작아야 해요.","나머지가 될 수 있는 수는 0, 1, 2, 3이에요.","4가 남으면 4씩 한 묶음을 더 만들 수 있어요 — 4와 5는 나머지가 될 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#23','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C7',4,'essay','teacher','노인 복지관에서 곶감을 주셨어요. 접시 8개에 똑같이 6개씩 놓았더니 2개가 남았어요. 곶감은 모두 몇 개인지 구하고, 나눗셈의 계산 결과가 맞는지 확인하는 방법과 연결하여 설명해 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"노인 복지관에서 곶감을 주셨어요. 접시 8개에 똑같이 6개씩 놓았더니 2개가 남았어요. 곶감은 모두 몇 개인지 구하고, 나눗셈의 계산 결과가 맞는지 확인하는 방법과 연결하여 설명해 보세요.","answer_guide":{"answer":"예: 접시 8개에 6개씩 놓았으므로 8 × 6 = 48개이고, 남은 2개를 더하면 48 + 2 = 50개이다. 곶감 수를 □라 하면 □ ÷ 8 = 6 … 2이므로 나누는 수와 몫의 곱에 나머지를 더한 50이 나누어지는 수이다.","scoring_points":["8 × 6 = 48을 구했는가","남은 2개를 더해 50개를 구했는가","나누는 수 × 몫 + 나머지와 연결해 설명했는가"]},"explanation":["8 × 6 = 48 — 접시에 놓은 곶감이에요.","48 + 2 = 50 — 남은 2개까지 더해요.","50 ÷ 8 = 6 … 2 — 확인하는 방법과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#24','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C10',4,'sa','auto','민서네 모둠은 전체 36쪽인 책을 4주 동안 월요일과 목요일에 읽기로 했어요(모두 8일). 하루에 읽는 쪽수는 똑같이 하고, 마지막 날에는 남은 쪽수도 모두 읽어요. 마지막 날에는 몇 쪽을 읽어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u2-C10","difficulty":4,"kind":"sa","stem":"민서네 모둠은 전체 36쪽인 책을 4주 동안 월요일과 목요일에 읽기로 했어요(모두 8일). 하루에 읽는 쪽수는 똑같이 하고, 마지막 날에는 남은 쪽수도 모두 읽어요. 마지막 날에는 몇 쪽을 읽어야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["36 ÷ 8 = 4 … 4 — 하루에 4쪽씩 읽고 4쪽이 남아요.","마지막 날에는 4쪽에 남은 4쪽을 더해 4 + 4 = 8쪽을 읽어요.","확인: 8 × 4 + 4 = 36."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_a#25','math',3,2,'u2','','tb_g3_2_math_u2_review_a','unit_review','M3-2-u2-C3',4,'essay','teacher','단원 핵심 질문 「나누어지는 수가 커지면 나눗셈은 어떻게 할까요?」에 답해 보세요. 배지 96개를 3묶음으로 똑같이 나누는 것을 예로 들어 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C3","difficulty":4,"kind":"essay","stem":"단원 핵심 질문 「나누어지는 수가 커지면 나눗셈은 어떻게 할까요?」에 답해 보세요. 배지 96개를 3묶음으로 똑같이 나누는 것을 예로 들어 설명해 보세요.","answer_guide":{"answer":"예: 나누어지는 수의 높은 자리부터 나누고, 남는 수가 있으면 아래 자리와 함께 다시 나눈다. 96을 90과 6으로 나누어 90 ÷ 3 = 30, 6 ÷ 3 = 2를 더하면 32이므로 한 묶음에 32개씩이다. 더 이상 나눌 수 없을 때 남는 것은 나머지이다.","scoring_points":["높은 자리부터 나눈다고 했는가","96 ÷ 3 = 32를 구했는가","남는 수는 다시 나누거나 나머지가 된다고 썼는가"]},"explanation":["90 ÷ 3 = 30, 6 ÷ 3 = 2.","30 + 2 = 32 — 96 ÷ 3 = 32.","앞자리부터 나누고, 남으면 다시 나누고, 끝에 남는 것이 나머지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#1','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C1',1,'sa','auto','80 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"80 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["80은 10 카드 8장 — 8 ÷ 4 = 2예요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","80 ÷ 4 = 20 — 확인: 4 × 20 = 80이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#2','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C3',1,'sa','auto','62 ÷ 2는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"62 ÷ 2는 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 6 ÷ 2 → 몫 3 · 일의 자리 2 ÷ 2 → 몫 1.","62 ÷ 2 = 31 — 확인: 2 × 31 = 62예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#3','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C5',1,'sa','auto','계산해 보세요. 96 ÷ 6을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"계산해 보세요. 96 ÷ 6을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 36 ÷ 6 → 몫 6.","96 ÷ 6 = 16 — 확인: 6 × 16 = 96이에요."],"asset":{"type":"ldiv","a":96,"b":6,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#4','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',1,'mc','auto','902 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":1,"kind":"mc","stem":"902 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"300 … 2","correct":true},{"t":"299 … 5","mis":"M3-2-u2-X05"},{"t":"2 … 300","mis":"M3-2-u2-X06"},{"t":"300","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 9 ÷ 3 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 2는 3으로 나눌 수 없어 몫 0.","902 ÷ 3 = 300 … 2 — 확인: 3 × 300 + 2 = 902예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#5','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C3',1,'mc','auto','몫이 가장 큰 것은 어느 것인가요? 70 ÷ 5, 50 ÷ 2, 60 ÷ 4',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요? 70 ÷ 5, 50 ÷ 2, 60 ÷ 4","options":[{"t":"50 ÷ 2","correct":true},{"t":"70 ÷ 5","mis":"M3-2-u2-X15"},{"t":"60 ÷ 4","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","70 ÷ 5 = 14, 50 ÷ 2 = 25, 60 ÷ 4 = 15.","몫이 가장 큰 것은 50 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#6','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C4',1,'mc','auto','배지 26개를 한 명에게 2개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있는지 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X16','M3-2-u2-X17']::text[],false,'{"seq":6,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"배지 26개를 한 명에게 2개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있는지 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"약 15명, 13명","correct":true},{"t":"약 15명, 31명","mis":"M3-2-u2-X04"},{"t":"약 30명, 13명","mis":"M3-2-u2-X16"},{"t":"약 13명, 15명","mis":"M3-2-u2-X17"}],"explanation":["26을 30으로 보면 30 ÷ 2 = 15 — 약 15명이에요.","실제로 계산하면 26 ÷ 2 = 13 — 13명이에요.","어림한 값과 실제 값이 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#7','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',1,'mc','auto','젤리 400개를 한 명에게 7개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요? 남는 젤리는 몇 개인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"젤리 400개를 한 명에게 7개씩 나누어 주려고 해요. 몇 명에게 나누어 줄 수 있나요? 남는 젤리는 몇 개인가요?","options":[{"t":"57명에게 나누어 주고, 1개가 남아요","correct":true},{"t":"56명에게 나누어 주고, 8개가 남아요","mis":"M3-2-u2-X05"},{"t":"1명에게 나누어 주고, 57개가 남아요","mis":"M3-2-u2-X06"},{"t":"57명에게 나누어 주고, 0개가 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 젤리 수를 한 명에게 주는 젤리 수로 나누어요 — 식은 400 ÷ 7.","백의 자리 4는 7보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 40으로 보고 40 ÷ 7 → 몫 5, 5 남음 · 남은 5를 내려 50 ÷ 7 → 몫 7.","400 ÷ 7 = 57 … 1 — 몫 57은 젤리를 받는 사람 수, 나머지 1은 남는 젤리 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#8','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',1,'sa','auto','어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"어떤 수를 7로 나누었더니 몫이 13이고 나머지가 4가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","7 × 13 = 91, 91 + 4 = 95예요.","확인: 95 ÷ 7 = 13 … 4."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#9','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',2,'sa','auto','25 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"25 ÷ 4의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["나누는 수 4의 단에서 25보다 크지 않은 가장 큰 곱을 찾아요.","4 × 6 = 24 — 몫 6, 25 − 24 = 1이 남아요.","25 ÷ 4 = 6 … 1 — 나머지 1은 나누는 수 4보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#10','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',2,'sa','auto','44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"44 ÷ 3 = 14 … 2를 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["나누는 수 × 몫 = 3 × 14 = 42예요.","여기에 나머지 2를 더하면 44예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["3 × 14","=",null],["□ + 2","=","44"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#11','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',2,'sa','auto','258 ÷ 4의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"258 ÷ 4의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["6"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 2는 4보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 4 → 몫 6, 1 남음 · 남은 1을 내려 18 ÷ 4 → 몫 4.","258 ÷ 4 = 64 … 2 — 몫의 십의 자리 숫자는 6이에요."],"asset":{"type":"ldiv","a":258,"b":4,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#12','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',2,'mc','auto','307 ÷ 3의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":12,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"307 ÷ 3의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","몫 102 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":307,"b":3,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#13','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],false,'{"seq":13,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"16 ÷ 2","correct":true},{"t":"17 ÷ 6","mis":"M3-2-u2-X07"},{"t":"32 ÷ 5","mis":"M3-2-u2-X07"},{"t":"44 ÷ 9","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","16 ÷ 2 = 8이에요 — 나머지가 0이에요.","나머지는 17 ÷ 6 → 5, 32 ÷ 5 → 2, 44 ÷ 9 → 8."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#14','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C3',2,'sa','auto','26 ÷ 2를 20과 6으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"26 ÷ 2를 20과 6으로 갈라 나누었어요. ?에 알맞은 수를 쓰세요.","answer":["13"],"explanation":["26을 20과 6으로 갈라요 — 둘 다 2로 나누어떨어져요.","20 ÷ 2 = 10, 6 ÷ 2 = 3이에요.","10 + 3 = 13 — 26 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["20 ÷ 2","=","10"],["6 ÷ 2","=","3"],["10 + 3","=",null]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#15','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',2,'sa','auto','정후가 흰색 블록 112개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"정후가 흰색 블록 112개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 흰색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["37"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 112 ÷ 3.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 11로 보고 11 ÷ 3 → 몫 3, 2 남음 · 남은 2를 내려 22 ÷ 3 → 몫 7.","112 ÷ 3 = 37 … 1 — 한 개에 37개씩, 1개가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#16','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C2',2,'sa','auto','붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 붙임딱지를 한 명에게 몇 장씩 나누어 줄 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"붙임딱지 80장을 5명에게 똑같이 나누어 주려고 해요. 붙임딱지를 한 명에게 몇 장씩 나누어 줄 수 있나요? 숫자로 쓰세요.","answer":["16"],"explanation":["전체 붙임딱지 수를 사람 수로 나누어요 — 식은 80 ÷ 5.","십의 자리 8 ÷ 5 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 5 → 몫 6.","80 ÷ 5 = 16 — 몫 16은 한 명이 받는 붙임딱지 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#17','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C5',3,'mc','auto','정후는 파란색 구슬 65개, 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이를 5개 만들어요. 목걸이 한 개에 더 많이 사용하는 구슬은 어느 것인가요?',ARRAY['M3-2-u2-X17','M3-2-u2-X15']::text[],false,'{"seq":17,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"정후는 파란색 구슬 65개, 빨간색 구슬 85개를 모두 사용하여 똑같은 목걸이를 5개 만들어요. 목걸이 한 개에 더 많이 사용하는 구슬은 어느 것인가요?","options":[{"t":"빨간색 구슬","correct":true},{"t":"파란색 구슬","mis":"M3-2-u2-X17"},{"t":"똑같아요","mis":"M3-2-u2-X15"}],"explanation":["파란색 65 ÷ 5 = 13 — 한 개에 13개.","빨간색 85 ÷ 5 = 17 — 한 개에 17개.","17개가 13개보다 많아요 — 빨간색 구슬을 더 많이 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#18','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',3,'mc','auto','3장의 수 카드 5, 7, 8을 한 번씩만 사용하여 (두 자리 수) ÷ (한 자리 수)의 나눗셈을 만들려고 해요. 몫이 가장 작을 때의 몫과 나머지는 각각 얼마인가요?',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":18,"concept":"M3-2-u2-C7","difficulty":3,"kind":"mc","stem":"3장의 수 카드 5, 7, 8을 한 번씩만 사용하여 (두 자리 수) ÷ (한 자리 수)의 나눗셈을 만들려고 해요. 몫이 가장 작을 때의 몫과 나머지는 각각 얼마인가요?","options":[{"t":"몫 7, 나머지 1","correct":true},{"t":"몫 8, 나머지 2","mis":"M3-2-u2-X15"},{"t":"몫 17, 나머지 2","mis":"M3-2-u2-X17"},{"t":"몫 9, 나머지 3","mis":"M3-2-u2-X15"}],"explanation":["몫이 가장 작으려면 나누어지는 수는 가장 작게, 나누는 수는 가장 크게 해요.","가장 작은 두 자리 수는 57, 가장 큰 한 자리 수는 8이에요.","57 ÷ 8 = 7 … 1 — 몫 7, 나머지 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#19','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',3,'ox','auto','615 ÷ 6 = 120 … 3이에요.',ARRAY['M3-2-u2-X11']::text[],false,'{"seq":19,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"615 ÷ 6 = 120 … 3이에요.","answer":"X","reason_options":[{"t":"몫의 0은 나눌 수 없는 그 자리에 써야 해서","correct":true},{"t":"0은 끝에 붙이면 되어서","mis":"M3-2-u2-X11"}],"mis":"M3-2-u2-X11","explanation":["백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 1은 6으로 나눌 수 없어 몫 0, 1 남음 · 남은 1을 내려 15 ÷ 6 → 몫 2.","바르게 계산하면 615 ÷ 6 = 102 … 3.","0은 그 자리에 — 확인: 6 × 102 + 3 = 615예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#20','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C9',3,'ox','auto','73 ÷ 3 = 23 … 4예요.',ARRAY['M3-2-u2-X05']::text[],false,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"73 ÷ 3 = 23 … 4예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["십의 자리 7 ÷ 3 → 몫 2, 1 남음 · 남은 1을 내려 13 ÷ 3 → 몫 4.","바르게 계산하면 73 ÷ 3 = 24 … 1.","나머지 < 나누는 수 — 확인: 3 × 24 + 1 = 73이에요."],"asset":{"type":"ldiv","a":73,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#21','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',3,'sa','auto','태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"태민이 흰색 블록 341개로 똑같은 열쇠고리 4개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 흰색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["341 ÷ 4 = 85 … 1 — 한 개에 85개씩 쓰고 1개가 남아요.","한 개에 86개씩 쓰려면 4 × 86 = 344개가 필요해요.","344 − 341 = 3 — 적어도 3개 더 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#22','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C6',3,'sa','auto','다음 나눗셈의 나머지가 2일 때 □ 안에 알맞은 수를 쓰세요. 5□ ÷ 9','{}'::text[],false,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"sa","stem":"다음 나눗셈의 나머지가 2일 때 □ 안에 알맞은 수를 쓰세요. 5□ ÷ 9","answer":["6"],"explanation":["9의 단에서 50과 59 사이에 있는 곱은 9 × 6 = 54예요.","나머지가 2가 되려면 54 + 2 = 56이어야 해요.","56 ÷ 9 = 6 … 2 — □는 6이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#23','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C7',4,'essay','teacher','999 ÷ 8을 세로셈으로 계산하고, 계산 결과가 맞는지 확인하는 방법까지 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u2-C7","difficulty":4,"kind":"essay","stem":"999 ÷ 8을 세로셈으로 계산하고, 계산 결과가 맞는지 확인하는 방법까지 써 보세요.","answer_guide":{"answer":"예: 백의 자리 9를 8로 나누면 몫 1, 1이 남는다. 남은 1과 십의 자리 9를 합친 19를 8로 나누면 몫 2, 3이 남는다. 남은 3과 일의 자리 9를 합친 39를 8로 나누면 몫 4, 7이 남는다. 999 ÷ 8 = 124 … 7이다. 확인: 8 × 124 = 992, 992 + 7 = 999.","scoring_points":["자리마다 남은 수를 내려 나누었는가","999 ÷ 8 = 124 … 7을 구했는가","8 × 124 + 7 = 999로 확인했는가"]},"explanation":["9 ÷ 8 → 1, 1 남음 · 19 ÷ 8 → 2, 3 남음 · 39 ÷ 8 → 4, 7 남음.","999 ÷ 8 = 124 … 7.","8 × 124 + 7 = 999."],"asset":{"type":"ldiv","a":999,"b":8,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#24','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C10',4,'sa','auto','민서네 모둠은 줄넘기를 하루에 120회씩 4주 동안 8번 하기로 했어요. 모두 960회예요. 960회를 8번에 똑같이 나누면 한 번에 몇 회인지 나눗셈으로 확인해 보세요. 960 ÷ 8은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u2-C10","difficulty":4,"kind":"sa","stem":"민서네 모둠은 줄넘기를 하루에 120회씩 4주 동안 8번 하기로 했어요. 모두 960회예요. 960회를 8번에 똑같이 나누면 한 번에 몇 회인지 나눗셈으로 확인해 보세요. 960 ÷ 8은 얼마인가요? 숫자로 쓰세요.","answer":["120"],"explanation":["120 × 8 = 960이에요.","곱셈과 나눗셈의 관계로 960 ÷ 8 = 120으로 바꿀 수 있어요.","960 ÷ 8 = 120 — 계산이 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_b#25','math',3,2,'u2','','tb_g3_2_math_u2_review_b','unit_review','M3-2-u2-C8',4,'essay','teacher','친구가 418 ÷ 4를 계산하면서 「십의 자리 1은 4보다 작으니까 4 ÷ 1 = 4」라고 하여 몫을 142라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C8","difficulty":4,"kind":"essay","stem":"친구가 418 ÷ 4를 계산하면서 「십의 자리 1은 4보다 작으니까 4 ÷ 1 = 4」라고 하여 몫을 142라고 썼어요. 무엇이 잘못되었는지 설명하고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 나누는 수 4를 자리 숫자 1로 거꾸로 나누었다. 십의 자리 1은 4로 나눌 수 없으므로 몫의 십의 자리에 0을 쓰고, 1과 일의 자리 8을 합친 18을 4로 나누어야 한다. 418 ÷ 4 = 104 … 2이고, 확인하면 4 × 104 + 2 = 418이다.","scoring_points":["거꾸로 나눈 잘못을 찾았는가","몫의 십의 자리에 0을 쓰고 18을 나누었는가","104 … 2를 구하고 확인했는가"]},"explanation":["자리 숫자 ÷ 나누는 수 — 1은 4로 나눌 수 없어 몫 0.","18 ÷ 4 = 4 … 2 — 418 ÷ 4 = 104 … 2.","4 × 104 + 2 = 418."],"asset":{"type":"ldiv","a":418,"b":4,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#1','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C1',1,'sa','auto','90 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"90 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["90은 10 카드 9장 — 9 ÷ 3 = 3이에요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","90 ÷ 3 = 30 — 확인: 3 × 30 = 90이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#2','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C3',1,'sa','auto','84 ÷ 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"84 ÷ 4는 얼마인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 4 → 몫 2 · 일의 자리 4 ÷ 4 → 몫 1.","84 ÷ 4 = 21 — 확인: 4 × 21 = 84예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#3','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C5',1,'sa','auto','계산해 보세요. 45 ÷ 3을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"계산해 보세요. 45 ÷ 3을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 4 ÷ 3 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 3 → 몫 5.","45 ÷ 3 = 15 — 확인: 3 × 15 = 45예요."],"asset":{"type":"ldiv","a":45,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#4','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',1,'mc','auto','638 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":1,"kind":"mc","stem":"638 ÷ 3의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"212 … 2","correct":true},{"t":"211 … 5","mis":"M3-2-u2-X05"},{"t":"2 … 212","mis":"M3-2-u2-X06"},{"t":"212","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 3 → 몫 2 · 십의 자리 3 ÷ 3 → 몫 1 · 일의 자리 8 ÷ 3 → 몫 2.","638 ÷ 3 = 212 … 2 — 확인: 3 × 212 + 2 = 638이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#5','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C3',1,'mc','auto','몫이 가장 큰 것은 어느 것인가요? 34 ÷ 2, 72 ÷ 6, 91 ÷ 7, 64 ÷ 4',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요? 34 ÷ 2, 72 ÷ 6, 91 ÷ 7, 64 ÷ 4","options":[{"t":"34 ÷ 2","correct":true},{"t":"72 ÷ 6","mis":"M3-2-u2-X15"},{"t":"91 ÷ 7","mis":"M3-2-u2-X15"},{"t":"64 ÷ 4","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","34 ÷ 2 = 17, 72 ÷ 6 = 12, 91 ÷ 7 = 13, 64 ÷ 4 = 16.","몫이 가장 큰 것은 34 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#6','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C4',1,'mc','auto','책 526권을 5권씩 봉투에 담으려고 해요. 필요한 봉투 수를 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X10','M3-2-u2-X16','M3-2-u2-X17']::text[],false,'{"seq":6,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"책 526권을 5권씩 봉투에 담으려고 해요. 필요한 봉투 수를 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"약 100장, 105장","correct":true},{"t":"약 100장, 15장","mis":"M3-2-u2-X10"},{"t":"약 50장, 105장","mis":"M3-2-u2-X16"},{"t":"약 105장, 100장","mis":"M3-2-u2-X17"}],"explanation":["526을 500으로 보면 500 ÷ 5 = 100 — 약 100장이에요.","실제로 계산하면 526 ÷ 5 = 105 … 1 — 105장이 필요하고 1권이 남아요.","어림한 값과 실제 값이 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#7','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',1,'mc','auto','공공 도서관에서 책 256권을 3권씩 봉투에 담아 각 가정으로 보내려고 해요. 봉투는 몇 장 필요한가요? 남는 책은 몇 권인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"공공 도서관에서 책 256권을 3권씩 봉투에 담아 각 가정으로 보내려고 해요. 봉투는 몇 장 필요한가요? 남는 책은 몇 권인가요?","options":[{"t":"봉투 85장, 책 1권이 남아요","correct":true},{"t":"봉투 84장, 책 4권이 남아요","mis":"M3-2-u2-X05"},{"t":"봉투 1장, 책 85권이 남아요","mis":"M3-2-u2-X06"},{"t":"봉투 85장, 책 0권이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 책 수를 봉투 한 장에 담는 책 수로 나누어요 — 식은 256 ÷ 3.","백의 자리 2는 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 25로 보고 25 ÷ 3 → 몫 8, 1 남음 · 남은 1을 내려 16 ÷ 3 → 몫 5.","256 ÷ 3 = 85 … 1 — 몫 85는 필요한 봉투 수, 나머지 1은 남는 책 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#8','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',1,'sa','auto','어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"어떤 수를 3으로 나누었더니 몫이 212이고 나머지가 2가 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["638"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","3 × 212 = 636, 636 + 2 = 638이에요.","확인: 638 ÷ 3 = 212 … 2."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#9','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',2,'sa','auto','60 ÷ 8의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"60 ÷ 8의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["나누는 수 8의 단에서 60보다 크지 않은 가장 큰 곱을 찾아요.","8 × 7 = 56 — 몫 7, 60 − 56 = 4가 남아요.","60 ÷ 8 = 7 … 4 — 나머지 4는 나누는 수 8보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#10','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',2,'sa','auto','99 ÷ 8 = 12 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"99 ÷ 8 = 12 … 3을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["96"],"explanation":["나누는 수 × 몫 = 8 × 12 = 96이에요.","여기에 나머지 3을 더하면 99예요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["8 × 12","=",null],["□ + 3","=","99"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#11','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',2,'sa','auto','197 ÷ 3의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"197 ÷ 3의 세로셈이에요. 몫의 일의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["5"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 1은 3보다 작아 아래 자리와 함께 봐요 · 십의 자리까지 19로 보고 19 ÷ 3 → 몫 6, 1 남음 · 남은 1을 내려 17 ÷ 3 → 몫 5.","197 ÷ 3 = 65 … 2 — 몫의 일의 자리 숫자는 5예요."],"asset":{"type":"ldiv","a":197,"b":3,"hide":[["q",2]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#12','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',2,'mc','auto','605 ÷ 2의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":12,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"605 ÷ 2의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 6 ÷ 2 → 몫 3 · 십의 자리 0 → 몫 0 · 일의 자리 5 ÷ 2 → 몫 2.","몫 302 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":605,"b":2,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#13','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],false,'{"seq":13,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"27 ÷ 3","correct":true},{"t":"32 ÷ 7","mis":"M3-2-u2-X07"},{"t":"37 ÷ 4","mis":"M3-2-u2-X07"},{"t":"33 ÷ 6","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","27 ÷ 3 = 9예요 — 나머지가 0이에요.","나머지는 32 ÷ 7 → 4, 37 ÷ 4 → 1, 33 ÷ 6 → 3."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#14','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C3',2,'sa','auto','84 ÷ 4를 80과 4로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"84 ÷ 4를 80과 4로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["20"],"explanation":["84를 80과 4로 갈라요 — 둘 다 4로 나누어떨어져요.","80 ÷ 4 = 20, 4 ÷ 4 = 1이에요.","20 + 1 = 21 — 84 ÷ 4의 몫이에요."],"asset":{"type":"expr_grid","rows":[["80 ÷ 4","=",null],["4 ÷ 4","=","1"],["□ + 1","=","21"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#15','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',2,'sa','auto','태민이 갈색 블록 92개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 갈색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"태민이 갈색 블록 92개로 똑같은 열쇠고리 5개를 만들려고 해요. 열쇠고리 한 개에 갈색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["18"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 92 ÷ 5.","십의 자리 9 ÷ 5 → 몫 1, 4 남음 · 남은 4를 내려 42 ÷ 5 → 몫 8.","92 ÷ 5 = 18 … 2 — 한 개에 18개씩, 2개가 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#16','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C2',2,'sa','auto','달걀 90개를 바구니 6개에 똑같이 나누어 담으려고 해요. 바구니 한 개에 달걀을 몇 개씩 담으면 되나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"달걀 90개를 바구니 6개에 똑같이 나누어 담으려고 해요. 바구니 한 개에 달걀을 몇 개씩 담으면 되나요? 숫자로 쓰세요.","answer":["15"],"explanation":["전체 달걀 수를 바구니 수로 나누어요 — 식은 90 ÷ 6.","십의 자리 9 ÷ 6 → 몫 1, 3 남음 · 남은 3을 내려 30 ÷ 6 → 몫 5.","90 ÷ 6 = 15 — 몫 15는 바구니 한 개에 담는 달걀 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#17','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C5',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 96 ÷ 6 ○ 32 ÷ 2',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":17,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 96 ÷ 6 ○ 32 ÷ 2","options":[{"t":"=","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"<","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["96 ÷ 6의 몫은 16이에요.","32 ÷ 2의 몫은 16이에요.","16 = 16 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#18','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C1',3,'mc','auto','수 카드 3, 4, 5, 9 가운데 2장을 골라 한 번씩만 사용하여 □0 ÷ □ = 30을 완성하려고 해요. 알맞은 나눗셈식은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X15']::text[],false,'{"seq":18,"concept":"M3-2-u2-C1","difficulty":3,"kind":"mc","stem":"수 카드 3, 4, 5, 9 가운데 2장을 골라 한 번씩만 사용하여 □0 ÷ □ = 30을 완성하려고 해요. 알맞은 나눗셈식은 어느 것인가요?","options":[{"t":"90 ÷ 3 = 30","correct":true},{"t":"30 ÷ 9 = 30","mis":"M3-2-u2-X20"},{"t":"90 ÷ 9 = 30","mis":"M3-2-u2-X15"},{"t":"40 ÷ 5 = 30","mis":"M3-2-u2-X15"}],"explanation":["몫이 30이 되려면 앞의 수를 뒤의 수로 나눈 몫이 3이어야 해요.","9 ÷ 3 = 3 — 그래서 90 ÷ 3 = 30이에요.","나누어지는 수가 10배 커지면 몫도 10배 커져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#19','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C8',3,'ox','auto','721 ÷ 7 = 13이에요.',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":19,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"721 ÷ 7 = 13이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 7 ÷ 7 → 몫 1 · 십의 자리 2는 7로 나눌 수 없어 몫 0, 2 남음 · 남은 2를 내려 21 ÷ 7 → 몫 3.","바르게 계산하면 721 ÷ 7 = 103.","나눌 수 없으면 몫에 0 — 확인: 7 × 103 = 721이에요."],"asset":{"type":"ldiv","a":721,"b":7,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#20','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',3,'ox','auto','367 ÷ 3 = 121 … 4예요.',ARRAY['M3-2-u2-X05']::text[],false,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"367 ÷ 3 = 121 … 4예요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 6 ÷ 3 → 몫 2 · 일의 자리 7 ÷ 3 → 몫 2.","바르게 계산하면 367 ÷ 3 = 122 … 1.","나머지 < 나누는 수 — 확인: 3 × 122 + 1 = 367이에요."],"asset":{"type":"ldiv","a":367,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#21','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C7',3,'sa','auto','정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 분홍색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"정후가 분홍색 블록 85개로 똑같은 열쇠고리 3개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 분홍색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["2"],"explanation":["85 ÷ 3 = 28 … 1 — 한 개에 28개씩 쓰고 1개가 남아요.","한 개에 29개씩 쓰려면 3 × 29 = 87개가 필요해요.","87 − 85 = 2 — 적어도 2개 더 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#22','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C9',3,'mc','auto','37□ ÷ 4는 나누어떨어지는 나눗셈이에요. 0부터 9까지의 수 가운데 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":22,"concept":"M3-2-u2-C9","difficulty":3,"kind":"mc","stem":"37□ ÷ 4는 나누어떨어지는 나눗셈이에요. 0부터 9까지의 수 가운데 □에 들어갈 수 있는 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2, 6","correct":true},{"t":"2","mis":"M3-2-u2-X15"},{"t":"0, 4, 8","mis":"M3-2-u2-X15"},{"t":"6","mis":"M3-2-u2-X15"}],"explanation":["백의 자리 3은 4보다 작아 37을 봐요 — 37 ÷ 4 = 9 … 1.","남은 1을 내리면 1□가 4로 나누어떨어져야 해요 — 12와 16.","그래서 □는 2와 6 — 372 ÷ 4 = 93, 376 ÷ 4 = 94예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#23','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C6',4,'essay','teacher','친구가 「나눗셈도 일의 자리부터 계산하면 안 되나요?」라고 물었어요. 28 ÷ 3을 일의 자리부터 계산하는 방법과 십의 자리부터 계산하는 방법으로 각각 구하고, 두 방법을 견주어 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"친구가 「나눗셈도 일의 자리부터 계산하면 안 되나요?」라고 물었어요. 28 ÷ 3을 일의 자리부터 계산하는 방법과 십의 자리부터 계산하는 방법으로 각각 구하고, 두 방법을 견주어 보세요.","answer_guide":{"answer":"예: 일의 자리부터 하면 8 ÷ 3 = 2 … 2이고, 십의 자리 20과 남은 2를 합친 22를 3으로 나누면 7 … 1이므로 몫은 2 + 7 = 9, 나머지는 1이다. 십의 자리부터 하면 28을 3으로 나누어 28 ÷ 3 = 9 … 1이다. 결과는 같지만 일의 자리부터 하면 단계가 더 많다.","scoring_points":["일의 자리부터 계산하여 9 … 1을 구했는가","십의 자리부터 계산하여 9 … 1을 구했는가","두 방법의 결과가 같고 단계 수가 다르다고 견주었는가"]},"explanation":["8 ÷ 3 = 2 … 2, 22 ÷ 3 = 7 … 1 — 몫 9, 나머지 1.","28 ÷ 3 = 9 … 1.","결과는 같지만 높은 자리부터 하면 더 간단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#24','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C10',4,'sa','auto','정후는 빨간색 80개, 초록색 50개, 노란색 100개, 회색 690개를 골라 똑같은 열쇠고리 3개를 만들었어요. 남는 블록은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M3-2-u2-C10","difficulty":4,"kind":"sa","stem":"정후는 빨간색 80개, 초록색 50개, 노란색 100개, 회색 690개를 골라 똑같은 열쇠고리 3개를 만들었어요. 남는 블록은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["빨간색 80 ÷ 3 = 26 … 2, 초록색 50 ÷ 3 = 16 … 2.","노란색 100 ÷ 3 = 33 … 1, 회색 690 ÷ 3 = 230.","남는 블록은 2 + 2 + 1 + 0 = 5 — 모두 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_c#25','math',3,2,'u2','','tb_g3_2_math_u2_review_c','unit_review','M3-2-u2-C5',4,'essay','teacher','소율이네 반 학생들이 페트병 57개를 수레에 똑같이 나누어 3번 옮기고, 유리병 72개를 수레에 똑같이 나누어 4번 옮겼어요. 페트병과 유리병 가운데 한 번 나를 때 수레에 더 많이 실은 병은 무엇인지 풀이 과정을 쓰고 답을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C5","difficulty":4,"kind":"essay","stem":"소율이네 반 학생들이 페트병 57개를 수레에 똑같이 나누어 3번 옮기고, 유리병 72개를 수레에 똑같이 나누어 4번 옮겼어요. 페트병과 유리병 가운데 한 번 나를 때 수레에 더 많이 실은 병은 무엇인지 풀이 과정을 쓰고 답을 구해 보세요.","answer_guide":{"answer":"예: 페트병은 57 ÷ 3 = 19(개)씩 옮겼고, 유리병은 72 ÷ 4 = 18(개)씩 옮겼으므로 한 번 나를 때 수레에 더 많이 실은 병은 페트병이다.","scoring_points":["57 ÷ 3 = 19를 구했는가","72 ÷ 4 = 18을 구했는가","페트병이라고 답했는가"]},"explanation":["페트병 57 ÷ 3 = 19.","유리병 72 ÷ 4 = 18.","19개가 18개보다 많아요 — 페트병."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#1','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C1',1,'sa','auto','70 ÷ 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"M3-2-u2-C1","difficulty":1,"kind":"sa","stem":"70 ÷ 7은 얼마인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["70은 10 카드 7장 — 7 ÷ 7 = 1이에요.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","70 ÷ 7 = 10 — 확인: 7 × 10 = 70이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#2','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C3',1,'sa','auto','93 ÷ 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"M3-2-u2-C3","difficulty":1,"kind":"sa","stem":"93 ÷ 3은 얼마인가요? 숫자로 쓰세요.","answer":["31"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 9 ÷ 3 → 몫 3 · 일의 자리 3 ÷ 3 → 몫 1.","93 ÷ 3 = 31 — 확인: 3 × 31 = 93이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#3','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C5',1,'sa','auto','계산해 보세요. 87 ÷ 3을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"M3-2-u2-C5","difficulty":1,"kind":"sa","stem":"계산해 보세요. 87 ÷ 3을 세로셈으로 계산하면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["29"],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 3 → 몫 2, 2 남음 · 남은 2를 내려 27 ÷ 3 → 몫 9.","87 ÷ 3 = 29 — 확인: 3 × 29 = 87이에요."],"asset":{"type":"ldiv","a":87,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#4','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',1,'mc','auto','669 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":4,"concept":"M3-2-u2-C8","difficulty":1,"kind":"mc","stem":"669 ÷ 6의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"111 … 3","correct":true},{"t":"110 … 9","mis":"M3-2-u2-X05"},{"t":"3 … 111","mis":"M3-2-u2-X06"},{"t":"111","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","백의 자리 6 ÷ 6 → 몫 1 · 십의 자리 6 ÷ 6 → 몫 1 · 일의 자리 9 ÷ 6 → 몫 1.","669 ÷ 6 = 111 … 3 — 확인: 6 × 111 + 3 = 669예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#5','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C3',1,'mc','auto','몫이 가장 큰 것은 어느 것인가요? 36 ÷ 3, 48 ÷ 2, 99 ÷ 9',ARRAY['M3-2-u2-X15']::text[],false,'{"seq":5,"concept":"M3-2-u2-C3","difficulty":1,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요? 36 ÷ 3, 48 ÷ 2, 99 ÷ 9","options":[{"t":"48 ÷ 2","correct":true},{"t":"36 ÷ 3","mis":"M3-2-u2-X15"},{"t":"99 ÷ 9","mis":"M3-2-u2-X15"}],"explanation":["하나씩 몫을 구해요.","36 ÷ 3 = 12, 48 ÷ 2 = 24, 99 ÷ 9 = 11.","몫이 가장 큰 것은 48 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#6','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C4',1,'mc','auto','지아가 485 ÷ 5의 몫을 어림했어요. 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?',ARRAY['M3-2-u2-X04','M3-2-u2-X16','M3-2-u2-X17']::text[],false,'{"seq":6,"concept":"M3-2-u2-C4","difficulty":1,"kind":"mc","stem":"지아가 485 ÷ 5의 몫을 어림했어요. 어림한 값과 실제로 계산한 값을 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"약 100, 97","correct":true},{"t":"약 100, 79","mis":"M3-2-u2-X04"},{"t":"약 10, 97","mis":"M3-2-u2-X16"},{"t":"약 97, 100","mis":"M3-2-u2-X17"}],"explanation":["485를 500으로 보면 500 ÷ 5 = 100 — 약 100이에요.","실제로 계산하면 485 ÷ 5 = 97이에요.","어림한 값과 실제 값의 차는 3이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#7','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',1,'mc','auto','색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 한 명이 색종이를 몇 장씩 가질 수 있나요? 남는 색종이는 몇 장인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":7,"concept":"M3-2-u2-C10","difficulty":1,"kind":"mc","stem":"색종이 409장을 4명이 똑같이 나누어 가지려고 해요. 한 명이 색종이를 몇 장씩 가질 수 있나요? 남는 색종이는 몇 장인가요?","options":[{"t":"한 명이 102장씩 가지고, 1장이 남아요","correct":true},{"t":"한 명이 101장씩 가지고, 5장이 남아요","mis":"M3-2-u2-X05"},{"t":"한 명이 1장씩 가지고, 102장이 남아요","mis":"M3-2-u2-X06"},{"t":"한 명이 102장씩 가지고, 0장이 남아요","mis":"M3-2-u2-X07"}],"explanation":["전체 색종이 수를 사람 수로 나누어요 — 식은 409 ÷ 4.","백의 자리 4 ÷ 4 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 9 ÷ 4 → 몫 2.","409 ÷ 4 = 102 … 1 — 몫 102는 한 명이 가지는 색종이 수, 나머지 1은 남는 색종이 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#8','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',1,'sa','auto','어떤 수를 4로 나누었더니 몫이 13이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M3-2-u2-C7","difficulty":1,"kind":"sa","stem":"어떤 수를 4로 나누었더니 몫이 13이고 나머지가 1이 되었어요. 어떤 수는 얼마인가요? 숫자로 쓰세요.","answer":["53"],"explanation":["어떤 수는 나누어지는 수 — 나누는 수 × 몫 + 나머지예요.","4 × 13 = 52, 52 + 1 = 53이에요.","확인: 53 ÷ 4 = 13 … 1."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#9','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',2,'sa','auto','45 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"M3-2-u2-C6","difficulty":2,"kind":"sa","stem":"45 ÷ 6의 나머지는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["나누는 수 6의 단에서 45보다 크지 않은 가장 큰 곱을 찾아요.","6 × 7 = 42 — 몫 7, 45 − 42 = 3이 남아요.","45 ÷ 6 = 7 … 3 — 나머지 3은 나누는 수 6보다 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#10','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',2,'sa','auto','57 ÷ 2 = 28 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M3-2-u2-C7","difficulty":2,"kind":"sa","stem":"57 ÷ 2 = 28 … 1을 확인하는 식이에요. □에 알맞은 수를 쓰세요.","answer":["56"],"explanation":["나누는 수 × 몫 = 2 × 28 = 56이에요.","여기에 나머지 1을 더하면 57이에요.","나누어지는 수와 같으면 바르게 계산한 거예요."],"asset":{"type":"expr_grid","rows":[["2 × 28","=",null],["□ + 1","=","57"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#11','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',2,'sa','auto','999 ÷ 8의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.','{}'::text[],false,'{"seq":11,"concept":"M3-2-u2-C9","difficulty":2,"kind":"sa","stem":"999 ÷ 8의 세로셈이에요. 몫의 십의 자리 ?에 알맞은 숫자를 쓰세요.","answer":["2"],"explanation":["몫은 나누어지는 수의 자리에 맞추어 그 자리 위에 써요.","백의 자리 9 ÷ 8 → 몫 1, 1 남음 · 남은 1을 내려 19 ÷ 8 → 몫 2, 3 남음 · 남은 3을 내려 39 ÷ 8 → 몫 4.","999 ÷ 8 = 124 … 7 — 몫의 십의 자리 숫자는 2예요."],"asset":{"type":"ldiv","a":999,"b":8,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#12','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',2,'mc','auto','808 ÷ 8의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":12,"concept":"M3-2-u2-C8","difficulty":2,"kind":"mc","stem":"808 ÷ 8의 몫을 세로셈으로 쓸 때 몫의 십의 자리에 써야 하는 숫자는 어느 것인가요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M3-2-u2-X10"},{"t":"2","mis":"M3-2-u2-X10"},{"t":"3","mis":"M3-2-u2-X10"}],"explanation":["높은 자리부터 차례로 나누어요.","백의 자리 8 ÷ 8 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 8 ÷ 8 → 몫 1.","몫 101 — 십의 자리 숫자는 0이에요."],"asset":{"type":"ldiv","a":808,"b":8,"hide":[["q",1]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#13','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',2,'mc','auto','나누어떨어지는 나눗셈은 어느 것인가요?',ARRAY['M3-2-u2-X07']::text[],false,'{"seq":13,"concept":"M3-2-u2-C6","difficulty":2,"kind":"mc","stem":"나누어떨어지는 나눗셈은 어느 것인가요?","options":[{"t":"54 ÷ 9","correct":true},{"t":"50 ÷ 9","mis":"M3-2-u2-X07"},{"t":"55 ÷ 9","mis":"M3-2-u2-X07"},{"t":"53 ÷ 9","mis":"M3-2-u2-X07"}],"explanation":["나머지가 0일 때 나누어떨어진다고 해요.","54 ÷ 9 = 6이에요 — 나머지가 0이에요.","나머지는 50 ÷ 9 → 5, 55 ÷ 9 → 1, 53 ÷ 9 → 8."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#14','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C3',2,'sa','auto','68 ÷ 2를 60과 8로 갈라 나누었어요. □에 알맞은 수를 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M3-2-u2-C3","difficulty":2,"kind":"sa","stem":"68 ÷ 2를 60과 8로 갈라 나누었어요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["68을 60과 8로 갈라요 — 둘 다 2로 나누어떨어져요.","60 ÷ 2 = 30, 8 ÷ 2 = 4예요.","30 + 4 = 34 — 68 ÷ 2의 몫이에요."],"asset":{"type":"expr_grid","rows":[["60 ÷ 2","=","30"],["8 ÷ 2","=",null],["30 + □","=","34"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#15','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',2,'sa','auto','정후가 파란색 블록 60개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 파란색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":15,"concept":"M3-2-u2-C10","difficulty":2,"kind":"sa","stem":"정후가 파란색 블록 60개로 똑같은 열쇠고리 3개를 만들려고 해요. 열쇠고리 한 개에 파란색 블록을 몇 개까지 사용할 수 있나요? 숫자로 쓰세요.","answer":["20"],"explanation":["블록 수 ÷ 열쇠고리 수 — 식은 60 ÷ 3.","나누어지는 수가 10배 커지면 몫도 10배 커져요.","60 ÷ 3 = 20 — 한 개에 20개씩, 남는 블록은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#16','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C2',2,'sa','auto','공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":16,"concept":"M3-2-u2-C2","difficulty":2,"kind":"sa","stem":"공깃돌 70개를 주머니 한 개에 5개씩 담으려고 해요. 주머니는 몇 개 필요한가요? 숫자로 쓰세요.","answer":["14"],"explanation":["전체 공깃돌 수를 주머니 한 개에 담는 공깃돌 수로 나누어요 — 식은 70 ÷ 5.","십의 자리 7 ÷ 5 → 몫 1, 2 남음 · 남은 2를 내려 20 ÷ 5 → 몫 4.","70 ÷ 5 = 14 — 몫 14는 필요한 주머니 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#17','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C5',3,'mc','auto','몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 68 ÷ 4 ○ 56 ÷ 2',ARRAY['M3-2-u2-X15','M3-2-u2-X17']::text[],false,'{"seq":17,"concept":"M3-2-u2-C5","difficulty":3,"kind":"mc","stem":"몫의 크기를 비교하여 ○ 안에 알맞은 것을 고르세요. 68 ÷ 4 ○ 56 ÷ 2","options":[{"t":"<","correct":true},{"t":">","mis":"M3-2-u2-X15"},{"t":"=","mis":"M3-2-u2-X15"},{"t":"알 수 없어요","mis":"M3-2-u2-X17"}],"explanation":["68 ÷ 4의 몫은 17이에요.","56 ÷ 2의 몫은 28이에요.","17 < 28 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#18','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',3,'mc','auto','85 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?',ARRAY['M3-2-u2-X05','M3-2-u2-X06','M3-2-u2-X07']::text[],false,'{"seq":18,"concept":"M3-2-u2-C7","difficulty":3,"kind":"mc","stem":"85 ÷ 7의 몫과 나머지를 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"12 … 1","correct":true},{"t":"11 … 8","mis":"M3-2-u2-X05"},{"t":"1 … 12","mis":"M3-2-u2-X06"},{"t":"12","mis":"M3-2-u2-X07"}],"explanation":["높은 자리부터 차례로 나누어 몫을 그 자리 위에 써요.","십의 자리 8 ÷ 7 → 몫 1, 1 남음 · 남은 1을 내려 15 ÷ 7 → 몫 2.","85 ÷ 7 = 12 … 1 — 확인: 7 × 12 + 1 = 85예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#19','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C8',3,'ox','auto','307 ÷ 3 = 12 … 1이에요.',ARRAY['M3-2-u2-X10']::text[],false,'{"seq":19,"concept":"M3-2-u2-C8","difficulty":3,"kind":"ox","stem":"307 ÷ 3 = 12 … 1이에요.","answer":"X","reason_options":[{"t":"나눌 수 없는 자리의 몫에는 0을 써야 해서","correct":true},{"t":"0은 없어도 되는 숫자라서","mis":"M3-2-u2-X10"}],"mis":"M3-2-u2-X10","explanation":["백의 자리 3 ÷ 3 → 몫 1 · 십의 자리 0 → 몫 0 · 일의 자리 7 ÷ 3 → 몫 2.","바르게 계산하면 307 ÷ 3 = 102 … 1.","나눌 수 없으면 몫에 0 — 확인: 3 × 102 + 1 = 307이에요."],"asset":{"type":"ldiv","a":307,"b":3,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#20','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C9',3,'ox','auto','75 ÷ 2 = 36 … 3이에요.',ARRAY['M3-2-u2-X05']::text[],false,'{"seq":20,"concept":"M3-2-u2-C9","difficulty":3,"kind":"ox","stem":"75 ÷ 2 = 36 … 3이에요.","answer":"X","reason_options":[{"t":"나머지는 나누는 수보다 작아야 해서","correct":true},{"t":"나머지는 얼마든지 커도 되어서","mis":"M3-2-u2-X05"}],"mis":"M3-2-u2-X05","explanation":["십의 자리 7 ÷ 2 → 몫 3, 1 남음 · 남은 1을 내려 15 ÷ 2 → 몫 7.","바르게 계산하면 75 ÷ 2 = 37 … 1.","나머지 < 나누는 수 — 확인: 2 × 37 + 1 = 75예요."],"asset":{"type":"ldiv","a":75,"b":2,"upto":0}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#21','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C7',3,'sa','auto','태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 검은색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":21,"concept":"M3-2-u2-C7","difficulty":3,"kind":"sa","stem":"태민이 검은색 블록 687개로 똑같은 열쇠고리 5개를 만들려고 해요. 남는 블록 없이 한 개에 하나씩 더 쓰려면 검은색 블록이 적어도 몇 개 더 있어야 하나요? 숫자로 쓰세요.","answer":["3"],"explanation":["687 ÷ 5 = 137 … 2 — 한 개에 137개씩 쓰고 2개가 남아요.","한 개에 138개씩 쓰려면 5 × 138 = 690개가 필요해요.","690 − 687 = 3 — 적어도 3개 더 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#22','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',3,'sa','auto','어떤 수를 9로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":22,"concept":"M3-2-u2-C6","difficulty":3,"kind":"sa","stem":"어떤 수를 9로 나누었을 때 나머지가 될 수 있는 가장 큰 수는 무엇인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["나머지가 9가 되면 9씩 한 묶음을 더 만들 수 있어요.","그래서 나머지는 언제나 나누는 수 9보다 작아요.","가장 큰 나머지는 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#23','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C6',4,'essay','teacher','사탕 13개를 4명이 똑같이 나누어 가질 때 「한 명이 1개씩 가지고 9개가 남는다」, 「2개씩 가지고 5개가 남는다」, 「3개씩 가지고 1개가 남는다」고 말할 수 있어요. 이 가운데 나눗셈의 몫과 나머지로 알맞은 것을 고르고 까닭을 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M3-2-u2-C6","difficulty":4,"kind":"essay","stem":"사탕 13개를 4명이 똑같이 나누어 가질 때 「한 명이 1개씩 가지고 9개가 남는다」, 「2개씩 가지고 5개가 남는다」, 「3개씩 가지고 1개가 남는다」고 말할 수 있어요. 이 가운데 나눗셈의 몫과 나머지로 알맞은 것을 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 「3개씩 가지고 1개가 남는다」가 알맞다. 13 ÷ 4 = 3 … 1이다. 9개나 5개가 남으면 4명에게 더 나누어 줄 수 있으므로 나눗셈의 나머지가 될 수 없다. 나머지는 나누는 수 4보다 작아야 한다.","scoring_points":["3개씩, 1개 남음을 골랐는가","13 ÷ 4 = 3 … 1로 나타냈는가","나머지는 나누는 수보다 작아야 한다는 까닭을 썼는가"]},"explanation":["나머지 9와 5는 4보다 커서 더 나누어 줄 수 있어요.","13 ÷ 4 = 3 … 1.","나머지는 0 이상이고 나누는 수보다 작을 때 한 가지로 정해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#24','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',4,'mc','auto','「8명이 공책 240권을 똑같이 나누어 가질 때 한 명이 공책을 몇 권씩 가질 수 있나요?」 알맞은 식과 답은 어느 것인가요?',ARRAY['M3-2-u2-X20','M3-2-u2-X14','M3-2-u2-X01']::text[],false,'{"seq":24,"concept":"M3-2-u2-C10","difficulty":4,"kind":"mc","stem":"「8명이 공책 240권을 똑같이 나누어 가질 때 한 명이 공책을 몇 권씩 가질 수 있나요?」 알맞은 식과 답은 어느 것인가요?","options":[{"t":"240 ÷ 8 = 30 — 30권씩","correct":true},{"t":"8 ÷ 240 — 나눌 수 없어요","mis":"M3-2-u2-X20"},{"t":"240 × 8 = 1920 — 1920권씩","mis":"M3-2-u2-X14"},{"t":"240 ÷ 8 = 3 — 3권씩","mis":"M3-2-u2-X01"}],"explanation":["나누어지는 것은 공책 240권, 나누는 수는 사람 수 8이에요 — 문장에 나온 차례가 아니에요.","24 ÷ 8 = 3이고 240은 24의 10배 — 240 ÷ 8 = 30이에요.","확인: 8 × 30 = 240 — 한 명이 30권씩 가져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_math_u2_review_d#25','math',3,2,'u2','','tb_g3_2_math_u2_review_d','unit_review','M3-2-u2-C10',4,'essay','teacher','모둠 친구들과 독서와 줄넘기 계획표를 만들어요. 예를 들어 전체 128쪽인 책을 4주 동안 8일에 나누어 읽는다면 하루에 몇 쪽을 읽어야 하는지 구하고, 계획을 세울 때 나눗셈의 나머지는 어떻게 하면 좋을지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-2-u2-C10","difficulty":4,"kind":"essay","stem":"모둠 친구들과 독서와 줄넘기 계획표를 만들어요. 예를 들어 전체 128쪽인 책을 4주 동안 8일에 나누어 읽는다면 하루에 몇 쪽을 읽어야 하는지 구하고, 계획을 세울 때 나눗셈의 나머지는 어떻게 하면 좋을지 써 보세요.","answer_guide":{"answer":"예: 128 ÷ 8 = 16이므로 하루에 16쪽씩 읽으면 된다. 나누어떨어지지 않아 나머지가 생기면 하루에 몫만큼 읽고, 마지막 날에 남은 쪽수(나머지)를 더 읽도록 계획한다. 확인: 8 × 16 = 128.","scoring_points":["128 ÷ 8 = 16을 구했는가","나머지가 생기면 마지막 날에 더 읽는다고 썼는가","곱셈으로 확인했는가"]},"explanation":["128 ÷ 8 = 16 — 하루에 16쪽.","8 × 16 = 128 — 나누어떨어져요.","나머지가 있으면 마지막 날에 남은 쪽수까지 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
